var QUIZ_DATA = {

  "刑法·总则": [
  {q:"《中华人民共和国刑法》最近一次大规模修订的修正案是？", opts:["刑法修正案(十二)（2023）","刑法修正案(十一)","刑法修正案(十)","刑法修正案(九)"], ans:0, diff:1, exp:"刑法修正案(十二)于2023年12月29日通过，2024年3月1日起施行，主要修改行贿罪相关条款。刑法修正案(十一)于2020年通过。", chapter:"第一章 刑法概说"},
  {q:"犯罪嫌疑人在被侦查机关第一次讯问后或采取强制措施之日起，有权做什么？", opts:["聘请律师提供法律帮助","拒绝回答任何问题","自行离开","销毁证据"], ans:0, diff:1, exp:"犯罪嫌疑人在被侦查机关第一次讯问后或采取强制措施之日起，有权聘请律师为其提供法律咨询、代理申诉控告。这是刑事诉讼法赋予的基本权利，体现刑法与刑事诉讼法等程序法的衔接。", chapter:"第一章 刑法概说"},
  {q:"根据《刑法》第2条，我国刑法的任务不包括？", opts:["规定民事诉讼程序","保卫国家安全、人民民主专政政权和社会主义制度","保护公民的人身权利、民主权利和其他权利","维护社会秩序、经济秩序"], ans:0, diff:1, exp:"《刑法》第2条规定刑法的任务是保卫国家安全、人民民主专政政权和社会主义制度，保护国有、集体及公民私人财产，保护公民人身、民主等权利，维护社会秩序等。民事诉讼程序由民事诉讼法规定，不属于刑法任务。", chapter:"第一章 刑法概说"},
  {q:"按照刑法条文用语的通常含义解释刑法，属于哪种解释方法？", opts:["文理解释","体系解释","历史解释","目的解释"], ans:0, diff:2, exp:"文理解释即按条文语言文字的字面含义进行的解释，是其他解释方法的前提；体系解释强调条文在刑法体系中的地位；历史解释依据立法沿革；目的解释依据立法目的。", chapter:"第一章 刑法概说"},
  {q:"关于刑法解释，下列说法正确的是？", opts:["全国人大常委会的立法解释与两高的司法解释均具有法律效力，学理解释无法律约束力","只有学理解释具有法律约束力","立法解释没有法律效力","司法解释只对个案有效"], ans:0, diff:2, exp:"立法解释、司法解释属于有权解释（法定解释），具有普遍约束力；学理解释属于无权解释，仅供参考，无法律约束力。", chapter:"第一章 刑法概说"},
  {q:"我国刑法的基本原则不包括以下哪项？", opts:["罪刑法定原则","罪刑相适应原则","适用刑法人人平等原则","无罪推定原则"], ans:3, diff:1, exp:"我国刑法明文规定了三大基本原则：罪刑法定原则（第3条）、适用刑法人人平等原则（第4条）、罪刑相适应原则（第5条）。无罪推定是刑事诉讼法的原则。", chapter:"第二章 刑法的基本原则"},
  {q:"罪刑法定原则的派生原则不包括？", opts:["允许不利于被告人的类推解释","禁止习惯法","禁止绝对不定期刑","禁止溯及既往"], ans:0, diff:2, exp:"罪刑法定的派生原则包括：排斥习惯法、禁止类推（不利于被告人的）、禁止溯及既往（不利于被告人的）、禁止绝对不定期刑、明确性原则。", chapter:"第二章 刑法的基本原则"},
  {q:"关于罪刑相适应原则，以下哪项表述不正确？", opts:["刑罚的轻重只需考虑犯罪行为，无需考虑人身危险性","刑罚的轻重应与犯罪分子所犯罪行相适应","量刑时应做到重罪重罚、轻罪轻罚","罪刑相适应要求刑罚个别化"], ans:0, diff:1, exp:"罪刑相适应不仅要求刑罚与所犯罪行相适应，也要求考虑犯罪分子的人身危险性和再犯可能性，实现刑罚个别化。", chapter:"第二章 刑法的基本原则"},
  {q:"关于罪刑法定原则，以下表述正确的是？", opts:["法无明文规定不为罪，法无明文规定不处罚","允许类推解释","允许溯及既往","习惯法可以作为定罪依据"], ans:0, diff:1, exp:"罪刑法定原则要求：法律明文规定为犯罪的才能定罪处罚；禁止类推；禁止溯及既往（除非有利于被告人）；禁止以习惯法作为定罪依据。", chapter:"第二章 刑法的基本原则"},
  {q:"下列做法中，直接体现罪刑法定原则的是？", opts:["对法律没有明文规定的行为不以犯罪论处","对罪行严重的犯罪分子从重处罚","对未成年人犯罪从宽处罚","对累犯从重处罚"], ans:0, diff:1, exp:"罪刑法定原则要求法无明文规定不为罪、不处罚（《刑法》第3条）。B、D体现罪刑相适应或对特定主体的特别规定，C体现对未成年人的特殊保护。", chapter:"第二章 刑法的基本原则"},
  {q:"我国刑法对溯及力采取什么原则？", opts:["从旧兼从轻原则","从新原则","从旧原则","从新兼从轻原则"], ans:0, diff:2, exp:"《刑法》第12条规定，中华人民共和国成立以后本法施行以前的行为，如果当时的法律不认为是犯罪的，适用当时的法律；如果当时的法律认为是犯罪的，依照本法应当追诉的，按照当时的法律追究刑事责任，但是如果本法不认为是犯罪或者处刑较轻的，适用本法。", chapter:"第三章 刑法的效力"},
  {q:"关于刑法的空间效力，我国采取什么原则？", opts:["属地原则为主，兼采属人、保护、普遍管辖原则","仅属地原则","仅属人原则","仅保护原则"], ans:0, diff:1, exp:"我国刑法以属地管辖为基础，兼采属人管辖、保护管辖和普遍管辖原则。这体现在《刑法》第6-11条中。", chapter:"第三章 刑法的效力"},
  {q:"关于刑法的适用范围，属地管辖原则的依据是？", opts:["凡在中国领域内犯罪的，除法律有特别规定外，都适用本法","中国人无论在哪犯罪都适用本法","外国人在外国对中国犯罪适用本法","国际犯罪一律适用本法"], ans:0, diff:1, exp:"《刑法》第6条规定了属地管辖：凡在中国领域内犯罪的，除法律有特别规定外，都适用本法。领域包括领陆、领水、领空，以及中国船舶和航空器。", chapter:"第三章 刑法的效力"},
  {q:"我国公民在中华人民共和国领域外犯本法规定之罪的，如何适用我国刑法？", opts:["适用本法，但按本法规定最高刑为3年以下有期徒刑的，可以不予追究","一律不适用我国刑法","一律适用我国刑法，无任何例外","只适用犯罪地的法律"], ans:0, diff:2, exp:"《刑法》第7条属人管辖：中华人民共和国公民在领域外犯本法规定之罪的，适用本法，但按本法规定的最高刑为3年以下有期徒刑的，可以不予追究；国家工作人员和军人不受此限，一律适用本法。", chapter:"第三章 刑法的效力"},
  {q:"外国人在中华人民共和国领域外对中国国家或者公民犯罪，我国刑法能否适用？", opts:["按本法规定最低刑为3年以上有期徒刑的，可以适用，但按犯罪地法律不受处罚的除外","只要侵害中国利益就一律适用","一律不能适用","只能由国际法院管辖"], ans:0, diff:3, exp:"《刑法》第8条保护管辖：外国人在领域外对中国国家或公民犯罪，按本法规定最低刑为3年以上有期徒刑的，可以适用本法，但按犯罪地法律不受处罚的除外。两个限制条件缺一不可。", chapter:"第三章 刑法的效力"},
  {q:"犯罪的社会危害性、刑事违法性、应受刑罚处罚性三个基本特征中，最本质的特征是？", opts:["严重的社会危害性","刑事违法性","应受刑罚处罚性","形式的违法性"], ans:0, diff:1, exp:"严重的社会危害性是犯罪的本质特征，是刑事违法性和应受刑罚处罚性的基础；刑事违法性是法律形式，应受刑罚处罚性是法律后果。", chapter:"第四章 犯罪概念与犯罪构成"},
  {q:"犯罪概念与犯罪构成的关系，下列说法正确的是？", opts:["犯罪概念是犯罪构成的基础，犯罪构成是犯罪概念的具体化","犯罪概念回答'具备哪些要件才成立犯罪'","二者完全相同","犯罪构成只适用于分则具体罪名"], ans:0, diff:2, exp:"犯罪概念从总体上回答什么是犯罪（三特征），犯罪构成则是认定犯罪的具体规格和标准，是犯罪概念的具体化。总则规定的一般构成对分则各罪均适用。", chapter:"第四章 犯罪概念与犯罪构成"},
  {q:"根据我国刑法理论通说，犯罪构成的四个要件不包括？", opts:["犯罪对象","犯罪主体","犯罪客观方面","犯罪主观方面"], ans:0, diff:1, exp:"通说'四要件说'为犯罪客体、犯罪客观方面、犯罪主体、犯罪主观方面。犯罪对象是犯罪客体的具体表现，不是独立要件。", chapter:"第四章 犯罪概念与犯罪构成"},
  {q:"以犯罪既遂为标准规定的构成要件，称为？", opts:["基本的犯罪构成","修正的犯罪构成","简单的犯罪构成","复杂的犯罪构成"], ans:0, diff:3, exp:"基本的犯罪构成指刑法分则条文就某一犯罪既遂形态所规定的基本构成要件；修正的犯罪构成指在基本构成基础上，依据预备、未遂、中止及共同犯罪形态修正形成的构成要件。", chapter:"第四章 犯罪概念与犯罪构成"},
  {q:"根据《刑法》第13条'但书'，情节显著轻微危害不大的行为，应如何处理？", opts:["不认为是犯罪","构成犯罪但免除处罚","构成犯罪但减轻处罚","构成犯罪但宣告缓刑"], ans:0, diff:1, exp:"《刑法》第13条但书规定情节显著轻微危害不大的不认为是犯罪，体现了犯罪概念的定量因素，使刑法处罚范围受到合理限制。", chapter:"第四章 犯罪概念与犯罪构成"},
  {q:"犯罪客体是指？", opts:["刑法所保护而为犯罪行为所侵犯的社会关系","犯罪行为直接作用的具体的人或物","犯罪行为指向的对象","犯罪行为造成的损害结果"], ans:0, diff:1, exp:"犯罪客体是刑法所保护的、为犯罪行为所侵犯的社会主义社会关系，是犯罪构成的基本要件之一，决定犯罪的性质和分类。", chapter:"第五章 犯罪客体"},
  {q:"关于犯罪客体与犯罪对象的关系，下列说法正确的是？", opts:["犯罪对象是犯罪客体的物质表现，犯罪客体决定犯罪性质，且并非一切犯罪都有犯罪对象","二者是同一概念","任何犯罪都有犯罪对象","犯罪对象决定犯罪性质"], ans:0, diff:3, exp:"犯罪对象是犯罪行为直接作用的具体的人或物，是犯罪客体的表现形式；犯罪客体才是决定犯罪性质的要素。某些犯罪（如脱逃罪、组织类犯罪）没有具体犯罪对象。", chapter:"第五章 犯罪客体"},
  {q:"我国刑法分则划分章节（同类犯罪）的主要依据是？", opts:["犯罪的同类客体","犯罪的直接客体","犯罪的一般客体","犯罪对象的性质"], ans:0, diff:2, exp:"刑法分则依据同类客体把犯罪划分为十大类（如危害国家安全罪、侵犯财产罪等），作为分则体系划分依据；直接客体是具体罪名归类的关键，一般客体则是一切犯罪共同侵犯的整体社会关系。", chapter:"第五章 犯罪客体"},
  {q:"抢劫罪侵犯的客体属于？", opts:["复杂客体，既侵犯财产权利又侵犯人身权利","简单客体，仅侵犯财产权利","简单客体，仅侵犯人身权利","同类客体中的公共安全"], ans:0, diff:1, exp:"抢劫罪通过暴力、胁迫等手段当场劫取财物，同时侵犯财产权利和人身权利，是典型复杂客体，故被归类于分则第五章侵犯财产罪。", chapter:"第五章 犯罪客体"},
  {q:"犯罪的一般客体是指？", opts:["一切犯罪行为共同侵犯的、刑法所保护的社会关系的整体","某一类犯罪共同侵犯的社会关系","具体犯罪直接侵犯的社会关系","犯罪对象的总和"], ans:0, diff:2, exp:"一般客体是一切犯罪共同侵犯的刑法所保护的社会关系的整体，体现犯罪的共同本质；同类客体是某一类犯罪共同侵犯的社会关系；直接客体是具体犯罪直接侵犯的社会关系。", chapter:"第五章 犯罪客体"},
  {q:"犯罪构成四要件中，犯罪客观方面不包括？", opts:["犯罪动机","危害行为","危害结果","因果关系"], ans:0, diff:1, exp:"犯罪客观方面包括危害行为、危害结果、因果关系等。犯罪动机属于犯罪主观方面的内容。", chapter:"第六章 犯罪客观方面"},
  {q:"不作为犯罪中'作为义务'的来源不包括？", opts:["道德义务","法律明文规定的义务","职务或业务要求的义务","先行行为引起的义务"], ans:0, diff:2, exp:"不作为犯罪的作为义务来源于：法律明文规定、职务或业务要求、法律行为（合同等）引起的义务、先行行为引起的义务。单纯道德义务不产生刑法上的作为义务。", chapter:"第六章 犯罪客观方面"},
  {q:"关于因果关系中的'介入因素'理论，以下哪项正确？", opts:["异常介入因素可能中断因果关系","介入因素不影响因果关系","所有介入因素都中断因果关系","因果关系与介入因素无关"], ans:0, diff:3, exp:"当介入因素异常且对结果起到决定性作用时，可能中断原来的因果关系。需要考虑介入因素是否由先行行为所引起、是否异常、对结果的贡献大小。", chapter:"第六章 犯罪客观方面"},
  {q:"母亲因不愿抚养而故意不给婴儿哺乳，致使婴儿死亡，该行为属于？", opts:["以不作为方式实施的不纯正不作为犯，可能构成故意杀人罪","纯正不作为犯，只能构成遗弃罪","作为犯","迷信犯"], ans:0, diff:3, exp:"遗弃罪是纯正不作为犯（只能由不作为构成）；而不给哺乳致婴儿死亡，是以不作为方式实施通常由作为构成的故意杀人罪，属于不纯正不作为犯，是否构成故意杀人罪还须判断其主观故意。", chapter:"第六章 犯罪客观方面"},
  {q:"只要实施了刑法分则规定的行为即告既遂，不要求发生危害结果的犯罪是？", opts:["行为犯","结果犯","危险犯","实害犯"], ans:0, diff:1, exp:"行为犯以行为的完成为既遂标准（如脱逃罪）；结果犯要求发生法定危害结果（如故意杀人致人死亡）；危险犯要求造成具体危险（如放火罪）。", chapter:"第六章 犯罪客观方面"},
  {q:"我国刑法规定的完全负刑事责任的年龄是多少？", opts:["16周岁","14周岁","18周岁","12周岁"], ans:0, diff:1, exp:"《刑法》第17条规定，已满16周岁的人犯罪，应当负刑事责任。已满14周岁不满16周岁的人，仅对八种严重犯罪负刑事责任。", chapter:"第七章 犯罪主体"},
  {q:"已满14周岁不满16周岁的人，对以下哪种行为需要负刑事责任？", opts:["故意杀人","盗窃","诈骗","抢夺"], ans:0, diff:2, exp:"《刑法》第17条第2款规定，已满14不满16周岁的人，对故意杀人、故意伤害致人重伤或死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质八种犯罪负刑事责任。", chapter:"第七章 犯罪主体"},
  {q:"已满多少周岁不满18周岁的人犯罪，应当从轻或者减轻处罚？", opts:["14周岁","16周岁","12周岁","18周岁"], ans:0, diff:1, exp:"《刑法》第17条第3款规定，已满14周岁不满18周岁的人犯罪，应当从轻或者减轻处罚。注意'应当'是强制性规定。", chapter:"第七章 犯罪主体"},
  {q:"关于刑事责任年龄的降低，刑法修正案(十一)规定已满多少周岁的人对特定严重犯罪负刑事责任？", opts:["12周岁","10周岁","13周岁","14周岁"], ans:0, diff:2, exp:"《刑法》第17条第3款（修正案十一新增）：已满12周岁不满14周岁的人，犯故意杀人、故意伤害罪致人死亡或以特别残忍手段致人重伤造成严重残疾，情节恶劣，经最高人民检察院核准追诉的，应负刑事责任。", chapter:"第七章 犯罪主体"},
  {q:"精神病人犯罪的责任能力如何认定？", opts:["不能辨认或不能控制自己行为时不负刑事责任","一律不负刑事责任","减轻处罚","从轻处罚"], ans:0, diff:2, exp:"《刑法》第18条规定，精神病人在不能辨认或者不能控制自己行为的时候造成危害结果，经法定程序鉴定确认的，不负刑事责任。间歇性精神病人在精神正常时犯罪应负刑事责任。", chapter:"第七章 犯罪主体"},
  {q:"醉酒的人犯罪，应如何承担刑事责任？", opts:["应当负刑事责任","不负刑事责任","减轻处罚","从轻处罚"], ans:0, diff:1, exp:"《刑法》第18条第4款明确规定，醉酒的人犯罪，应当负刑事责任。醉酒不能作为免责或减责事由。", chapter:"第七章 犯罪主体"},
  {q:"关于又聋又哑的人或者盲人犯罪，以下说法正确的是？", opts:["可以从轻、减轻或者免除处罚","不负刑事责任","应当从轻处罚","与正常人同等对待"], ans:0, diff:2, exp:"《刑法》第19条规定，又聋又哑的人或者盲人犯罪，可以从轻、减轻或者免除处罚。注意是'可以'而非'应当'。", chapter:"第七章 犯罪主体"},
  {q:"单位犯罪的双罚制是指？", opts:["对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚","仅对单位判处罚金","仅对责任人判处刑罚","对单位判处罚金或对责任人判处刑罚择一"], ans:0, diff:2, exp:"《刑法》第31条规定，单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。这是'双罚制'原则。单位犯罪是犯罪主体的特殊形态。", chapter:"第七章 犯罪主体"},
  {q:"犯罪主观方面的'故意'分为哪两种？", opts:["直接故意和间接故意","一般故意和特殊故意","事前故意和事后故意","确定故意和不确定故意"], ans:0, diff:1, exp:"《刑法》第14条规定，明知自己的行为会发生危害社会的结果，并且希望（直接故意）或者放任（间接故意）这种结果发生的，是故意犯罪。", chapter:"第八章 犯罪主观方面"},
  {q:"过于自信的过失与间接故意的主要区别是什么？", opts:["对危害结果的态度不同：过于自信的过失是轻信能够避免，间接故意是放任","认识因素不同","主体不同","客体不同"], ans:0, diff:3, exp:"两者的关键区别在于意志因素：过于自信的过失中行为人排斥结果发生、轻信能够避免；间接故意中行为人对结果持放任态度，发生与否都不违背本意。", chapter:"第八章 犯罪主观方面"},
  {q:"以下哪种情形属于疏忽大意的过失？", opts:["应当预见但未预见","已经预见但轻信能避免","明知会发生而希望","明知会可能发生而放任"], ans:0, diff:1, exp:"疏忽大意的过失是指行为人应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见。已预见但轻信能避免是过于自信的过失。", chapter:"第八章 犯罪主观方面"},
  {q:"意外事件与疏忽大意过失的区分关键是什么？", opts:["行为人是否应当预见并能预见危害结果","是否造成损害","行为方式是否相同","主体是否相同"], ans:0, diff:3, exp:"《刑法》第16条规定，行为在客观上虽然造成了损害结果，但不是出于故意或过失，而是由于不能抗拒或不能预见的原因所引起的，不是犯罪。关键在于预见能力和预见义务。", chapter:"第八章 犯罪主观方面"},
  {q:"犯罪目的与犯罪动机的区别是什么？", opts:["目的是行为人希望通过犯罪行为达到的结果，动机是推动实施犯罪行为的内心起因","目的是动机，动机是目的","两者完全相同","动机可以决定犯罪性质"], ans:0, diff:2, exp:"犯罪目的是行为人希望通过实施犯罪行为达到的危害结果；犯罪动机是推动行为人实施犯罪行为的内心起因。例如：杀人的目的是剥夺他人生命，动机可能是报复、图财等。", chapter:"第八章 犯罪主观方面"},
  {q:"事实认识错误中的'对象错误'，以下哪种处理正确？", opts:["对象错误一般不影响故意犯罪的成立（法定符合说）","对象错误一律不构成犯罪","对象错误导致犯罪不成立","对象错误不按犯罪处理"], ans:0, diff:3, exp:"根据法定符合说，如果行为人意图侵害的对象与实际侵害的对象属于同一犯罪构成范围内的对象，对象错误不影响故意犯罪的成立。如想杀甲却杀死乙，仍构成故意杀人罪。", chapter:"第八章 犯罪主观方面"},
  {q:"正当防卫的时间条件是？", opts:["不法侵害正在进行","不法侵害已经结束","不法侵害尚未开始","任何时间"], ans:0, diff:1, exp:"正当防卫必须是针对正在进行的不法侵害。不法侵害尚未开始或已经结束后的'防卫'属于防卫不适时，可能构成犯罪。", chapter:"第九章 正当行为"},
  {q:"以下哪种情形不属于正当防卫？", opts:["互相斗殴中的反击行为","对正在进行的抢劫行为的反抗","对正在进行的故意伤害行为的反抗","对正在进行的强奸行为的反抗"], ans:0, diff:2, exp:"互相斗殴中双方均有侵害对方的故意，不属于正当防卫。但一方已停止斗殴或放弃斗殴，另一方继续侵害的，可以成立正当防卫。", chapter:"第九章 正当行为"},
  {q:"特殊防卫（无限防卫）适用于哪种情形？", opts:["严重危及人身安全的暴力犯罪","所有犯罪","财产犯罪","过失犯罪"], ans:0, diff:1, exp:"《刑法》第20条第3款规定，对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，采取防卫行为造成不法侵害人伤亡的，不属于防卫过当，不负刑事责任。", chapter:"第九章 正当行为"},
  {q:"紧急避险与正当防卫的主要区别不包括？", opts:["两者都可以针对不法侵害人","紧急避险针对的是危险来源（含自然力），正当防卫针对不法侵害","紧急避险损害的是第三者的合法权益","紧急避险要求避险限度更严格"], ans:0, diff:3, exp:"紧急避险是损害第三者的合法权益来避免危险；正当防卫是直接对抗不法侵害人。紧急避险不能针对不法侵害人，这是两者的根本区别之一。", chapter:"第九章 正当行为"},
  {q:"关于防卫过当，下列说法正确的是？", opts:["明显超过必要限度造成重大损害的，应当负刑事责任，但应当减轻或者免除处罚","防卫过当不负刑事责任","造成不法侵害人伤亡的一律构成防卫过当","防卫过当一律按故意犯罪论处"], ans:0, diff:2, exp:"《刑法》第20条第2款：正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但应当减轻或者免除处罚。防卫过当以正当防卫成立的前提要件为基础，主观上多为过失或间接故意。", chapter:"第九章 正当行为"},
  {q:"犯罪预备与犯意表示的区别是什么？", opts:["犯罪预备是行为，犯意表示仅是思想流露","两者完全相同","犯意表示是行为","犯罪预备是思想活动"], ans:0, diff:2, exp:"犯罪预备是行为人为实施犯罪准备工具、制造条件的行为（如购买凶器、踩点），具有可罚性。犯意表示仅是口头或书面表达犯罪意图，没有实际行动。", chapter:"第十章 故意犯罪的停止形态"},
  {q:"犯罪未遂与犯罪预备的时间分界点是什么？", opts:["是否已经着手实行犯罪","是否准备了工具","是否制造了条件","是否有犯罪意图"], ans:0, diff:1, exp:"犯罪预备是在着手实行犯罪前的准备阶段；犯罪未遂是已经着手实行犯罪但未得逞。'着手'是区分预备和未遂的关键时间节点。", chapter:"第十章 故意犯罪的停止形态"},
  {q:"犯罪中止与犯罪未遂的核心区别是？", opts:["中止是自动放弃，未遂是意志以外原因被迫停止","中止是未完成犯罪，未遂是完成犯罪","中止发生在预备阶段，未遂发生在实行阶段","两者没有区别"], ans:0, diff:1, exp:"《刑法》第24条规定，犯罪中止是自动放弃犯罪或自动有效防止结果发生。犯罪未遂是因意志以外的原因未能得逞。'自动性'是核心区分标准。", chapter:"第十章 故意犯罪的停止形态"},
  {q:"对于中止犯，没有造成损害的，应如何处理？", opts:["应当免除处罚","可以免除处罚","应当减轻处罚","可以从轻处罚"], ans:0, diff:1, exp:"《刑法》第24条第2款规定，对于中止犯，没有造成损害的，应当免除处罚；造成损害的，应当减轻处罚。", chapter:"第十章 故意犯罪的停止形态"},
  {q:"对于未遂犯，可以如何处理处罚？", opts:["可以从轻或者减轻处罚","应当免除处罚","应当减轻处罚","不予处罚"], ans:0, diff:1, exp:"《刑法》第23条第2款规定，对于未遂犯，可以比照既遂犯从轻或者减轻处罚。注意是'可以'而非'应当'。", chapter:"第十章 故意犯罪的停止形态"},
  {q:"手段不能犯与迷信犯的区别是什么？", opts:["手段不能犯可能构成未遂犯，迷信犯不为罪","两者都可构成犯罪","两者都不构成犯罪","两者没有任何区别"], ans:0, diff:3, exp:"手段不能犯是指行为人使用的犯罪方法在客观上不可能达到既遂（如误将白糖当砒霜投毒），可能构成犯罪未遂（如属绝对不能则不罚）。迷信犯是指采取超自然方法（如诅咒），因不可能产生危害结果而不为罪。", chapter:"第十章 故意犯罪的停止形态"},
  {q:"共同犯罪的主体要件要求几人以上？", opts:["二人以上","三人以上","一人以上","五人以上"], ans:0, diff:1, exp:"《刑法》第25条规定，共同犯罪是指二人以上共同故意犯罪。二人以上共同过失犯罪的，不以共同犯罪论处。", chapter:"第十一章 共同犯罪"},
  {q:"以下哪种人不构成共同犯罪？", opts:["二人以上共同过失犯罪","二人以上共同故意犯罪","事前通谋的共同犯罪","事中通谋的共同犯罪"], ans:0, diff:1, exp:"《刑法》第25条第2款规定，二人以上共同过失犯罪，不以共同犯罪论处；应当负刑事责任的，按照他们所犯的罪分别处罚。", chapter:"第十一章 共同犯罪"},
  {q:"主犯和首要分子的关系，以下哪项正确？", opts:["首要分子是主犯的一种，但犯罪集团的首要分子按集团所犯全部罪行处罚","首要分子不一定是从犯","主犯不一定是首要分子","以上都对"], ans:3, diff:3, exp:"首要分子是主犯的一种特殊类型。犯罪集团的首要分子对集团所犯全部罪行负责。聚众犯罪中不一定有主犯。选项D'以上都对'是正确的。", chapter:"第十一章 共同犯罪"},
  {q:"关于教唆犯，以下说法正确的是？", opts:["教唆他人犯罪的，应按他在共同犯罪中所起的作用处罚","教唆犯一律按主犯处罚","教唆不满14周岁的人犯罪不负刑事责任","教唆未遂的，不处罚"], ans:0, diff:2, exp:"《刑法》第29条规定，教唆他人犯罪的，应按他在共同犯罪中所起作用处罚。教唆不满18周岁的人犯罪应从重处罚。教唆未遂的，可以从轻或减轻处罚。", chapter:"第十一章 共同犯罪"},
  {q:"胁从犯是指什么？", opts:["被胁迫参加犯罪的人","主动参加犯罪的人","组织犯罪的人","教唆犯罪的人"], ans:0, diff:1, exp:"《刑法》第28条规定，对于被胁迫参加犯罪的，应当按照他的犯罪情节减轻处罚或者免除处罚。胁从犯主观上不愿意犯罪但因受到威胁而参与。", chapter:"第十一章 共同犯罪"},
  {q:"犯罪集团的首要分子对哪些犯罪承担责任？", opts:["集团所犯的全部罪行","仅自己实施和策划的犯罪","集团所有成员的犯罪","仅自己实施的犯罪"], ans:0, diff:1, exp:"《刑法》第26条第3款规定，对组织、领导犯罪集团的首要分子，按照集团所犯的全部罪行处罚。这与一般主犯按其所参与或组织指挥的全部犯罪处罚不同。", chapter:"第十一章 共同犯罪"},
  {q:"结果加重犯的成立条件不包括？", opts:["行为人对加重结果必须具有直接故意","基本犯罪行为与加重结果之间具有因果关系","基本犯罪已经构成","刑法对加重结果规定了更重的法定刑"], ans:0, diff:3, exp:"结果加重犯要求行为人对加重结果至少存在过失。如果对加重结果有故意则可能构成其他犯罪。结果加重犯不要求对加重结果有直接故意，有过失即可。", chapter:"第十二章 罪数"},
  {q:"牵连犯的处理原则是？", opts:["从一重罪处罚（法律有特别规定的除外）","数罪并罚","从一轻罪处罚","吸收原则"], ans:0, diff:2, exp:"牵连犯是指以实施某一犯罪为目的，其方法行为或结果行为又触犯其他罪名的形态。通常从一重罪处罚，但法律明确规定数罪并罚的除外（如以暴力抗拒缉私的）。", chapter:"第十二章 罪数"},
  {q:"关于想象竞合犯，以下哪项正确？", opts:["一行为触犯数罪名，从一重罪处罚","数行为触犯数罪名","一行为只触犯一罪名","从轻处罚"], ans:0, diff:2, exp:"想象竞合犯是指一个行为同时触犯数个罪名。处理原则是从一重罪处罚。不同于数罪并罚，因为只有一个行为。", chapter:"第十二章 罪数"},
  {q:"关于吸收犯，下列说法正确的是？", opts:["数个行为之间存在吸收关系，重行为吸收轻行为，按一罪处罚","数行为一律数罪并罚","一个行为触犯数个罪名","与牵连犯完全相同"], ans:0, diff:3, exp:"吸收犯指数个犯罪行为之间存在吸收关系（如既遂吸收预备、主行为吸收从行为），只按吸收后的一罪处罚；牵连犯则基于手段与目的、原因与结果的牵连关系处理，二者不同。", chapter:"第十二章 罪数"},
  {q:"一行为同时符合普通法与特别法规定的犯罪构成时，一般应如何处理？", opts:["适用特别法优于普通法原则","一律数罪并罚","从一重罪处罚","从一轻罪处罚"], ans:0, diff:3, exp:"法条竞合（法规竞合）时一般适用特别法优于普通法（如诈骗罪与合同诈骗罪、金融诈骗罪等），个别情形司法解释另有规定时依其规定处理。", chapter:"第十二章 罪数"},
  {q:"刑事责任在本质上是？", opts:["因实施犯罪行为而产生的否定性法律评价和刑事法律负担","一种民事赔偿义务","一种行政处罚责任","一种道德谴责"], ans:0, diff:1, exp:"刑事责任是行为人因实施犯罪行为而依法承担的、由国家强制力保证的否定性评价和刑事法律负担，区别于民事责任和行政责任。", chapter:"第十三章 刑事责任"},
  {q:"行为人承担刑事责任的根据（通说）是？", opts:["实施了符合犯罪构成要件的行为，犯罪构成是刑事责任的唯一根据","只要造成损害结果","只要达到刑事责任年龄","只要被司法机关立案"], ans:0, diff:2, exp:"通说认为犯罪构成是认定行为人负刑事责任的唯一根据，其实质是主客观相统一的严重危害社会的犯罪行为；损害结果、责任年龄仅是成立犯罪的部分条件。", chapter:"第十三章 刑事责任"},
  {q:"关于刑事责任与刑罚的关系，下列说法正确的是？", opts:["刑事责任是刑罚适用的前提，刑罚是刑事责任的主要实现方式，二者不能等同","刑事责任与刑罚完全相同","刑罚可以脱离刑事责任单独存在","追究刑事责任必然判处刑罚"], ans:0, diff:3, exp:"刑事责任是因犯罪产生的法律后果，刑罚是实现刑事责任的主要方式，但并非唯一方式：符合条件可免予刑事处罚而采用非刑罚处理方法，故追究刑事责任不一定判处刑罚。", chapter:"第十三章 刑事责任"},
  {q:"根据《刑法》第37条，对于犯罪情节轻微不需要判处刑罚的，人民法院可以？", opts:["免予刑事处罚，并可根据情况予以训诫、责令具结悔过、赔礼道歉、赔偿损失或交由主管部门处理","仍然必须判处刑罚","宣告无罪","直接撤销案件"], ans:0, diff:2, exp:"《刑法》第37条：对于犯罪情节轻微不需要判处刑罚的，可以免予刑事处罚，但可以根据案件的不同情况，予以训诫或者责令具结悔过、赔礼道歉、赔偿损失，或者由主管部门予以行政处罚或者行政处分。", chapter:"第十三章 刑事责任"},
  {q:"下列情形中，不属于刑事责任消灭原因的是？", opts:["行为人犯罪后态度良好","刑罚执行完毕","追诉时效经过","犯罪嫌疑人、被告人死亡"], ans:0, diff:1, exp:"刑事责任的消灭（终止）原因主要包括刑罚执行完毕、追诉时效经过、赦免以及犯罪嫌疑人、被告人死亡等；犯罪后态度良好只能影响量刑，不导致责任消灭。", chapter:"第十三章 刑事责任"},
  {q:"我国刑法中主刑的种类不包括以下哪项？", opts:["罚金","管制","拘役","死刑"], ans:0, diff:1, exp:"《刑法》第33条规定，主刑包括：管制、拘役、有期徒刑、无期徒刑、死刑。罚金是附加刑（《刑法》第34条）。", chapter:"第十四章 刑罚及其种类"},
  {q:"管制的期限是多少？", opts:["3个月以上2年以下","1年以上3年以下","6个月以上1年以下","1年以上5年以下"], ans:0, diff:1, exp:"《刑法》第38条规定，管制的期限为3个月以上2年以下。管制是我国独创的主刑，不剥夺人身自由但限制一定自由。", chapter:"第十四章 刑罚及其种类"},
  {q:"拘役的期限是多少？", opts:["1个月以上6个月以下","3个月以上1年以下","6个月以上2年以下","1个月以上1年以下"], ans:0, diff:1, exp:"《刑法》第42条规定，拘役的期限为1个月以上6个月以下。拘役由公安机关就近执行，是一种短期剥夺人身自由的刑罚。", chapter:"第十四章 刑罚及其种类"},
  {q:"有期徒刑的期限是多少？", opts:["6个月以上15年以下","1年以上10年以下","3年以上20年以下","1年以上15年以下"], ans:0, diff:2, exp:"《刑法》第45条规定，有期徒刑的期限为6个月以上15年以下。数罪并罚时最高不超过25年（总合刑期不满35年的，最高不超过20年）。", chapter:"第十四章 刑罚及其种类"},
  {q:"关于死刑的适用，以下哪项正确？", opts:["犯罪时不满18周岁的人不适用死刑","审判时怀孕的妇女可以适用死刑","已满75周岁的人一律不适用死刑","死刑立即执行和死缓没有区别"], ans:0, diff:2, exp:"《刑法》第49条规定，犯罪时不满18周岁的人和审判时怀孕的妇女不适用死刑。审判时已满75周岁的人不适用死刑，但以特别残忍手段致人死亡的除外。", chapter:"第十四章 刑罚及其种类"},
  {q:"死缓二年期满后，如果没有故意犯罪，应如何处理？", opts:["减为无期徒刑","执行死刑","释放","继续考察"], ans:0, diff:2, exp:"《刑法》第50条规定，判处死刑缓期执行的，在缓期执行期间如果没有故意犯罪，二年期满后减为无期徒刑；如有重大立功表现，减为25年有期徒刑；如故意犯罪情节恶劣，报请最高法核准执行死刑。", chapter:"第十四章 刑罚及其种类"},
  {q:"以下哪项属于附加刑？", opts:["剥夺政治权利","拘役","管制","有期徒刑"], ans:0, diff:1, exp:"《刑法》第34条规定，附加刑包括罚金、剥夺政治权利、没收财产。附加刑也可以独立适用。驱逐出境适用于犯罪的外国人（第35条）。", chapter:"第十四章 刑罚及其种类"},
  {q:"附加刑中的'剥夺政治权利'不包括剥夺什么权利？", opts:["劳动权","选举权和被选举权","言论、出版等自由权利","担任国家机关职务的权利"], ans:0, diff:1, exp:"《刑法》第54条规定，剥夺政治权利包括：选举权和被选举权；言论、出版、集会、结社、游行、示威自由的权利；担任国家机关职务的权利；担任国有企业、事业单位、人民团体领导职务的权利。", chapter:"第十四章 刑罚及其种类"},
  {q:"累犯的构成条件不包括？", opts:["前后两罪均为过失犯罪","前后两罪均为故意犯罪","前罪被判处有期徒刑以上刑罚","后罪发生在前罪刑罚执行完毕或赦免后5年内"], ans:0, diff:2, exp:"累犯要求前后两罪均为故意犯罪，过失犯罪不构成累犯。一般累犯的时间条件是5年内。特殊累犯（危害国家安全、恐怖活动、黑社会性质组织等）无时间限制。", chapter:"第十五章 刑罚制度"},
  {q:"关于自首，以下说法正确的是？", opts:["自动投案并如实供述自己罪行的，是自首","被抓获后如实供述不可构成自首","自首不能减轻处罚","自首只适用于轻罪"], ans:0, diff:1, exp:"《刑法》第67条规定，犯罪以后自动投案，如实供述自己的罪行的，是自首。被采取强制措施后如实供述司法机关还未掌握的本人其他罪行的，以自首论。自首可以从轻或减轻处罚。", chapter:"第十五章 刑罚制度"},
  {q:"关于立功，以下说法正确的是？", opts:["犯罪分子揭发他人犯罪行为查证属实的构成立功","只有重大立功才可以从轻处罚","自首和立功不能同时认定","坦白和立功效果完全相同"], ans:0, diff:2, exp:"《刑法》第68条规定，犯罪分子揭发他人犯罪行为查证属实或提供重要线索从而侦破其他案件的，构成立功。一般立功可以从轻或减轻处罚；重大立功可以减轻或免除处罚。", chapter:"第十五章 刑罚制度"},
  {q:"关于缓刑的适用条件，以下哪项错误？", opts:["被判处无期徒刑的犯罪分子可以适用缓刑","被判处拘役或3年以下有期徒刑","犯罪情节较轻","有悔罪表现且无再犯危险"], ans:0, diff:2, exp:"缓刑仅适用于被判处拘役或3年以下有期徒刑的犯罪分子。无期徒刑不能适用缓刑。缓刑还需满足：犯罪情节较轻、有悔罪表现、无再犯危险、对社区无重大不良影响。", chapter:"第十五章 刑罚制度"},
  {q:"缓刑考验期内犯新罪的，应如何处理？", opts:["撤销缓刑，数罪并罚","延长考验期","仅处罚新罪","维持缓刑"], ans:0, diff:2, exp:"《刑法》第77条规定，缓刑考验期内犯新罪或发现漏罪的，应撤销缓刑，对新罪或漏罪作出判决，把前罪和后罪所判处的刑罚进行数罪并罚。", chapter:"第十五章 刑罚制度"},
  {q:"减刑以后实际执行的刑期，判处有期徒刑的不能少于？", opts:["原判刑期的二分之一","原判刑期的三分之一","原判刑期的三分之二","原判刑期的四分之一"], ans:0, diff:2, exp:"《刑法》第78条规定，减刑后实际执行的刑期：管制、拘役、有期徒刑不能少于原判刑期的二分之一；无期徒刑不能少于13年（死缓减为无期的不能少于25年）。", chapter:"第十五章 刑罚制度"},
  {q:"我国刑法规定的最长追诉时效是多少年？", opts:["20年","10年","15年","25年"], ans:0, diff:1, exp:"《刑法》第87条规定，法定最高刑为无期徒刑、死刑的，追诉时效为20年。如果20年后认为必须追诉，须报请最高人民检察院核准。", chapter:"第十五章 刑罚制度"},
  {q:"追诉时效从什么时候起算？", opts:["犯罪之日起","立案之日起","起诉之日起","判决之日起"], ans:0, diff:1, exp:"《刑法》第89条规定，追诉期限从犯罪之日起计算；犯罪行为有连续或继续状态的，从行为终了之日起计算。", chapter:"第十五章 刑罚制度"},
  {q:"下列哪种情况追诉时效中断？", opts:["在追诉期限内又犯罪的","被害人提出控告的","公安机关立案的","嫌疑人被通缉的"], ans:0, diff:2, exp:"《刑法》第89条第2款规定，在追诉期限以内又犯罪的，前罪追诉的期限从犯后罪之日起计算。这是追诉时效的中断。", chapter:"第十五章 刑罚制度"},
  {q:"关于数罪并罚的限制加重原则，有期徒刑总和刑期不满35年的，最高刑期不超过？", opts:["20年","25年","15年","30年"], ans:0, diff:2, exp:"《刑法》第69条规定，有期徒刑总和刑期不满35年的，最高不能超过20年；总和刑期在35年以上的，最高不能超过25年。", chapter:"第十五章 刑罚制度"},
  {q:"关于减刑的适用对象，以下哪项正确？", opts:["被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子","仅限被判处有期徒刑的","被判处死刑立即执行的","仅限被判处无期徒刑的"], ans:0, diff:1, exp:"《刑法》第78条规定，减刑适用于被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子。死刑缓期执行的减刑另有规定。减刑后实际执行刑期不得低于法定最低限度。", chapter:"第十五章 刑罚制度"},
  {q:"假释的适用条件不包括？", opts:["犯罪分子服刑期间表现良好即可，无需达到一定刑期","被判处有期徒刑的，执行原判刑期二分之一以上","被判处无期徒刑的，实际执行13年以上","认真遵守监规、接受教育改造、确有悔改表现、无再犯危险"], ans:0, diff:2, exp:"假释有刑期条件：有期徒刑需执行原判二分之一以上，无期徒刑需实际执行13年以上。特殊情况下经最高法核准可不受上述刑期限制。", chapter:"第十五章 刑罚制度"}
],

  "刑法·分则": [
  {q:"刑法分则条文的基本结构通常是指？", opts:["罪状和法定刑","罪名和刑种","构成要件和主刑","总则和分则"], ans:0, diff:1, exp:"刑法分则条文的基本结构由罪状与法定刑两部分构成。罪状描述具体犯罪的构成特征，法定刑规定该罪的刑罚种类和幅度。", chapter:"第一章 刑法各论概述"},
  {q:"《刑法》第232条规定'故意杀人的'，该罪状属于何种罪状？", opts:["简单罪状","叙明罪状","引证罪状","空白罪状"], ans:0, diff:2, exp:"简单罪状只在条文中表述罪名而不具体描述构成要件，如'故意杀人的'。叙明罪状则在条文中详细描述犯罪构成要件。", chapter:"第一章 刑法各论概述"},
  {q:"交通肇事罪的罪状表述为'违反交通运输管理法规'，需参照相关行政法规确定其构成要件，该罪状属于？", opts:["空白罪状","简单罪状","叙明罪状","引证罪状"], ans:0, diff:2, exp:"空白罪状指条文未直接规定犯罪构成要件，需参照其他法律、法规加以确定。交通肇事罪须结合《道路交通安全法》等行政法规认定其违反性。", chapter:"第一章 刑法各论概述"},
  {q:"《刑法》第240条规定拐卖妇女、儿童罪时，对'拐卖'行为作了'拐骗、绑架、收买、贩卖、接送、中转'的明确列举，该罪状属于？", opts:["叙明罪状","简单罪状","引证罪状","空白罪状"], ans:0, diff:2, exp:"叙明罪状在条文中对犯罪构成要件作详细具体的描述。该款对拐卖行为方式的列举即属叙明罪状。", chapter:"第一章 刑法各论概述"},
  {q:"行为人实施合同诈骗行为，同时触犯诈骗罪与合同诈骗罪条文。对此应如何定罪处罚？", opts:["按特别法条（合同诈骗罪）优于普通法条（诈骗罪）处理","一律按处罚较重的诈骗罪论处","实行数罪并罚","由被害人选择罪名起诉"], ans:0, diff:3, exp:"两罪构成法条竞合关系。合同诈骗罪相对于诈骗罪是特别法条，依特别法优于普通法的原则，应以合同诈骗罪定罪处罚。", chapter:"第一章 刑法各论概述"},
  {q:"关于选择性罪名（如'非法制造、买卖、运输、邮寄、储存枪支、弹药、爆炸物罪'），下列说法正确的是？", opts:["行为人实施其中数个行为的，仍按一罪论处，不实行数罪并罚","行为人实施其中数个行为的，应当数罪并罚","选择性罪名只能适用于一种行为方式","选择性罪名在司法中无法适用"], ans:0, diff:3, exp:"选择性罪名指条文包含数个可选择的行为方式或对象但作为一罪规定的罪名。实施其中部分或全部行为的，仍按一罪从重处罚，不数罪并罚。", chapter:"第一章 刑法各论概述"},
  {q:"背叛国家罪的主体是？", opts:["中华人民共和国公民","一切具有刑事责任能力的自然人","国家机关工作人员","中国军人"], ans:0, diff:2, exp:"背叛国家罪（《刑法》第102条）的主体是特殊主体，限于具有中华人民共和国国籍的公民，一般须有一定社会地位。勾结外国危害国家主权、领土完整和安全。", chapter:"第二章 危害国家安全罪"},
  {q:"下列行为中，属于《刑法》第110条间谍罪法定行为方式的是？", opts:["参加间谍组织或者接受间谍组织及其代理人的任务","为境外人员提供一般商业信息","向他人出售自己的身份证","非法获取公民个人信息"], ans:0, diff:2, exp:"间谍罪的行为方式包括：参加间谍组织、接受间谍组织及其代理人任务、为敌人指示轰击目标。提供一般商业信息等不构成该罪。", chapter:"第二章 危害国家安全罪"},
  {q:"间谍罪与为境外窃取、刺探、收买、非法提供国家秘密、情报罪的关键区别是？", opts:["行为人是否隶属于间谍组织或为其效力","国家秘密密级的高低","行为人的国籍","是否造成泄密后果"], ans:0, diff:3, exp:"为境外窃取、刺探、收买、非法提供国家秘密、情报罪（第111条）不要求行为人为间谍组织效力；间谍罪则要求行为人参加间谍组织或接受其任务。", chapter:"第二章 危害国家安全罪"},
  {q:"甲系某军工科研院所研究人员，为获取报酬，将本单位承担的重点课题涉密资料提供给某境外机构。甲的行为构成？", opts:["为境外窃取、刺探、收买、非法提供国家秘密罪","间谍罪","故意泄露国家秘密罪","非法获取国家秘密罪"], ans:0, diff:3, exp:"甲向境外机构非法提供国家秘密，符合《刑法》第111条之规定，构成为境外窃取、刺探、收买、非法提供国家秘密罪。因甲未参加间谍组织，不构成间谍罪。", chapter:"第二章 危害国家安全罪"},
  {q:"国家机关工作人员甲将不属于国家秘密的一般工作文件发送给朋友乙，乙转发至网络公开。对甲应如何处理？", opts:["不构成犯罪，因其泄露的并非国家秘密","构成故意泄露国家秘密罪","构成为境外窃取、刺探、收买、非法提供国家秘密罪","构成间谍罪"], ans:0, diff:3, exp:"故意泄露国家秘密罪（第398条）的对象仅限于国家秘密。甲泄露的是一般工作信息而非国家秘密，不符合构成要件，不构成犯罪，可按有关规定给予纪律处分。", chapter:"第二章 危害国家安全罪"},
  {q:"叛逃罪的主体是？", opts:["国家机关工作人员或者掌握国家秘密的国家工作人员","一切中国公民","军事机关以外的所有人员","国家工作人员以外的自然人"], ans:0, diff:2, exp:"叛逃罪（《刑法》第109条）的主体是特殊主体，限于国家机关工作人员或掌握国家秘密的国家工作人员，在履行公务期间擅离岗位叛逃境外或在境外叛逃。", chapter:"第二章 危害国家安全罪"},
  {q:"放火罪属于什么类型的犯罪？", opts:["危害公共安全罪","侵犯财产罪","侵犯人身权利罪","妨害社会管理秩序罪"], ans:0, diff:1, exp:"放火罪规定在《刑法》第二章'危害公共安全罪'中（第114条、第115条）。放火罪是危险犯，只要实施放火行为危及公共安全即构成既遂。", chapter:"第三章 危害公共安全罪"},
  {q:"为在社会上立功表现，A点火烧房子，在消防员来时又扑灭了火，烧毁了一些物品。A的行为构成什么罪？", opts:["放火罪","失火罪","故意毁坏财物罪","寻衅滋事罪"], ans:0, diff:2, exp:"A点火烧房子的行为已经构成放火罪（既遂）。放火罪是危险犯，只要放火行为足以危害公共安全即构成既遂，事后扑灭火焰不影响定罪。", chapter:"第三章 危害公共安全罪"},
  {q:"破坏交通工具罪与故意毁坏财物罪的区别在于？", opts:["是否危害公共安全","毁坏财物的价值","行为方式","犯罪地点"], ans:0, diff:2, exp:"破坏交通工具罪要求破坏火车、汽车、电车、船只、航空器，足以使其发生倾覆、毁坏危险，危及公共安全。如果仅破坏一般财物，不危及公共安全，则构成故意毁坏财物罪。", chapter:"第三章 危害公共安全罪"},
  {q:"交通肇事罪的主观方面是？", opts:["过失","故意","故意或过失均可","严格责任"], ans:0, diff:1, exp:"交通肇事罪是典型的过失犯罪，行为人对违反交通运输管理法规是故意的，但对造成严重后果是过失的。", chapter:"第三章 危害公共安全罪"},
  {q:"危险驾驶罪包括哪些情形？", opts:["追逐竞驶、醉酒驾驶、超载超速、违规运输危化品","仅醉酒驾驶","仅追逐竞驶","醉酒驾驶和无证驾驶"], ans:0, diff:1, exp:"《刑法》第133条之一规定，危险驾驶罪包括四种情形：追逐竞驶情节恶劣、醉酒驾驶机动车、从事校车或旅客运输严重超载超速、违反规定运输危险化学品危及公共安全。", chapter:"第三章 危害公共安全罪"},
  {q:"以危险方法危害公共安全罪与故意杀人罪的区分，以下哪项正确？", opts:["是否危害不特定多数人的生命安全","是否使用暴力","是否造成死亡","是否有故意"], ans:0, diff:3, exp:"关键区别在于行为是否危害不特定多数人的生命、健康或重大公私财产安全。如果行为针对特定个人实施，应定故意杀人罪；如果行为危及不特定多数人，应定以危险方法危害公共安全罪。", chapter:"第三章 危害公共安全罪"},
  {q:"破坏交通工具罪与破坏交通设施罪的关键区别是？", opts:["犯罪对象不同：交通工具 vs 交通设施","主观方面不同","犯罪主体不同","是否危及公共安全"], ans:0, diff:1, exp:"破坏交通工具罪的对象是火车、汽车、电车、船只、航空器；破坏交通设施罪的对象是轨道、桥梁、隧道、公路、机场、航道、灯塔、标志等交通设施。", chapter:"第三章 危害公共安全罪"},
  {q:"非法持有枪支罪与非法制造枪支罪的关系，正确的处理是？", opts:["如能证明枪支系自己制造的，以非法制造枪支罪一罪论处","一律数罪并罚","均以非法持有枪支罪处理","两罪不能并存"], ans:0, diff:3, exp:"如果非法制造的枪支被自己持有，属于吸收关系，一般以非法制造枪支罪一罪论处。但非法制造后又贩卖、运输的，可能分别评价。", chapter:"第三章 危害公共安全罪"},
  {q:"交通肇事后逃逸的，应如何处理？", opts:["处3年以上7年以下有期徒刑","处拘役","处7年以上有期徒刑","以故意杀人罪论处"], ans:0, diff:2, exp:"《刑法》第133条规定，交通肇事后逃逸的，处3年以上7年以下有期徒刑。因逃逸致人死亡的，处7年以上有期徒刑。交通肇事后为逃避追究而将被害人带离现场隐藏或遗弃致其得不到救助而死亡的，以故意杀人罪论处。", chapter:"第三章 危害公共安全罪"},
  {q:"丢失枪支不报罪的犯罪主体是？", opts:["依法配备公务用枪的人员","所有持枪人员","非法持枪人员","枪支销售商"], ans:0, diff:1, exp:"《刑法》第129条规定，依法配备公务用枪的人员丢失枪支不及时报告、造成严重后果的，构成本罪。不包括依法配置民用枪支的人员。", chapter:"第三章 危害公共安全罪"},
  {q:"销售假药罪属于什么类型的犯罪？", opts:["行为犯（抽象危险犯）","结果犯","具体危险犯","实害犯"], ans:0, diff:2, exp:"《刑法》第141条规定，生产、销售假药的即构成犯罪。刑法修正案(八)删除了'足以严重危害人体健康'的要件，使该罪成为行为犯。", chapter:"第四章 破坏社会主义市场经济秩序罪"},
  {q:"洗钱罪的上游犯罪不包括以下哪项？", opts:["交通肇事罪","毒品犯罪","贪污贿赂犯罪","恐怖活动犯罪"], ans:0, diff:3, exp:"洗钱罪的上游犯罪包括：毒品犯罪、黑社会性质组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪（《刑法》第191条）。交通肇事罪不属于上述范围。", chapter:"第四章 破坏社会主义市场经济秩序罪"},
  {q:"关于信用卡诈骗罪，以下哪种行为方式不正确？", opts:["使用信用卡正常透支消费","使用伪造的信用卡","冒用他人信用卡","恶意透支"], ans:0, diff:1, exp:"信用卡诈骗罪的行为方式包括：使用伪造的信用卡、使用作废的信用卡、冒用他人信用卡、恶意透支。正常的信用卡透支消费并在规定期限内还款的不构成犯罪。", chapter:"第四章 破坏社会主义市场经济秩序罪"},
  {q:"集资诈骗罪与非法吸收公众存款罪的核心区别是？", opts:["是否具有非法占有目的","是否向社会公开宣传","是否承诺还本付息","涉及金额大小"], ans:0, diff:2, exp:"集资诈骗罪以非法占有为目的，使用诈骗方法非法集资；非法吸收公众存款罪不具有非法占有目的，仅违反金融管理法规吸收资金。'非法占有目的'是两罪的核心区别。", chapter:"第四章 破坏社会主义市场经济秩序罪"},
  {q:"逃税罪的首次免责条款规定，纳税人补缴税款后可以不予追究刑事责任的条件不包括？", opts:["5年内因逃税受过刑事处罚","补缴应纳税款","缴纳滞纳金","已受行政处罚"], ans:0, diff:3, exp:"《刑法》第201条第4款规定，有逃税行为，经税务机关依法下达追缴通知后，补缴应纳税款、缴纳滞纳金并已受行政处罚的，不予追究刑事责任。但5年内因逃税受过刑事处罚或被税务机关给予两次以上行政处罚的除外。", chapter:"第四章 破坏社会主义市场经济秩序罪"},
  {q:"关于非法吸收公众存款罪的'四性'特征，哪项不属于？", opts:["有偿性","非法性","公开性","利诱性"], ans:0, diff:2, exp:"非法吸收公众存款罪的'四性'特征：非法性（未经批准）、公开性（公开宣传）、利诱性（承诺回报）、社会性（向社会不特定对象吸收资金）。'有偿性'不是'四性'的标准表述。", chapter:"第四章 破坏社会主义市场经济秩序罪"},
  {q:"生产、销售有毒有害食品罪与生产、销售不符合安全标准食品罪的区别？", opts:["前者掺入有毒有害非食品原料，后者食品本身不符合安全标准","两者完全相同","前者为结果犯，后者为行为犯","两者法定刑相同"], ans:0, diff:3, exp:"有毒有害食品罪是行为犯（抽象危险犯），在食品中掺入有毒有害非食品原料即构成；不符合安全标准食品罪是危险犯，需足以造成严重食物中毒或其他严重食源性疾病。", chapter:"第四章 破坏社会主义市场经济秩序罪"},
  {q:"故意杀人罪与故意伤害致死的主要区别是？", opts:["主观故意内容不同：杀人故意vs伤害故意","仅看死亡结果是否发生","仅看作案工具是否致命","仅看打击部位"], ans:0, diff:2, exp:"区分关键在于主观故意内容——故意杀人罪具有剥夺他人生命的故意，故意伤害致死只有损害他人健康的故意但对死亡结果有过失。需综合考量作案工具、打击部位、打击力度、作案动机等客观因素推断主观故意。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"过失致人死亡罪与意外事件的区分？", opts:["行为人是否应当预见并能预见死亡结果","是否造成死亡","行为方式","主体身份"], ans:0, diff:1, exp:"过失致人死亡罪要求行为人能够预见死亡结果但因疏忽大意未能预见或过于自信轻信能避免。意外事件中行为人不能预见且无法预见的，不构成犯罪。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"强奸罪的基本构成中，手段行为不包括？", opts:["欺骗手段","暴力手段","胁迫手段","其他手段（如麻醉）"], ans:0, diff:1, exp:"强奸罪要求以暴力、胁迫或其他手段强奸妇女。单纯的欺骗（如冒充丈夫）一般不构成强奸罪的手段要件。'其他手段'通常指使妇女不知反抗或不能反抗的手段。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"绑架罪与非法拘禁罪的核心区别是什么？", opts:["是否以勒索财物为目的或绑架他人作为人质","是否限制人身自由","拘禁时间长短","是否使用了暴力"], ans:0, diff:2, exp:"绑架罪以勒索财物或满足其他不法要求为目的（目的犯），侵犯的是复杂客体（人身权利+财产权利等）。非法拘禁罪仅侵犯人身自由权利。为索取债务扣押他人的，以非法拘禁罪定罪。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"绑架过程中杀害被绑架人的应如何处理？", opts:["以绑架罪一罪论处，处无期徒刑或死刑","以绑架罪和故意杀人罪数罪并罚","以故意杀人罪论处","以故意伤害罪和绑架罪并罚"], ans:0, diff:1, exp:"根据《刑法》第239条，杀害被绑架人的属于绑架罪的结果加重犯，处无期徒刑或死刑，并处没收财产，不再另定故意杀人罪进行数罪并罚。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"拐卖妇女、儿童罪与拐骗儿童罪的主要区别？", opts:["是否以出卖为目的","是否使用暴力","被害人年龄","犯罪主体"], ans:0, diff:1, exp:"拐卖妇女儿童罪以出卖为目的；拐骗儿童罪不以出卖为目的（如为收养、使唤）。'出卖目的'是两罪的核心区别。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"关于侮辱罪，以下哪项正确？", opts:["侮辱罪属于告诉才处理的犯罪","侮辱罪是公诉案件","侮辱罪不要求公然进行","网上侮辱他人不构成侮辱罪"], ans:0, diff:1, exp:"《刑法》第246条规定，侮辱罪属于告诉才处理的犯罪（自诉案件），但严重危害社会秩序和国家利益的除外。侮辱行为必须公然进行。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"为索取债务非法扣押、拘禁他人的，应定什么罪？", opts:["非法拘禁罪","绑架罪","敲诈勒索罪","抢劫罪"], ans:0, diff:1, exp:"《刑法》第238条第3款规定，为索取债务非法扣押、拘禁他人的，以非法拘禁罪定罪。这里的'债务'包括合法债务和非法债务（如赌债、毒债）。如索要金额明显超出债务数额则可能构成绑架罪。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"负有照护职责人员性侵罪的保护对象是？", opts:["已满14周岁不满16周岁的未成年女性","所有未成年人","未满14周岁的未成年人","成年女性"], ans:0, diff:1, exp:"《刑法》第236条之一（修正案十一新增）规定，对已满14周岁不满16周岁的未成年女性负有监护、收养、看护、教育、医疗等特殊职责的人员，与该未成年女性发生性关系的，构成本罪。", chapter:"第五章 侵犯公民人身权利、民主权利罪"},
  {q:"抢劫罪与抢夺罪的核心区别是？", opts:["是否使用暴力、胁迫或其他方法压制被害人反抗","是否公开进行","是否取得财物","犯罪数额大小"], ans:0, diff:1, exp:"抢劫罪要求以暴力、胁迫或其他方法压制被害人反抗后取得财物。抢夺罪是趁人不备公然夺取财物，未使用暴力压制反抗。但携带凶器抢夺的，以抢劫罪定罪。", chapter:"第六章 侵犯财产罪"},
  {q:"盗窃罪与职务侵占罪的核心区别？", opts:["是否利用职务上的便利","是否秘密进行","犯罪数额","犯罪主体是否为特殊主体"], ans:0, diff:2, exp:"职务侵占罪要求利用职务上的便利（管理、经手本单位财物的便利），将本单位财物非法占为己有。盗窃罪不需要利用职务便利。这是两罪的核心区别。", chapter:"第六章 侵犯财产罪"},
  {q:"侵占罪的犯罪对象是？", opts:["代为保管的他人财物、遗忘物、埋藏物","他人的任何财物","公共财物","无主物"], ans:0, diff:1, exp:"《刑法》第270条规定，侵占罪的对象限于代为保管的他人财物、他人的遗忘物或埋藏物。侵占罪是亲告罪（告诉才处理）。", chapter:"第六章 侵犯财产罪"},
  {q:"摩托车未上锁，A将车开走并转卖，A构成什么罪？", opts:["盗窃罪","侵占罪","诈骗罪","抢夺罪"], ans:0, diff:1, exp:"A以非法占有为目的，秘密窃取他人摩托车并转卖，构成盗窃罪。摩托车虽未上锁，但仍属他人占有之物，不属于遗忘物或埋藏物。", chapter:"第六章 侵犯财产罪"},
  {q:"敲诈勒索罪和抢劫罪的核心区别是什么？", opts:["暴力程度和取财时间：抢劫是当场暴力+当场取财，敲诈是威胁+将来取财或将来暴力","犯罪数额不同","犯罪对象不同","犯罪主体不同"], ans:0, diff:2, exp:"两罪核心区别在客观方面：抢劫罪是当场使用暴力、胁迫+当场取得财物（两个'当场'）；敲诈勒索罪是通过威胁或要挟，可以是将来实施暴力+将来取得财物，或当场威胁+将来取财等。", chapter:"第六章 侵犯财产罪"},
  {q:"冒充警察抢劫运钞车，属于抢劫罪的哪种加重情形？", opts:["冒充军警人员抢劫","持枪抢劫","抢劫银行","抢劫金融机构"], ans:0, diff:1, exp:"冒充警察属于'冒充军警人员抢劫'，是抢劫罪的八种加重情形之一。同时抢劫运钞车也可能涉及'抢劫金融机构'的加重情形。", chapter:"第六章 侵犯财产罪"},
  {q:"诈骗罪的基本结构是？", opts:["虚构事实、隐瞒真相→被害人陷入错误认识→基于错误处分财产→行为人取得财产","秘密窃取他人财物","趁人不备公然夺取","利用职务便利侵占"], ans:0, diff:1, exp:"诈骗罪的基本构造：行为人实施欺骗行为→被害人陷入或维持错误认识→被害人基于错误认识处分财产→行为人取得财产、被害人遭受损失。各环节需有因果关系。", chapter:"第六章 侵犯财产罪"},
  {q:"故意毁坏财物罪与破坏生产经营罪的主要区别？", opts:["破坏生产经营罪要求出于泄愤报复等个人目的破坏生产经营","两者完全相同","犯罪数额不同","犯罪时间不同"], ans:0, diff:2, exp:"破坏生产经营罪要求出于泄愤报复或其他个人目的，毁坏机器设备、残害耕畜或以其他方法破坏生产经营。故意毁坏财物罪无此特殊目的要求，是毁坏财物的普通罪名。", chapter:"第六章 侵犯财产罪"},
  {q:"A与B都是吸毒者，A将毒品以购买价转让给B，A是否构成贩卖毒品罪？", opts:["构成，有偿转让即贩卖","不构成，平价转让无牟利","不构成，吸毒者之间转让属自用","构成非法持有毒品罪"], ans:0, diff:2, exp:"吸毒者有偿转让毒品给他人并获取对价，属于贩卖毒品行为。即使以购买价转让，也构成贩卖毒品罪，因为其行为已进入流通环节并获取了对价。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"为躲避公安部门的酒驾排查，开车向交警冲撞，构成什么罪？", opts:["妨害公务罪","故意杀人罪","以危险方法危害公共安全罪","袭警罪"], ans:0, diff:2, exp:"行为人以暴力方法阻碍人民警察依法执行公务，构成妨害公务罪（袭警罪）。不足以推定具有杀人故意，也未危害不特定多数人安全。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"妨害作证罪与伪证罪的区别？", opts:["犯罪主体不同：妨害作证罪是一般主体，伪证罪是特殊主体","行为方式不同","犯罪时间不同","没有区别"], ans:0, diff:2, exp:"伪证罪的犯罪主体限于刑事诉讼中的证人、鉴定人、记录人、翻译人（特殊主体）。妨害作证罪是一般主体（以暴力、威胁、贿买等方法阻止证人作证或指使他人作伪证）。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"网络服务提供者拒不履行信息网络安全管理义务，造成危害后果时，构成什么罪？", opts:["拒不履行信息网络安全管理义务罪","玩忽职守罪","帮助信息网络犯罪活动罪","非法经营罪"], ans:0, diff:2, exp:"《刑法》第286条之一规定了拒不履行信息网络安全管理义务罪，网络服务提供者不履行安全管理义务，经监管部门责令改正而拒不改正，造成严重后果的构成本罪。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"高空抛物罪中'情节严重'的理解，以下哪项正确？", opts:["多次抛掷、抛掷物品数量多、在人员密集场所抛掷等","只要抛掷就构成犯罪","只有造成人员伤亡才是情节严重","只有抛掷危险物品才构成"], ans:0, diff:1, exp:"《刑法》第291条之二，从建筑物抛掷物品情节严重的构成犯罪。'情节严重'需综合考量抛掷物品的种类、数量、抛掷场所、时间、造成的危险程度等因素。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"妨害传染病防治罪的主观方面是？", opts:["故意违反防控规定，但对引起传播危险是过失","故意传播传染病","过失违反防控规定","无过错责任"], ans:0, diff:2, exp:"妨害传染病防治罪的行为人故意违反传染病防治规定，但对引起甲类传染病传播或有传播严重危险的结果是过失心态。属于混合罪过。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"组织考试作弊罪适用于哪些考试？", opts:["法律规定的国家考试","所有考试","学校期末考试","公司招聘考试"], ans:0, diff:1, exp:"《刑法》第284条之一规定，组织考试作弊罪适用于'法律规定的国家考试'，如高考、研究生考试、公务员考试、法律职业资格考试、教师资格考试等。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"催收非法债务罪规制的行为方式不包括？", opts:["向人民法院提起诉讼","使用暴力、胁迫方法","限制他人人身自由","侵入他人住宅、恐吓跟踪骚扰"], ans:0, diff:1, exp:"《刑法》第293条之一（催收非法债务罪）规制的行为包括：使用暴力/胁迫、限制人身自由、侵入住宅或恐吓跟踪骚扰。通过合法途径（如诉讼）催收不构成本罪。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"袭警罪与妨害公务罪的关系，以下哪项正确？", opts:["袭警罪是妨害公务罪的特别规定，暴力袭击正在执行职务的人民警察的适用袭警罪","两者完全相同","袭警罪和妨害公务罪可以同时适用","袭警罪仅适用于武装警察"], ans:0, diff:1, exp:"袭警罪是妨害公务罪的特殊条款。暴力袭击正在依法执行职务的人民警察的，构成袭警罪（《刑法》第277条第5款）。使用枪支、管制刀具等手段严重危及其人身安全的，处3年以上7年以下有期徒刑。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"侵犯公民个人信息罪的'公民个人信息'不包括？", opts:["已公开的企业工商登记信息","姓名身份证号","行踪轨迹","财产状况"], ans:0, diff:1, exp:"公民个人信息是指以电子或其他方式记录的能单独或与其他信息结合识别特定自然人身份的各种信息。企业公开的工商登记信息不属于公民个人信息。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"包庇罪与伪证罪的主要区别是？", opts:["发生时间不同：伪证罪限于刑事诉讼中，包庇罪可在任何阶段","两者完全相同","犯罪主体完全相同","法定刑完全相同"], ans:0, diff:2, exp:"伪证罪限于刑事诉讼过程中，在侦查、起诉、审判阶段对与案件有重要关系的情节作虚假证明；包庇罪可在犯罪后任何阶段实施。主体也不同。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"关于传播性病罪，需要行为人主观上明知自己患有哪类疾病？", opts:["严重性病","任何传染病","一般疾病","非传染性疾病"], ans:0, diff:1, exp:"《刑法》第360条规定，明知自己患有梅毒、淋病等严重性病而卖淫、嫖娼的构成传播性病罪。要求'明知'的主观要件。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"虚假诉讼罪的主观方面必须是？", opts:["以捏造的事实提起民事诉讼，妨害司法秩序或严重侵害他人合法权益","只需提起诉讼","只需提供证据","只需陈述事实"], ans:0, diff:2, exp:"《刑法》第307条之一规定，以捏造的事实提起民事诉讼，妨害司法秩序或者严重侵害他人合法权益的，构成虚假诉讼罪。要求'捏造的事实'与'提起民事诉讼'相结合。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"冒名顶替罪（顶替他人身份就学就业）规定在哪部修正案中新增？", opts:["刑法修正案(十一)","刑法修正案(九)","刑法修正案(十)","刑法修正案(十二)"], ans:0, diff:1, exp:"《刑法》第280条之二（冒名顶替罪）由刑法修正案(十一)新增，2021年3月1日起施行。规制的行为包括盗用、冒用他人身份，顶替他人取得高等学历教育入学资格、公务员录用资格、就业安置待遇等。", chapter:"第七章 妨害社会管理秩序罪"},
  {q:"行贿罪的主观方面要求行为人具有什么目的？", opts:["为谋取不正当利益","为谋取任何利益","为谋取非法利益","为谋取个人利益"], ans:0, diff:1, exp:"行贿罪的主观方面要求行为人具有'为谋取不正当利益'的目的。如果因被勒索而给予国家工作人员财物、没有获得不正当利益的，不构成行贿。", chapter:"第八章 贪污贿赂罪"},
  {q:"贪污罪和挪用公款罪的核心区别是什么？", opts:["是否具有非法占有目的","犯罪主体不同","犯罪数额不同","是否利用职务便利"], ans:0, diff:2, exp:"两罪核心区别在于主观目的：贪污罪具有非法占有公共财物的目的（永久占有），挪用公款罪只有暂时使用后归还的意图。如果挪用后潜逃、挥霍等表明无归还意图，可转化为贪污罪。", chapter:"第八章 贪污贿赂罪"},
  {q:"受贿罪中'为他人谋取利益'的要件，以下哪种理解正确？", opts:["承诺、实施、实现谋利行为均满足要件，包括默示承诺","必须是实际实施了谋利行为","必须是成功实现了谋利结果","必须有明确的书面承诺"], ans:0, diff:2, exp:"'为他人谋取利益'包括承诺、实施和实现三个阶段的行为。只要有承诺（包括默示承诺）为他人谋取利益，即具备该要件。明知他人有具体请托事项而收受财物的，视为承诺为他人谋取利益。", chapter:"第八章 贪污贿赂罪"},
  {q:"甲系国有公司财务人员，利用职务便利将单位公款5万元非法占为己有。甲的行为构成？", opts:["贪污罪","职务侵占罪","盗窃罪","挪用公款罪"], ans:0, diff:2, exp:"甲在国有公司中从事公务，属于国家工作人员，利用职务便利非法占有公共财物，构成贪污罪（《刑法》第382条）。职务侵占罪的主体是非国家工作人员。", chapter:"第八章 贪污贿赂罪"},
  {q:"关于受贿罪中'利用职务上的便利'的理解，下列哪项正确？", opts:["指利用本人职务范围内主管、负责、承办公共事务的职权及形成的便利条件","仅指利用他人职务上的便利","包括利用与职务无关的亲友关系","不包括事后收受财物的情形"], ans:0, diff:2, exp:"'利用职务上的便利'指利用本人职务范围内主管、负责、承办某项公共事务的职权及所形成的便利条件，不包括与职务无关的私人关系。", chapter:"第八章 贪污贿赂罪"},
  {q:"某税务局局长甲应个体工商户乙请托，利用职权为乙违规减免税款，事后收受乙所送5万元。对甲的行为应如何定性？", opts:["受贿罪","贪污罪","滥用职权罪","徇私舞弊不征、少征税款罪"], ans:0, diff:3, exp:"甲作为国家工作人员，利用职务便利为请托人谋取利益并收受财物，符合受贿罪构成要件（《刑法》第385条），构成受贿罪。请托人为谋取不正当利益而给付财物，另构成行贿罪。", chapter:"第八章 贪污贿赂罪"},
  {q:"玩忽职守罪的主观方面是？", opts:["过失","故意","故意或过失均可","严格责任"], ans:0, diff:1, exp:"玩忽职守罪是典型的过失犯罪，行为人严重不负责任、不履行或不正确履行职责，致使公共财产、国家和人民利益遭受重大损失。", chapter:"第九章 渎职罪"},
  {q:"滥用职权罪的主观方面是？", opts:["故意","过失","故意或过失均可","严格责任"], ans:0, diff:1, exp:"滥用职权罪是故意犯罪，行为人明知自己滥用职权的行为会造成危害结果，希望或放任该结果发生。与玩忽职守罪（过失）相区别。", chapter:"第九章 渎职罪"},
  {q:"渎职罪的主体原则上限于？", opts:["国家机关工作人员","国有公司、企业中从事公务的人员","无业人员","事业单位一般职工"], ans:0, diff:2, exp:"渎职罪（刑法第九章）的主体原则上为特殊主体，限于国家机关工作人员。国有公司、企业人员不属于国家机关工作人员，其相应行为可能构成职务侵占罪、贪污罪等，但不构成本章渎职罪。", chapter:"第九章 渎职罪"},
  {q:"司法工作人员对明知是无罪的人而使他受追诉，对明知是有罪的人而故意包庇使其不受追诉的，构成？", opts:["徇私枉法罪","枉法裁判罪","滥用职权罪","徇私舞弊不移交刑事案件罪"], ans:0, diff:2, exp:"徇私枉法罪（《刑法》第399条第1款）的主体是司法工作人员，表现为对明知无罪的人使其受追诉、对明知有罪的人故意包庇使其不受追诉等。", chapter:"第九章 渎职罪"},
  {q:"关于徇私枉法罪与枉法裁判罪的区别，下列说法正确的是？", opts:["徇私枉法罪发生在刑事诉讼活动中，枉法裁判罪发生在民事、行政审判活动中","两者犯罪主体不同","枉法裁判罪属于危害公共安全罪","徇私枉法罪只能由不作为构成"], ans:0, diff:3, exp:"徇私枉法罪（第399条第1款）发生在刑事案件的侦查、起诉、审判活动中；枉法裁判罪（第399条第2款）发生在民事、行政审判活动中。二者主体均为司法工作人员。", chapter:"第九章 渎职罪"},
  {q:"司法工作人员甲收受犯罪嫌疑人亲属贿赂后，对明知有罪的人故意包庇使其不受追诉，同时构成受贿罪和徇私枉法罪。对甲应如何处理？", opts:["依照处罚较重的规定定罪处罚","以受贿罪和徇私枉法罪数罪并罚","只定徇私枉法罪","只定受贿罪"], ans:0, diff:3, exp:"《刑法》第399条第4款特别规定，司法工作人员贪赃枉法，收受贿赂又实施徇私枉法、枉法裁判行为构成犯罪的，依照处罚较重的规定定罪处罚，不数罪并罚。", chapter:"第九章 渎职罪"}
],

  "民法·总则": [
    {q:"《中华人民共和国民法典》共多少编、多少条？", opts:["7编1260条","5编1380条","8编1000条","6编1520条"], ans:0, diff:1, exp:"民法典共7编1260条，包括总则、物权、合同、人格权、婚姻家庭、继承、侵权责任七编，于2021年1月1日起施行。", chapter:"第一章 民法基本原理"},
    {q:"民法调整的法律关系是？", opts:["平等主体之间的人身关系和财产关系","国家与公民之间的行政关系","雇主与劳动者之间的劳动关系","国家与法人之间的管理关系"], ans:0, diff:1, exp:"《民法典》第2条规定，民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。", chapter:"第一章 民法基本原理"},
    {q:"民法中的'绿色原则'（生态环境保护原则）规定在民法典哪一条？", opts:["第9条","第1条","第10条","第5条"], ans:0, diff:1, exp:"《民法典》第9条规定，民事主体从事民事活动，应当有利于节约资源、保护生态环境。这是民法典新增加的'绿色原则'，体现了生态文明建设的法治要求。", chapter:"第一章 民法基本原理"},
    {q:"关于民事习惯的法律地位，以下哪项正确？", opts:["处理民事纠纷应当依法，法律没有规定的可以适用不违背公序良俗的习惯","习惯与法律具有同等效力","习惯不能作为裁判依据","习惯可以取代法律"], ans:0, diff:2, exp:"《民法典》第10条规定，处理民事纠纷应当依照法律；法律没有规定的，可以适用习惯，但是不得违背公序良俗。习惯是法律的补充渊源。", chapter:"第一章 民法基本原理"},
    {q:"民事主体按照自己的意愿设立、变更、终止民事法律关系，体现了民法的哪一项基本原则？", opts:["自愿原则","平等原则","公平原则","绿色原则"], ans:0, diff:1, exp:"《民法典》第5条规定，民事主体从事民事活动，应当遵循自愿原则，按照自己的意思设立、变更、终止民事法律关系。自愿原则又称意思自治原则。", chapter:"第一章 民法基本原理"},
    {q:"民事主体从事民事活动，不得违反法律，不得违背公序良俗。这里的'公序良俗'是指？", opts:["公共秩序和善良风俗","公共利益和个人风俗","国家秩序与民族习惯","公共秩序和商业惯例"], ans:0, diff:1, exp:"公序良俗即公共秩序与善良风俗。《民法典》第8条规定民事主体从事民事活动不得违反法律、不得违背公序良俗；依第153条，违背公序良俗的民事法律行为无效。", chapter:"第一章 民法基本原理"},
    {q:"根据民法典，自然人的民事权利能力从何时开始？", opts:["出生时","年满8周岁","年满16周岁","年满18周岁"], ans:0, diff:1, exp:"《民法典》第13条规定，自然人从出生时起到死亡时止，具有民事权利能力，依法享有民事权利，承担民事义务。", chapter:"第二章 民事主体"},
    {q:"胎儿是否具有继承权？", opts:["胎儿享有继承权，娩出时为死体的权利自始不存在","胎儿无继承权","胎儿仅在出生后有继承权","需由法院判断"], ans:0, diff:2, exp:"《民法典》第16条规定，涉及遗产继承、接受赠与等胎儿利益保护的，胎儿视为具有民事权利能力。但是胎儿娩出时为死体的，其民事权利能力自始不存在。", chapter:"第二章 民事主体"},
    {q:"完全民事行为能力人的最低年龄是多少？", opts:["18周岁","16周岁","20周岁","14周岁"], ans:0, diff:1, exp:"《民法典》第17-18条规定，18周岁以上的自然人为成年人，具有完全民事行为能力。16周岁以上以自己劳动收入为主要生活来源的，视为完全民事行为能力人。", chapter:"第二章 民事主体"},
    {q:"限制民事行为能力人独立实施的哪种行为有效？", opts:["纯获利益的行为","购买大额商品的行为","签订劳动合同的行为","处分不动产的行为"], ans:0, diff:2, exp:"《民法典》第145条规定，限制民事行为能力人实施的纯获利益的民事法律行为或者与其年龄、智力、精神健康状况相适应的民事法律行为有效。", chapter:"第二章 民事主体"},
    {q:"8周岁以上的未成年人属于哪种民事行为能力人？", opts:["限制民事行为能力人","无民事行为能力人","完全民事行为能力人","视为完全民事行为能力人"], ans:0, diff:1, exp:"《民法典》第19条规定，8周岁以上的未成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或经其同意、追认；但可独立实施纯获利益或与其年龄智力相适应的行为。", chapter:"第二章 民事主体"},
    {q:"无民事行为能力人包括哪些？", opts:["不满8周岁的未成年人、不能辨认自己行为的成年人和8周岁以上未成年人","仅不满8周岁的未成年人","仅精神病人","所有人"], ans:0, diff:2, exp:"《民法典》第20条、第21条规定，不满8周岁的未成年人为无民事行为能力人；不能辨认自己行为的成年人和8周岁以上未成年人为无民事行为能力人。", chapter:"第二章 民事主体"},
    {q:"宣告失踪的条件是自然人下落不明满多少年？", opts:["2年","1年","3年","4年"], ans:0, diff:1, exp:"《民法典》第40条规定，自然人下落不明满二年的，利害关系人可以向人民法院申请宣告该自然人为失踪人。", chapter:"第二章 民事主体"},
    {q:"宣告死亡的条件是自然人下落不明满多少年？", opts:["4年（一般），2年（因意外事件）","2年","3年","5年"], ans:0, diff:2, exp:"《民法典》第46条规定，下落不明满4年（一般情形）或因意外事件下落不明满2年，利害关系人可申请宣告死亡。因意外事件下落不明经有关机关证明不可能生存的，不受2年限制。", chapter:"第二章 民事主体"},
    {q:"法人应当具备的条件不包括？", opts:["必须由自然人组成","依法成立","有名称、组织机构、住所","有独立的财产或经费"], ans:0, diff:2, exp:"《民法典》第58条规定法人应：依法成立；有名称、组织机构、住所；有独立的财产或经费；能独立承担民事责任。法人不必然由自然人组成（如机关法人）。", chapter:"第二章 民事主体"},
    {q:"以下哪项属于非法人组织？", opts:["个人独资企业","有限责任公司","股份有限公司","机关法人"], ans:0, diff:1, exp:"《民法典》第102条规定，非法人组织包括个人独资企业、合伙企业、不具有法人资格的专业服务机构等。非法人组织不具有法人资格，但能以自己的名义从事民事活动。", chapter:"第二章 民事主体"},
    {q:"监护人应当按照什么原则履行监护职责？", opts:["最有利于被监护人的原则","监护人的意愿优先","经济效益最大化","社会公共利益优先"], ans:0, diff:1, exp:"《民法典》第35条规定，监护人应当按照最有利于被监护人的原则履行监护职责。监护人除为维护被监护人利益外，不得处分被监护人的财产。", chapter:"第二章 民事主体"},
    {q:"关于法人终止的原因，不包括？", opts:["法人章程规定的存续期间届满未延期不属于终止原因","解散","被宣告破产","法律规定的其他原因"], ans:0, diff:2, exp:"《民法典》第68条规定，法人终止的原因包括：解散、被宣告破产、法律规定的其他原因。法人章程规定的存续期间届满属于解散事由之一（第69条）。", chapter:"第二章 民事主体"},
    {q:"下列权利中，属于人身权的是？", opts:["生命权","所有权","债权","抵押权"], ans:0, diff:1, exp:"人身权包括人格权和身份权，生命权属于人格权（《民法典》第990条）。所有权、债权、抵押权属于财产权。", chapter:"第三章 民事权利"},
    {q:"关于绝对权与相对权的划分，下列说法正确的是？", opts:["物权、人身权属于绝对权，债权属于相对权","债权属于绝对权","人身权属于相对权","物权属于相对权"], ans:0, diff:2, exp:"绝对权又称对世权，可对抗不特定第三人，如物权、人身权；相对权又称对人权，仅能对抗特定相对人，如债权（参见《民法典》第118条关于债权定义的规定）。", chapter:"第三章 民事权利"},
    {q:"关于形成权，下列说法正确的是？", opts:["解除权属于形成权，享有解除权的一方以通知方式解除合同的，自通知到达对方时合同解除","形成权必须经对方当事人同意才能行使","形成权适用诉讼时效的规定","形成权本质上是请求权的下位概念"], ans:0, diff:3, exp:"《民法典》第565条规定，当事人一方依法主张解除合同的，应当通知对方，合同自通知到达对方时解除。解除权属形成权，依权利人单方意思表示即可变动法律关系。形成权适用除斥期间而非诉讼时效。", chapter:"第三章 民事权利"},
    {q:"根据《民法典》，下列哪一项不属于人格权？", opts:["身份权","姓名权","名誉权","隐私权"], ans:0, diff:1, exp:"《民法典》第990条规定，人格权包括生命权、身体权、健康权、姓名权、名称权、肖像权、名誉权、荣誉权、隐私权等。身份权（如配偶权、亲权）属于身份权，不属于人格权。", chapter:"第三章 民事权利"},
    {q:"关于数据和网络虚拟财产的保护，下列哪一说法符合《民法典》规定？", opts:["法律对数据和网络虚拟财产的保护有规定的，依照其规定","数据和网络虚拟财产不受法律保护","网络虚拟财产只能归国家所有","个人数据不属于任何民事主体的合法权益"], ans:0, diff:1, exp:"《民法典》第127条规定，法律对数据、网络虚拟财产的保护有规定的，依照其规定。该条为数据和网络虚拟财产权益保护提供了法律依据。", chapter:"第三章 民事权利"},
    {q:"关于自助行为，下列哪一说法符合《民法典》规定？", opts:["合法权益受到侵害，情况紧迫且不能及时获得国家机关保护，受害人可以在必要限度内采取扣留侵权人财物等合理措施","受害人可以采取任何私力救济措施，不受限制","自助行为只能针对人身实施，不能针对财物","采取自助行为造成损害的，一律由受害人承担全部责任"], ans:0, diff:2, exp:"《民法典》第1177条规定，合法权益受到侵害，情况紧迫且不能及时获得国家机关保护，不立即采取措施将使其合法权益受到难以弥补损害的，受害人可以在必要限度内采取扣留侵权人的财物等合理措施；受害人应当立即请求有关国家机关处理。超限造成损害的应承担侵权责任。", chapter:"第三章 民事权利"},
    {q:"关于民事法律行为的成立要件，不包括？", opts:["必须采用书面形式","有意思表示","行为人有相应民事行为能力","意思表示真实"], ans:0, diff:3, exp:"民事法律行为的一般成立要件包括：行为人具有相应民事行为能力、意思表示真实、不违反法律和公序良俗。书面形式仅在法律规定或当事人约定时才需要。", chapter:"第四章 民事法律行为"},
    {q:"以下哪种民事法律行为属于无效行为？", opts:["违反法律强制性规定的行为","重大误解的行为","欺诈行为","显失公平的行为"], ans:0, diff:1, exp:"违反法律强制性规定或违背公序良俗的民事法律行为无效（《民法典》第153条）。重大误解、欺诈、显失公平属于可撤销行为。", chapter:"第四章 民事法律行为"},
    {q:"以下哪种属于可撤销的民事法律行为？", opts:["基于重大误解实施的民事法律行为","违反公序良俗的行为","虚假意思表示的行为","恶意串通损害他人合法权益的行为"], ans:0, diff:2, exp:"《民法典》第147-151条规定，基于重大误解、欺诈、胁迫、显失公平实施的民事法律行为，受损害方有权请求撤销。无效的民事法律行为自始无效。", chapter:"第四章 民事法律行为"},
    {q:"重大误解的当事人行使撤销权的除斥期间是多少？", opts:["知道或应当知道撤销事由之日起90日","1年","6个月","3个月"], ans:0, diff:2, exp:"《民法典》第152条规定，重大误解的当事人自知道或应当知道撤销事由之日起90日内没有行使撤销权的，撤销权消灭。欺诈的除斥期间为1年。", chapter:"第四章 民事法律行为"},
    {q:"民事法律行为可撤销的除斥期间，最长不超过多少年？", opts:["5年","3年","1年","2年"], ans:0, diff:2, exp:"《民法典》第152条规定，当事人自知道或应当知道撤销事由之日起1年内没有行使撤销权的，撤销权消灭；但自民事法律行为发生之日起超过5年的，撤销权消灭。", chapter:"第四章 民事法律行为"},
    {q:"附条件的民事法律行为中'条件'的特征不包括？", opts:["条件必须是客观事实，不需要具有未来性","条件是未来的事实","条件是不确定的事实","条件是当事人约定的事实"], ans:0, diff:2, exp:"附条件民事法律行为的条件必须是未来的、不确定的、可能发生也可能不发生的、合法的事实。过去的事实不能作为条件。", chapter:"第四章 民事法律行为"},
    {q:"民事法律行为无效后，因该行为取得的财产应如何处理？", opts:["应当返还；不能返还的折价补偿","一律没收归国家","由取得方保留","无需返还"], ans:0, diff:2, exp:"《民法典》第157条规定，民事法律行为无效、被撤销或确定不发生效力后，行为人因该行为取得的财产应当予以返还；不能返还或没有必要返还的，折价补偿。有过错的一方应赔偿对方损失。", chapter:"第四章 民事法律行为"},
    {q:"代理制度中，无权代理的法律后果是？", opts:["未经被代理人追认的，对被代理人不发生效力","一律无效","对被代理人自动生效","由第三人承担责任"], ans:0, diff:3, exp:"《民法典》第171条规定，无权代理未经被代理人追认的，对被代理人不发生效力，由行为人（无权代理人）承担责任。相对人可以催告被代理人自收到通知之日起30日内予以追认。", chapter:"第五章 代理"},
    {q:"表见代理的构成要件不包括？", opts:["被代理人明确表示追认","行为人无代理权","存在使相对人相信行为人有代理权的表象","相对人善意且无过失"], ans:0, diff:3, exp:"表见代理的要件：行为人无代理权、有使相对人相信其有代理权的权利外观、相对人善意且无过失。表见代理不需要被代理人追认即发生有权代理的效果。", chapter:"第五章 代理"},
    {q:"关于代理中的'自己代理'，以下哪项正确？", opts:["代理人以被代理人名义与自己实施民事法律行为，一般被禁止","自己代理一律有效","自己代理不需要被代理人同意","自己代理对代理人有利时应予承认"], ans:0, diff:2, exp:"《民法典》第168条规定，代理人以被代理人名义与自己实施民事法律行为（自己代理）是禁止的，但被代理人同意或追认的除外。", chapter:"第五章 代理"},
    {q:"以下关于无权代理相对人的催告权，哪项正确？", opts:["相对人可催告被代理人自收到通知之日起30日内予以追认","相对人不能催告","催告期限为15日","被代理人不能追认"], ans:0, diff:1, exp:"《民法典》第171条规定，相对人可以催告被代理人自收到通知之日起30日内予以追认。被代理人未作表示的，视为拒绝追认。", chapter:"第五章 代理"},
    {q:"关于转委托代理（复代理），下列说法正确的是？", opts:["转委托须经被代理人同意或追认，紧急情况下为维护被代理人利益需要转委托的除外","代理人可以不经被代理人同意自行转委托","转委托后原代理人不再承担任何责任","复代理人以原代理人的名义从事代理活动"], ans:0, diff:3, exp:"《民法典》第169条规定，代理人需要转委托第三人代理的，应当取得被代理人的同意或者追认；紧急情况下为维护被代理人利益需要转委托的除外。未经同意或追认的转委托，代理人应当对转委托的第三人的行为承担责任。", chapter:"第五章 代理"},
    {q:"代理人和相对人恶意串通，损害被代理人合法权益的，法律后果是？", opts:["代理人与相对人承担连带责任，该民事法律行为无效","代理行为有效，被代理人应接受其约束","仅由相对人承担全部责任","该行为属于可撤销行为，被代理人可申请撤销"], ans:0, diff:2, exp:"《民法典》第164条第2款规定，代理人和相对人恶意串通损害被代理人合法权益的，代理人和相对人应当承担连带责任；依第154条，恶意串通损害他人合法权益的民事法律行为无效。", chapter:"第五章 代理"},
    {q:"关于民事责任承担方式，以下哪项不属于民法典规定的方式？", opts:["行政拘留","停止侵害","赔偿损失","消除影响、恢复名誉"], ans:0, diff:1, exp:"《民法典》第179条规定了11种民事责任承担方式：停止侵害、排除妨碍、消除危险、返还财产、恢复原状、修理重作更换、继续履行、赔偿损失、支付违约金、消除影响恢复名誉、赔礼道歉。", chapter:"第六章 民事责任"},
    {q:"以下哪种情形适用无过错责任原则？", opts:["饲养动物致人损害","一般侵权责任","医疗损害责任","物件损害责任"], ans:0, diff:2, exp:"饲养动物致人损害适用无过错责任原则（《民法典》第1245条）。一般侵权适用过错责任；医疗损害以过错责任为主。无过错责任不问行为人是否有过错。", chapter:"第六章 民事责任"},
    {q:"正当防卫造成损害的，应如何承担民事责任？", opts:["不承担民事责任","承担民事责任","适当承担民事责任","减轻承担民事责任"], ans:0, diff:1, exp:"《民法典》第181条规定，因正当防卫造成损害的，不承担民事责任。正当防卫超过必要限度造成不应有损害的，承担适当的民事责任。", chapter:"第六章 民事责任"},
    {q:"紧急避险造成损害的，民事责任如何承担？", opts:["由引起险情的人承担责任","避险人不承担任何责任","由避险人全部承担","由受益人全部承担"], ans:0, diff:2, exp:"《民法典》第182条规定，因紧急避险造成损害的，由引起险情发生的人承担民事责任。危险由自然原因引起的，紧急避险人不承担民事责任，可以给予适当补偿。", chapter:"第六章 民事责任"},
    {q:"关于民事责任的免责事由，以下哪项不属于？", opts:["受害人故意，行为人仍有重大过失","不可抗力","正当防卫","紧急避险"], ans:0, diff:3, exp:"免责事由包括不可抗力、正当防卫、紧急避险、受害人故意。但受害人故意作为免责事由时通常要求行为人无过错；如果行为人仍有重大过失，可能不能完全免责。", chapter:"第六章 民事责任"},
    {q:"因违约行为同时侵害对方人身、财产权益的，受损害方能否同时主张违约责任和侵权责任？", opts:["受损害方有权选择请求承担违约责任或者侵权责任，但不能同时主张","可以同时主张违约责任和侵权责任","只能主张侵权责任","只能主张违约责任"], ans:0, diff:3, exp:"《民法典》第186条规定，因当事人一方的违约行为损害对方人身权益、财产权益的，受损害方有权选择请求其承担违约责任或者侵权责任。违约责任与侵权责任竞合时，受损害方只能择一主张。", chapter:"第六章 民事责任"},
    {q:"诉讼时效的一般期间为多久？", opts:["3年","2年","1年","5年"], ans:0, diff:1, exp:"《民法典》第188条规定，向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。", chapter:"第七章 诉讼时效与期间"},
    {q:"诉讼时效的起算点是？", opts:["权利人知道或应当知道权利受损害以及义务人之日","权利受损害之日","起诉之日","判决之日"], ans:0, diff:1, exp:"《民法典》第188条第2款规定，诉讼时效期间自权利人知道或应当知道权利受到损害以及义务人之日起计算。", chapter:"第七章 诉讼时效与期间"},
    {q:"诉讼时效中断的事由不包括？", opts:["权利人因不可抗力无法行使请求权","权利人向义务人提出履行请求","义务人同意履行义务","权利人提起诉讼或申请仲裁"], ans:0, diff:2, exp:"《民法典》第195条规定，诉讼时效中断的事由包括：向义务人提出履行请求、义务人同意履行、提起诉讼或申请仲裁等。不可抗力导致无法行使权利属于诉讼时效中止事由。", chapter:"第七章 诉讼时效与期间"},
    {q:"诉讼时效中止的法定事由不包括？", opts:["权利人向义务人提出履行请求","不可抗力","无民事行为能力人无法定代理人","继承开始后未确定继承人或遗产管理人"], ans:0, diff:3, exp:"《民法典》第194条规定了诉讼时效中止的法定事由。'向义务人提出履行请求'属于诉讼时效中断的事由（第195条），不属于中止事由。中止使时效暂停计算，中断使时效重新计算。", chapter:"第七章 诉讼时效与期间"},
    {q:"《民法典》规定，自权利受到损害之日起超过多少年的，人民法院不予保护？", opts:["二十年","三年","十年","五年"], ans:0, diff:1, exp:"《民法典》第188条第2款规定，自权利受到损害之日起超过二十年的，人民法院不予保护；有特殊情况的，人民法院可以根据权利人的申请决定延长。此为最长权利保护期间，不受中止、中断影响。", chapter:"第七章 诉讼时效与期间"},
    {q:"下列请求权中，适用诉讼时效规定的是？", opts:["请求支付违约金的权利","请求停止侵害、排除妨碍、消除危险的权利","不动产物权人请求返还财产的权利","请求支付赡养费的权利"], ans:0, diff:3, exp:"《民法典》第196条规定，下列请求权不适用诉讼时效：请求停止侵害、排除妨碍、消除危险；不动产物权和登记的动产物权的权利人请求返还财产；请求支付抚养费、赡养费或扶养费。违约金请求权属于债权请求权，适用3年诉讼时效。", chapter:"第七章 诉讼时效与期间"}
  ],

  "民法·分则": [
  {q:"物权的种类包括？", opts:["所有权、用益物权、担保物权","仅所有权","所有权和债权","占有和所有"], ans:0, diff:1, exp:"《民法典》第114条规定，物权包括所有权、用益物权和担保物权。物权法定原则要求物权的种类和内容由法律规定。", chapter:"第一章 物权与所有权"},
  {q:"不动产物权的设立、变更、转让和消灭，何时发生效力？", opts:["依法登记时","签订合同时","交付时","付款时"], ans:0, diff:1, exp:"《民法典》第209条规定，不动产物权的设立、变更、转让和消灭，经依法登记发生效力；未经登记不发生效力。但法律另有规定的除外（如国家所有的自然资源）。", chapter:"第一章 物权与所有权"},
  {q:"动产物权的转让，何时发生效力？", opts:["交付时","签订合同时","登记时","付款时"], ans:0, diff:1, exp:"《民法典》第224条规定，动产物权的设立和转让自交付时发生效力，但法律另有规定的除外。交付有多种方式：现实交付、简易交付、指示交付、占有改定。", chapter:"第一章 物权与所有权"},
  {q:"关于物权法定原则，下列说法正确的是？", opts:["物权的种类和内容由法律规定，当事人不得自由创设","当事人可以自由约定物权种类","物权的种类法定，但内容可由当事人约定","交易习惯可以创设物权"], ans:0, diff:1, exp:"《民法典》第116条规定，物权的种类和内容，由法律规定。当事人不得创设法律未规定的物权类型。", chapter:"第一章 物权与所有权"},
  {q:"关于业主的建筑物区分所有权，下列说法正确的是？", opts:["业主对专有部分享有所有权，对共有部分享有共有和共同管理的权利","业主可以放弃共有部分的权利从而免缴物业费","共有部分归物业服务人所有","业主对专有部分不得转让"], ans:0, diff:1, exp:"《民法典》第271条规定，业主对建筑物内的专有部分享有所有权，对专有部分以外的共有部分享有共有和共同管理的权利。业主不得以放弃权利为由不履行义务（第273条）。", chapter:"第一章 物权与所有权"},
  {q:"关于善意取得，下列说法正确的是？", opts:["无处分权人转让财产，受让人善意且以合理价格受让并完成登记或交付的，可取得所有权","善意取得仅适用于动产","盗赃物可以适用善意取得","无偿受让财产也可适用善意取得"], ans:0, diff:3, exp:"《民法典》第311条规定，善意取得须同时具备：受让人善意、以合理价格转让、应当登记的已登记（不需要登记的已交付）。遗失物原则上不适用善意取得（第312条），盗赃物一般也不适用。", chapter:"第一章 物权与所有权"},
  {q:"关于用益物权，下列说法正确的是？", opts:["用益物权人对他人所有的不动产或动产，依法享有占有、使用和收益的权利","用益物权以担保债权实现为目的","用益物权人对标的物享有处分权","用益物权属于自物权"], ans:0, diff:1, exp:"《民法典》第323条规定，用益物权人对他人所有的不动产或动产，依法享有占有、使用、收益的权利。以担保债权实现为目的的是担保物权；用益物权为他物权，权利人不享有处分权。", chapter:"第二章 用益物权"},
  {q:"关于宅基地使用权，下列说法正确的是？", opts:["宅基地使用权人有权依法利用集体土地建造住宅及其附属设施","宅基地所有权属于宅基地使用权人","城镇居民可以依法购买农村宅基地建房","宅基地使用权可以任意抵押"], ans:0, diff:1, exp:"《民法典》第362条规定，宅基地使用权人依法对集体所有的土地享有占有、使用的权利，有权利用该土地建造住宅及附属设施。宅基地所有权属于集体，宅基地使用权不得抵押（第399条）。", chapter:"第二章 用益物权"},
  {q:"住宅建设用地使用权期限届满的，应当如何处理？", opts:["由国家无偿收回","自动续期","必须重新申请并经批准后方可继续使用","使用权消灭，须重新出让"], ans:1, diff:1, exp:"《民法典》第359条规定，住宅建设用地使用权期限届满的，自动续期；续期费用的缴纳或者减免，依照法律、行政法规的规定办理。", chapter:"第二章 用益物权"},
  {q:"关于土地承包经营权的设立，下列说法正确的是？", opts:["自取得土地承包经营权证时设立","未经登记不发生设立效力","自土地承包经营权合同生效时设立","自办理登记时设立"], ans:2, diff:2, exp:"《民法典》第333条规定，土地承包经营权自土地承包经营权合同生效时设立。第335条规定，土地承包经营权互换、转让未经登记不得对抗善意第三人，即采登记对抗主义。", chapter:"第二章 用益物权"},
  {q:"关于地役权的设立，下列说法正确的是？", opts:["地役权自登记时设立","地役权可以脱离需役地单独转让","地役权自地役权合同生效时设立，未经登记不得对抗善意第三人","地役权属于所有权的一种"], ans:2, diff:3, exp:"《民法典》第374条规定，地役权自地役权合同生效时设立，未经登记不得对抗善意第三人（登记对抗主义）。地役权不得与需役地分离而单独转让（第380条）。", chapter:"第二章 用益物权"},
  {q:"关于居住权，下列说法正确的是？", opts:["居住权自居住权合同生效时设立","设立居住权无须签订书面合同","居住权可以转让、继承","居住权自登记时设立"], ans:3, diff:2, exp:"《民法典》第368条规定，设立居住权应当采用书面形式订立合同并申请登记，居住权自登记时设立（登记生效主义）。第369条规定，居住权不得转让、继承。", chapter:"第二章 用益物权"},
  {q:"以下哪种不属于担保物权？", opts:["地上权","抵押权","质权","留置权"], ans:0, diff:1, exp:"地上权属于用益物权（建设用地使用权等），不属于担保物权。担保物权包括抵押权、质权和留置权三种。", chapter:"第三章 担保物权"},
  {q:"抵押权设立的要件是什么？", opts:["不动产抵押权自登记时设立，动产抵押权自合同生效时设立","一律自登记时设立","一律自合同签订时设立","一律自交付时设立"], ans:0, diff:3, exp:"《民法典》第402-403条规定，不动产抵押权自登记时设立（登记生效主义）；动产抵押权自抵押合同生效时设立，未经登记不得对抗善意第三人（登记对抗主义）。", chapter:"第三章 担保物权"},
  {q:"留置权的成立条件不包括？", opts:["债权人占有债务人的动产与债权属于同一法律关系","债权人合法占有债务人的动产","债务已届清偿期","债权人和债务人有明确约定"], ans:0, diff:2, exp:"留置权成立要件：合法占有债务人动产、债权已届清偿期、占有与债权属于同一法律关系（企业之间留置除外）。留置权是法定担保物权，不需要当事人约定。", chapter:"第三章 担保物权"},
  {q:"根据《民法典》，下列财产中不得设定抵押权的是？", opts:["土地所有权","建设用地使用权","正在建造的建筑物","生产设备、原材料、半成品"], ans:0, diff:1, exp:"《民法典》第399条规定，土地所有权、宅基地（法律允许的除外）、学校幼儿园医院等公益设施、权属有争议或依法被查封扣押的财产等不得抵押。建设用地使用权、在建建筑物、生产设备均可抵押。", chapter:"第三章 担保物权"},
  {q:"关于动产质权的设立，下列说法正确的是？", opts:["动产质权自出质人交付质押财产时设立","动产质权自质押合同签订时设立","权利质权一律无须登记","质权人可以使用质押财产"], ans:0, diff:1, exp:"《民法典》第429条规定，动产质权自出质人交付质押财产时设立。质权人负有妥善保管质押财产的义务，不得擅自使用、处分（第432条）。", chapter:"第三章 担保物权"},
  {q:"抵押期间，关于抵押人转让抵押财产，下列说法正确的是？", opts:["抵押人可以转让抵押财产，无须经抵押权人同意，但应通知抵押权人","抵押期间抵押财产一律不得转让","转让抵押财产必须经抵押权人书面同意，否则无效","转让抵押财产后抵押权消灭"], ans:0, diff:3, exp:"《民法典》第406条改变了原《物权法》第191条：抵押人可以转让抵押财产，无须经抵押权人同意，但应当及时通知抵押权人；抵押权不受影响（抵押权追及效力），抵押权人可以请求就转让价款提前清偿或者提存。", chapter:"第三章 担保物权"},
  {q:"合同订立的方式是？", opts:["要约和承诺","要约邀请和承诺","意向书和协议","谈判和协议"], ans:0, diff:1, exp:"《民法典》第471条规定，当事人订立合同可以采取要约、承诺方式。要约是希望和他人订立合同的意思表示；承诺是受要约人同意要约的意思表示。", chapter:"第四章 合同的订立与效力"},
  {q:"以下哪种属于要约邀请？", opts:["商业广告一般视为要约邀请","明确表示受约束的广告","包含具体交易条件的报价","标明价格的商品陈列"], ans:0, diff:2, exp:"《民法典》第473条规定，要约邀请是希望他人向自己发出要约的表示。拍卖公告、招标公告、商业广告等为要约邀请。但商业广告内容符合要约条件的，视为要约。", chapter:"第四章 合同的订立与效力"},
  {q:"承诺的生效时间是什么？", opts:["承诺通知到达要约人时","承诺人发出承诺时","要约人阅读承诺时","双方签字时"], ans:0, diff:1, exp:"《民法典》第484条规定，承诺通知到达要约人时生效。承诺不需要通知的，根据交易习惯或要约要求作出承诺行为时生效。我国采取'到达主义'。", chapter:"第四章 合同的订立与效力"},
  {q:"格式条款无效的情形不包括？", opts:["提供方对条款作了提示说明","具有无效民事法律行为情形","不合理免除或减轻提供方责任","加重对方责任或限制对方主要权利"], ans:0, diff:2, exp:"《民法典》第497条规定，格式条款无效的情形：(1)具有无效民事法律行为情形；(2)不合理免除或减轻提供方责任、加重对方责任、限制对方主要权利；(3)排除对方主要权利。提供了提示说明的有效格式条款是合法的。", chapter:"第四章 合同的订立与效力"},
  {q:"民间借贷利率的最高保护标准是什么？", opts:["合同成立时一年期LPR的四倍","年利率24%","年利率36%","年利率15%"], ans:0, diff:1, exp:"根据最高人民法院关于民间借贷的司法解释，民间借贷利率不得超过合同成立时一年期贷款市场报价利率（LPR）的四倍。", chapter:"第四章 合同的订立与效力"},
  {q:"定金合同的生效要件是？", opts:["定金合同自实际交付定金时成立","定金合同自签订时成立","定金合同自公证时成立","定金合同自登记时成立"], ans:0, diff:1, exp:"《民法典》第586条规定，定金合同自实际交付定金时成立。定金合同为实践合同（要物合同），仅有约定而无实际交付，定金合同不成立。", chapter:"第四章 合同的订立与效力"},
  {q:"赠与合同的性质是什么？", opts:["诺成合同","实践合同","要式合同","有偿合同"], ans:0, diff:2, exp:"《民法典》第657条规定，赠与合同是赠与人将自己的财产无偿给予受赠人，受赠人表示接受赠与的合同。赠与合同是诺成合同，赠与人在财产权利转移前可撤销（但公证赠与和公益赠与除外）。", chapter:"第四章 合同的订立与效力"},
  {q:"以下关于借款合同利息，哪项正确？", opts:["禁止高利放贷，借款利率不得违反国家有关规定","借款利息可以任意约定","所有借款都必须支付利息","借款利息不得超过LPR的三倍"], ans:0, diff:2, exp:"《民法典》第680条规定，禁止高利放贷，借款的利率不得违反国家有关规定。自然人之间借款对利息没有约定的，视为没有利息。民间借贷利率上限为LPR的四倍。", chapter:"第四章 合同的订立与效力"},
  {q:"承揽合同与买卖合同的区别主要在于？", opts:["承揽合同以完成特定工作并交付工作成果为目的，买卖合同以转移所有权为目的","两者名称不同","两者都没有区别","买卖合同可以有验收"], ans:0, diff:2, exp:"承揽合同的标的是完成特定工作并交付工作成果，材料可以由定作人提供或承揽人自备。买卖合同以转移标的物所有权为目的。来料加工通常属于承揽合同。", chapter:"第四章 合同的订立与效力"},
  {q:"委托合同与行纪合同的主要区别？", opts:["行纪人以自己名义从事贸易活动，委托人以委托人名义活动","两者完全相同","行纪合同为无偿合同","委托合同为要式合同"], ans:0, diff:2, exp:"行纪人以自己名义与第三人订立合同，行纪人直接享有合同权利、承担合同义务。委托人一般以委托人名义活动。行纪合同一般限于贸易活动（行纪），委托人可以是任何民事法律行为。", chapter:"第四章 合同的订立与效力"},
  {q:"合同的法定解除情形不包括？", opts:["一方当事人主观上不愿继续履行","因不可抗力致使不能实现合同目的","一方明确表示不履行主要债务","一方迟延履行经催告后仍未履行"], ans:0, diff:2, exp:"《民法典》第563条规定了法定解除情形：不可抗力、预期违约、迟延履行经催告仍不履行、根本违约等。单方不愿履行不能自动产生解除权，需双方协商或满足法定条件。", chapter:"第五章 合同的履行与违约责任"},
  {q:"违约金与实际损失的关系，以下哪项正确？", opts:["违约金过分高于损失的，可请求适当减少","违约金必须等于实际损失","违约金不受实际损失影响","违约金不能调整"], ans:0, diff:1, exp:"《民法典》第585条规定，约定的违约金过分高于造成的损失的，人民法院或仲裁机构可以根据当事人的请求予以适当减少。违约金低于损失的，可请求增加。", chapter:"第五章 合同的履行与违约责任"},
  {q:"关于保证方式，民法典的默认规则是什么？", opts:["一般保证","连带责任保证","按份保证","混合保证"], ans:0, diff:2, exp:"《民法典》第686条规定，当事人在保证合同中对保证方式没有约定或约定不明确的，按照一般保证承担保证责任。这与原《担保法》的连带责任保证默认规则不同。", chapter:"第五章 合同的履行与违约责任"},
  {q:"关于租赁期限，以下哪项正确？", opts:["租赁期限不得超过20年，超过部分无效","租赁期限可以无限长","租赁期限不得超过10年","租赁期限不得超过30年"], ans:0, diff:1, exp:"《民法典》第705条规定，租赁期限不得超过20年。超过20年的，超过部分无效。租赁期限届满可以续订，但续订后的租赁期限也不得超过20年。", chapter:"第五章 合同的履行与违约责任"},
  {q:"物业服务合同的双方当事人是？", opts:["业主和物业服务人","业主委员会和物业服务人","业主大会和物业服务人","开发商和物业服务人"], ans:0, diff:1, exp:"《民法典》第937条规定，物业服务合同是业主和物业服务人订立的合同。业主委员会代表业主与物业服务人订立合同。", chapter:"第五章 合同的履行与违约责任"},
  {q:"关于租赁合同中承租人的优先购买权，以下哪项正确？", opts:["出租人出卖租赁房屋的，应在出卖前合理期限内通知承租人，承租人享有优先购买权","承租人的优先购买权可以对抗所有购买人","拍卖房屋时承租人无优先购买权","优先购买权无时间限制"], ans:0, diff:3, exp:"《民法典》第726条规定，出租人出卖租赁房屋的，应在出卖前合理期限内通知承租人，承租人享有以同等条件优先购买的权利。但房屋按份共有人行使优先购买权或出租人将房屋出卖给近亲属的除外。", chapter:"第五章 合同的履行与违约责任"},
  {q:"关于保管合同中保管人的责任，以下哪项正确？", opts:["无偿保管人仅就故意或重大过失造成保管物毁损灭失承担赔偿责任","保管人对所有损失都承担责任","保管人可以任意使用保管物","保管人无需尽任何注意义务"], ans:0, diff:2, exp:"《民法典》第897条规定，无偿保管人证明自己没有故意或重大过失的，不承担赔偿责任。有偿保管人需尽一般注意义务。", chapter:"第五章 合同的履行与违约责任"},
  {q:"中介合同（居间合同）中，委托人'跳单'的法律后果？", opts:["委托人利用中介人提供的信息绕开中介人直接订立合同的，应向中介人支付报酬","委托人可以任意跳单","跳单无需支付任何费用","中介人自动丧失报酬请求权"], ans:0, diff:1, exp:"《民法典》第965条规定，委托人接受中介人的服务后，利用中介人提供的交易机会或媒介服务，绕开中介人直接订立合同的，应当向中介人支付报酬。", chapter:"第五章 合同的履行与违约责任"},
  {q:"合伙合同中的利润分配，约定不明确的如何处理？", opts:["由合伙人协商决定；协商不成的按实缴出资比例分配；无法确定出资比例的，由合伙人平均分配","由法院判决","利润归出资最多的合伙人","利润平均分配"], ans:0, diff:2, exp:"《民法典》第972条规定，利润分配按约定办理；无约定或约定不明确的，由合伙人协商决定；协商不成的按实缴出资比例分配；无法确定出资比例的，由合伙人平均分配。", chapter:"第五章 合同的履行与违约责任"},
  {q:"无因管理的构成要件不包括？", opts:["管理人事后报告","没有法定或约定义务","管理他人事务","为避免他人利益受损"], ans:0, diff:2, exp:"无因管理的要件：没有法定或约定义务、管理他人事务、为避免他人利益受损。不需要管理人主观上'为他人'（法条文义），也不以事后报告为成立要件。但管理人需及时通知受益人。", chapter:"第五章 合同的履行与违约责任"},
  {q:"不当得利的返还范围，善意得利人与恶意得利人有何不同？", opts:["善意得利人仅返还现存利益；恶意得利人返还全部所得并赔偿损失","两者返还范围完全相同","善意得利人无需返还","恶意得利人无需返还"], ans:0, diff:3, exp:"《民法典》第986-987条规定，善意得利人（不知无法律依据）仅须返还现存利益；恶意得利人（明知无法律依据）须返还全部所得，造成损害的还应赔偿损失。", chapter:"第五章 合同的履行与违约责任"},
  {q:"关于人格权，以下哪项不属于民法典规定的具体人格权？", opts:["荣誉权","生命权","姓名权","隐私权"], ans:0, diff:3, exp:"民法典规定了生命权、身体权、健康权、姓名权、名称权、肖像权、名誉权、荣誉权、隐私权等具体人格权。荣誉权属于具体人格权之一。注意本题为反向陷阱——荣誉权确实属于人格权。", chapter:"第六章 人格权"},
  {q:"以下哪种不属于侵害隐私权的行为？", opts:["经本人同意后公开其私密信息","以电话短信等方式侵扰他人私人生活","拍摄窥视他人私密空间","处理他人私密信息"], ans:0, diff:1, exp:"《民法典》第1033条规定了侵害隐私权的行为类型：侵扰私人生活、进入拍摄窥视私密空间/活动/部位、处理私密信息等。经本人同意的行为一般不构成侵害隐私权。", chapter:"第六章 人格权"},
  {q:"关于精神损害赔偿，以下哪种情况可主张？", opts:["侵害自然人人身权益造成严重精神损害","纯财产损失","轻微人身损害","合同违约"], ans:0, diff:1, exp:"《民法典》第1183条规定，侵害自然人人身权益造成严重精神损害的，被侵权人有权请求精神损害赔偿。因故意或重大过失侵害自然人具有人身意义的特定物造成严重精神损害的也可主张。", chapter:"第六章 人格权"},
  {q:"下列哪一行为不构成对肖像权的侵害？", opts:["未经同意在商业广告中使用他人肖像","为个人学习、课堂教学在必要范围内使用他人已经公开的肖像","丑化、污损他人肖像","未经同意公开他人肖像"], ans:1, diff:2, exp:"《民法典》第1019条规定，未经肖像权人同意，不得制作、使用、公开其肖像。第1020条规定，为个人学习、艺术欣赏、课堂教学等目的在必要范围内合理使用的，不构成侵权。", chapter:"第六章 人格权"},
  {q:"关于死者人格利益的保护，下列说法正确的是？", opts:["人死后人格利益一律不受法律保护","死者肖像可以由任何人在商业广告中使用","死者的姓名、肖像、名誉、荣誉、隐私、遗体等受到侵害的，其近亲属可依法请求行为人承担民事责任","死者人格利益不受任何限制地自由利用"], ans:2, diff:2, exp:"《民法典》第994条规定，死者的姓名、肖像、名誉、荣誉、隐私、遗体等受到侵害的，其近亲属有权依法请求行为人承担民事责任。", chapter:"第六章 人格权"},
  {q:"关于处理个人信息应当遵循的原则，下列说法正确的是？", opts:["合法、正当、必要原则，不得过度处理","只要经同意即可任意处理个人信息","个人信息仅指隐私信息","处理个人信息无须明示处理目的、方式和范围"], ans:0, diff:1, exp:"《民法典》第1035条规定，处理个人信息应当遵循合法、正当、必要原则，征得自然人或其监护人同意（法律、行政法规另有规定的除外），明示处理目的、方式、范围，不得过度处理。", chapter:"第六章 人格权"},
  {q:"结婚的法定婚龄是多少？", opts:["男22周岁，女20周岁","男25周岁，女23周岁","男女均为20周岁","男女均为18周岁"], ans:0, diff:1, exp:"《民法典》第1047条规定，结婚年龄男不得早于22周岁，女不得早于20周岁。", chapter:"第七章 婚姻家庭"},
  {q:"以下哪种情形属于无效婚姻？", opts:["重婚","一方婚前隐瞒已治愈的疾病","受胁迫的婚姻","未达法定婚龄但已补正的"], ans:0, diff:2, exp:"《民法典》第1051条规定无效婚姻：重婚、有禁止结婚的亲属关系、未到法定婚龄。受胁迫的婚姻属于可撤销婚姻（第1052条）。一方患有重大疾病未告知的也属可撤销（第1053条）。", chapter:"第七章 婚姻家庭"},
  {q:"夫妻共同债务的认定标准是什么？", opts:["夫妻双方共同签名或一方事后追认等共同意思表示所负的债务，以及一方在婚姻期间以个人名义为家庭日常生活需要所负的债务","婚姻期间所有债务都是共同债务","以个人名义的所有债务都不是共同债务","婚前的所有债务都是共同债务"], ans:0, diff:3, exp:"《民法典》第1064条规定，夫妻双方共同签名或一方事后追认的债务属共同债务；一方在婚姻期间以个人名义为家庭日常生活需要所负的债务属共同债务。超出家庭日常生活需要的个人债务不属于共同债务，除非债权人能证明用于共同生活或经营。", chapter:"第七章 婚姻家庭"},
  {q:"离婚冷静期的期限是多少？", opts:["30天","15天","60天","90天"], ans:0, diff:1, exp:"《民法典》第1077条规定，自婚姻登记机关收到离婚登记申请之日起30日内，任何一方不愿离婚的，可撤回申请。30日期满后30日内，双方应亲自到婚姻登记机关申请发给离婚证；未申请的视为撤回。", chapter:"第七章 婚姻家庭"},
  {q:"下列哪一情形，无过错方有权请求离婚损害赔偿？", opts:["夫妻感情不和长期分居","一方与他人同居","双方因性格差异无法共同生活","一方婚前隐瞒轻微性格缺陷"], ans:1, diff:2, exp:"《民法典》第1091条规定，重婚、与他人同居、实施家庭暴力、虐待遗弃家庭成员、有其他重大过错等情形，无过错方有权请求离婚损害赔偿。长期分居、性格不合等不属于法定情形。", chapter:"第七章 婚姻家庭"},
  {q:"关于非婚生子女的权利，下列说法正确的是？", opts:["非婚生子女享有与婚生子女同等的权利，任何人不得加以危害和歧视","非婚生子女不享有继承权","非婚生子女的生父无须负担抚养费","非婚生子女只能随生母生活"], ans:0, diff:1, exp:"《民法典》第1071条规定，非婚生子女享有与婚生子女同等的权利，任何人不得加以危害和歧视；不直接抚养非婚生子女的生父或生母，应当负担未成年子女或不能独立生活的成年子女的抚养费。", chapter:"第七章 婚姻家庭"},
  {q:"第一顺序法定继承人包括？", opts:["配偶、子女、父母","配偶、子女、父母、兄弟姐妹","配偶、子女","配偶、父母、祖父母"], ans:0, diff:1, exp:"《民法典》第1127条规定，第一顺序继承人：配偶、子女、父母。第二顺序：兄弟姐妹、祖父母、外祖父母。继承开始后由第一顺序继承人继承，没有第一顺序的由第二顺序继承。", chapter:"第八章 继承"},
  {q:"遗嘱的形式不包括？", opts:["口头遗嘱（非危急情况）","自书遗嘱","代书遗嘱","打印遗嘱"], ans:0, diff:3, exp:"《民法典》第1134-1139条规定了6种遗嘱形式：自书遗嘱、代书遗嘱、打印遗嘱、录音录像遗嘱、口头遗嘱（仅限危急情况）、公证遗嘱。普通情况下的口头遗嘱无效。", chapter:"第八章 继承"},
  {q:"继承开始后，被继承人生前订立了遗赠扶养协议、遗嘱的，遗产应如何分配？", opts:["有遗赠扶养协议的，按照协议办理","法定继承优先于遗嘱继承","遗嘱继承优先于遗赠扶养协议","遗赠优先于遗赠扶养协议"], ans:0, diff:2, exp:"《民法典》第1123条规定，继承开始后，按照法定继承办理；有遗嘱的，按照遗嘱继承或者遗赠办理；有遗赠扶养协议的，按照协议办理。遗赠扶养协议的效力优先。", chapter:"第八章 继承"},
  {q:"关于代位继承，下列说法正确的是？", opts:["被继承人的子女先于被继承人死亡的，由被继承人的子女的直系晚辈血亲代位继承","代位继承只适用于遗嘱继承","代位继承人只能继承遗产的一小部分","被继承人的兄弟姐妹先于其死亡的，其子女一律不能代位继承"], ans:0, diff:2, exp:"《民法典》第1128条规定，被继承人的子女先于被继承人死亡的，由其子女的直系晚辈血亲代位继承；被继承人的兄弟姐妹先于被继承人死亡的，由其兄弟姐妹的子女代位继承。代位继承人一般只能继承被代位继承人有权继承的份额。", chapter:"第八章 继承"},
  {q:"遗嘱人立有数份内容相抵触的遗嘱，应当以哪一份为准？", opts:["以最后的遗嘱为准","以公证遗嘱为准","以最先订立的遗嘱为准","以内容最全面的一份为准"], ans:0, diff:2, exp:"《民法典》第1142条规定，立有数份遗嘱，内容相抵触的，以最后的遗嘱为准。注意：公证遗嘱不再具有当然优先效力（原《继承法》曾规定公证遗嘱效力优先）。", chapter:"第八章 继承"},
  {q:"关于遗嘱处分遗产的限制，下列说法正确的是？", opts:["遗嘱应当为缺乏劳动能力又没有生活来源的继承人保留必要的遗产份额","遗嘱可以处分全部遗产而不受限制","必留份制度仅保护法定继承人以外的人","立遗嘱人无须照顾未成年继承人的利益"], ans:0, diff:1, exp:"《民法典》第1141条规定，遗嘱应当为缺乏劳动能力又没有生活来源的继承人保留必要的遗产份额，此为必留份制度。", chapter:"第八章 继承"},
  {q:"侵权责任的归责原则不包括？", opts:["公平责任原则作为一般归责原则","过错责任原则","无过错责任原则","过错推定原则"], ans:0, diff:2, exp:"侵权责任的主要归责原则是过错责任原则（含过错推定）和无过错责任原则。公平责任（《民法典》第1186条）只适用于法律明确规定的情形，不是一般的归责原则。", chapter:"第九章 侵权责任"},
  {q:"网络侵权中'通知-删除'规则，网络服务提供者在收到通知后未及时采取措施的，对损害扩大部分应？", opts:["承担连带责任","不承担任何责任","承担全部责任","单独承担责任"], ans:0, diff:2, exp:"《民法典》第1195条规定，网络服务提供者接到通知后应及时将该通知转送相关网络用户，并根据初步证据和服务类型采取必要措施；未及时采取措施的，对损害的扩大部分与该网络用户承担连带责任。", chapter:"第九章 侵权责任"},
  {q:"高空抛物致人损害，难以确定具体侵权人的，由谁承担责任？", opts:["可能加害的建筑物使用人给予补偿","物业公司承担全部责任","全体业主承担连带责任","受害人不获赔偿"], ans:0, diff:3, exp:"《民法典》第1254条规定，难以确定具体侵权人的，除能证明自己不是侵权人外，由可能加害的建筑物使用人给予补偿。物业公司未采取必要安保措施的，承担未履行义务范围内的补充责任。公安机关应依法及时调查。", chapter:"第九章 侵权责任"},
  {q:"产品责任中，被侵权人可以向谁主张赔偿？", opts:["可以向产品的生产者请求赔偿，也可以向产品的销售者请求赔偿","只能向生产者请求赔偿","只能向销售者请求赔偿","先向销售者请求，再向生产者请求"], ans:0, diff:2, exp:"《民法典》第1203条规定，因产品缺陷造成损害的，被侵权人可以向产品的生产者请求赔偿，也可以向产品的销售者请求赔偿。二者承担不真正连带责任。", chapter:"第九章 侵权责任"},
  {q:"环境污染责任的举证责任如何分配？", opts:["因果关系推定：污染者需证明其行为与损害之间不存在因果关系","被侵权人需证明污染行为和损害的全部因果关系","双方各自承担举证责任","不需要证明因果关系"], ans:0, diff:3, exp:"《民法典》第1230条规定，环境污染责任实行因果关系推定（举证责任倒置）：被侵权人仅需证明污染行为和损害存在，污染者需就法律规定的不承担责任或减轻责任的情形及其行为与损害之间不存在因果关系承担举证责任。", chapter:"第九章 侵权责任"},
  {q:"关于网络侵权中'反通知'制度，以下哪项正确？", opts:["网络用户接到转送通知后可以向网络服务提供者提交不存在侵权行为的声明","网络用户不能反驳通知","反通知由法院审理","网络服务提供者收到反通知后应立即恢复内容"], ans:0, diff:3, exp:"《民法典》第1196条规定，网络用户接到转送通知后可以向网络服务提供者提交不存在侵权行为的声明。网络服务提供者转送该声明后，权利人不得再通知删除，而应在合理期限内投诉或起诉。", chapter:"第九章 侵权责任"}
],

  "宪法": [
  {q:"宪法是国家的根本法，下列哪一选项最能体现宪法的根本法地位？", opts:["宪法规定国家的根本制度和根本任务，其内容具有根本性","宪法与其他法律效力相同，仅名称不同","宪法可以随时被普通法律修改","宪法仅规定国家机关的组织，不涉及公民权利"], ans:0, diff:1, exp:"宪法在内容上规定国家的根本制度、根本任务和公民的基本权利义务等最根本最重要的问题，其制定和修改程序比普通法律严格、效力高于普通法律，因而是国家的根本法。", chapter:"第一章 宪法总论"},
  {q:"关于宪法效力的表述，下列哪一选项正确？", opts:["一切法律、行政法规和地方性法规都不得同宪法相抵触","普通法律可以依据需要改变宪法的规定","宪法只对国家机关产生效力，对公民没有约束力","全国人大制定的法律在效力上高于宪法"], ans:0, diff:1, exp:"《宪法》第5条规定，一切法律、行政法规和地方性法规都不得同宪法相抵触。宪法具有最高的法律效力，是一切立法的依据。", chapter:"第一章 宪法总论"},
  {q:"关于宪法的制定权，下列哪一表述符合宪法学通说？", opts:["制宪权属于人民，人民是制宪权的最终所有者","制宪权属于全国人大常委会","制宪权属于国务院","制宪权属于最高人民法院"], ans:0, diff:3, exp:"宪法学通说认为制宪权属于人民。我国宪法由全国人民代表大会通过，而全国人民代表大会是人民行使国家权力的机关，人民是制宪权的最终所有者。", chapter:"第一章 宪法总论"},
  {q:"以是否具有统一的宪法典为标准，宪法可分为？", opts:["成文宪法与不成文宪法","刚性宪法与柔性宪法","钦定宪法与民定宪法","原始宪法与派生宪法"], ans:0, diff:2, exp:"以是否有统一的宪法典为标准，宪法分为成文宪法与不成文宪法，我国属成文宪法国家；以修改程序是否严格为标准分为刚性宪法与柔性宪法；以制定机关为标准分为钦定、民定、协定宪法。", chapter:"第一章 宪法总论"},
  {q:"下列对宪法规范特点的表述，哪一选项是错误的？", opts:["宪法规范具有很强的原则性，内容空洞抽象，无需其他法律具体化即可直接适用","宪法规范具有最高的法律效力","宪法规范调整社会关系的范围十分广泛","宪法规范的修改程序一般比普通法律严格"], ans:0, diff:3, exp:"宪法规范具有根本性、最高效力、原则性和稳定性等特点。宪法规范虽多为原则性规定，但并非空洞抽象，其内容须通过普通立法具体化方能适用，故A选项表述错误。", chapter:"第一章 宪法总论"},
  {q:"我国现行宪法是哪一年通过的？", opts:["1982年","1954年","1975年","1978年"], ans:0, diff:1, exp:"我国现行宪法是1982年12月4日由第五届全国人民代表大会第五次会议通过的，历经1988年、1993年、1999年、2004年、2018年五次修正。", chapter:"第二章 宪法的历史发展"},
  {q:"1982年宪法通过后，我国先后共进行了几次修正？", opts:["5次","4次","6次","7次"], ans:0, diff:2, exp:"1982年宪法先后于1988年、1993年、1999年、2004年、2018年进行了五次修正，2018年修正案是第五次修正。", chapter:"第二章 宪法的历史发展"},
  {q:"我国历史上第一部宪法性文件是？", opts:["1908年《钦定宪法大纲》","1912年《中华民国临时约法》","1949年《共同纲领》","1954年宪法"], ans:0, diff:2, exp:"1908年清政府颁布的《钦定宪法大纲》是我国历史上第一部宪法性文件。《中华民国临时约法》是中国历史上第一部资产阶级共和国性质的宪法性文件；《共同纲领》在新中国成立初期起临时宪法作用。", chapter:"第二章 宪法的历史发展"},
  {q:"关于1954年宪法的表述，下列哪一选项正确？", opts:["1954年宪法是我国第一部社会主义类型的宪法","1954年宪法由全国人大常委会通过","1954年宪法规定我国实行联邦制","1954年宪法是现行宪法"], ans:0, diff:2, exp:"1954年宪法由第一届全国人民代表大会第一次会议于1954年9月20日通过，是我国历史上第一部社会主义类型的宪法。现行宪法是1982年宪法，而非1954年宪法。", chapter:"第二章 宪法的历史发展"},
  {q:"我国的国家宪法日是每年的哪一天？", opts:["12月4日","10月1日","12月10日","1月1日"], ans:0, diff:1, exp:"2014年11月1日十二届全国人大常委会第十一次会议决定，将现行宪法通过、公布施行的12月4日设立为国家宪法日。", chapter:"第二章 宪法的历史发展"},
  {q:"中华人民共和国的一切权力属于谁？", opts:["人民","全国人民代表大会","国务院","国家主席"], ans:0, diff:1, exp:"《宪法》第2条规定，中华人民共和国的一切权力属于人民。人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。", chapter:"第三章 宪法的指导思想和基本原则"},
  {q:"2018年宪法修正案新增的指导思想是？", opts:["习近平新时代中国特色社会主义思想","邓小平理论","'三个代表'重要思想","科学发展观"], ans:0, diff:3, exp:"2018年宪法修正案将习近平新时代中国特色社会主义思想写入宪法序言，确立为国家的指导思想。此前历次修正分别增加了邓小平理论（1999）、'三个代表'重要思想（2004）、科学发展观（2018）。", chapter:"第三章 宪法的指导思想和基本原则"},
  {q:"我国宪法规定，国家机构实行什么原则？", opts:["民主集中制","三权分立","联邦主义","一院制"], ans:0, diff:1, exp:"《宪法》第3条规定，中华人民共和国的国家机构实行民主集中制的原则。民主集中制既是国家机构组织与活动的基本原则，也是人民主权原则的体现。", chapter:"第三章 宪法的指导思想和基本原则"},
  {q:"下列哪一项不是我国宪法的基本原则？", opts:["三权分立与制衡原则","人民主权原则","基本人权原则","法治原则"], ans:0, diff:3, exp:"我国宪法确认的基本原则包括人民主权原则、基本人权原则、法治原则以及权力制约和监督原则（以民主集中制为组织形式）。三权分立是西方国家的政权组织原则，我国实行的是民主集中制。", chapter:"第三章 宪法的指导思想和基本原则"},
  {q:"我国宪法规定，国家工作人员就职时应当依照法律规定？", opts:["公开进行宪法宣誓","向国务院宣誓","向国家主席宣誓","无须任何宣誓程序"], ans:0, diff:1, exp:"《宪法》第27条第3款（2018年修宪新增）规定，国家工作人员就职时应当依照法律规定公开进行宪法宣誓，以增强国家工作人员的宪法意识、维护宪法权威。", chapter:"第三章 宪法的指导思想和基本原则"},
  {q:"我国的国家性质（国体）是什么？", opts:["工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家","联邦制国家","君主立宪制国家","资本主义共和国"], ans:0, diff:1, exp:"《宪法》第1条规定，中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家。社会主义制度是根本制度。", chapter:"第四章 国家性质和国家形式"},
  {q:"我国的政权组织形式（政体）是什么？", opts:["人民代表大会制度","总统制","议会制","委员会制"], ans:0, diff:1, exp:"《宪法》第2条规定，人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。人民代表大会制度是我国的根本政治制度。", chapter:"第四章 国家性质和国家形式"},
  {q:"我国的国家结构形式是什么？", opts:["单一制","联邦制","邦联制","复合制"], ans:0, diff:2, exp:"我国是统一的多民族国家，实行单一制国家结构形式。在中央统一领导下，充分发挥地方的主动性和积极性。民族区域自治地方和特别行政区均为国家不可分离的部分。", chapter:"第四章 国家性质和国家形式"},
  {q:"2018年宪法修正案对爱国统一战线范围作出的调整是？", opts:["在拥护祖国统一的爱国者基础上，增加了致力于中华民族伟大复兴的爱国者","删除了社会主义事业的建设者","将民主党派成员排除出统一战线","将统一战线限定为工农联盟"], ans:0, diff:3, exp:"2018年宪法修正案将爱国统一战线扩大为包括全体社会主义劳动者、社会主义事业的建设者、拥护社会主义的爱国者、拥护祖国统一和致力于中华民族伟大复兴的爱国者的广泛爱国统一战线，其中致力于中华民族伟大复兴的爱国者为新增内容。", chapter:"第四章 国家性质和国家形式"},
  {q:"下列关于我国单一制国家结构形式的表述，哪一选项正确？", opts:["全国只有一个宪法和一个中央政权机关，地方行政区域均受中央统一领导","各省级行政区享有独立立法权，可以制定宪法","民族自治地方是独立的政治实体","特别行政区与中央没有隶属关系"], ans:0, diff:2, exp:"我国是单一制国家，全国只有一个宪法、一个中央政权机关，地方各级行政区域均受中央统一领导。民族区域自治地方和特别行政区都是中华人民共和国不可分离的部分。", chapter:"第四章 国家性质和国家形式"},
  {q:"居民委员会和村民委员会的性质是什么？", opts:["基层群众性自治组织","基层政权组织","行政机关","事业单位"], ans:0, diff:1, exp:"《宪法》第111条规定，居民委员会和村民委员会是基层群众性自治组织。它们不是一级国家政权机关，而是居民和村民自我管理、自我教育、自我服务的组织。", chapter:"第五章 国家基本制度"},
  {q:"我国宪法规定，国家在社会主义初级阶段坚持的基本经济制度是？", opts:["公有制为主体、多种所有制经济共同发展","单一公有制","完全的市场经济","计划经济"], ans:0, diff:2, exp:"《宪法》第6条（2018年修正）规定，国家在社会主义初级阶段坚持公有制为主体、多种所有制经济共同发展的基本经济制度。", chapter:"第五章 国家基本制度"},
  {q:"我国宪法规定的分配制度是？", opts:["按劳分配为主体、多种分配方式并存","平均分配","按需分配","按资分配"], ans:0, diff:1, exp:"《宪法》第6条规定，坚持按劳分配为主体、多种分配方式并存的分配制度。这与社会主义初级阶段的基本经济制度相适应。", chapter:"第五章 国家基本制度"},
  {q:"关于民族区域自治制度，以下哪项正确？", opts:["民族自治地方的自治机关是自治区、自治州、自治县的人大和政府","所有少数民族聚居区都设立自治机关","民族自治地方可以制定独立的宪法","民族自治地方享有外交自主权"], ans:0, diff:2, exp:"《宪法》第112条规定，民族自治地方的自治机关是自治区、自治州、自治县的人民代表大会和人民政府。自治地方可制定自治条例和单行条例，但须报全国人大常委会批准（自治区）或省级人大常委会批准（自治州/县）。", chapter:"第五章 国家基本制度"},
  {q:"民族自治地方的自制条例和单行条例需要报请哪里批准？", opts:["自治区制定的报全国人大常委会批准；自治州/县制定的报省级人大常委会批准","国务院批准","全国人大批准","最高人民法院批准"], ans:0, diff:2, exp:"《宪法》第116条规定，自治区制定的自治条例和单行条例报全国人大常委会批准后生效；自治州、自治县的报省或自治区的人大常委会批准后生效，并报全国人大常委会备案。", chapter:"第五章 国家基本制度"},
  {q:"我国宪法规定的社会主义经济制度的基础是什么？", opts:["生产资料的社会主义公有制","私有制","混合所有制","合作社所有制"], ans:0, diff:2, exp:"《宪法》第6条规定，中华人民共和国的社会主义经济制度的基础是生产资料的社会主义公有制，即全民所有制和劳动群众集体所有制。", chapter:"第五章 国家基本制度"},
  {q:"根据宪法，国家发展社会主义的教育事业，提高全国人民的什么水平？", opts:["科学文化水平","经济收入水平","政治觉悟水平","技术水平"], ans:0, diff:1, exp:"《宪法》第19条规定，国家发展社会主义的教育事业，提高全国人民的科学文化水平。国家举办各种学校，普及初等义务教育，发展中等教育、职业教育和高等教育，并发展学前教育。", chapter:"第五章 国家基本制度"},
  {q:"我国宪法规定，国民经济的主导力量是什么？", opts:["国有经济","集体经济","私营经济","外资经济"], ans:0, diff:2, exp:"《宪法》第7条规定，国有经济即社会主义全民所有制经济，是国民经济中的主导力量。国家保障国有经济的巩固和发展。", chapter:"第五章 国家基本制度"},
  {q:"根据宪法规定，哪些土地属于国家所有？", opts:["城市的土地属于国家所有","所有土地都属于国家所有","农村的土地都属于国家所有","宅基地属于国家所有"], ans:0, diff:3, exp:"《宪法》第10条规定，城市的土地属于国家所有。农村和城市郊区的土地除由法律规定属于国家所有的以外，属于集体所有；宅基地和自留地、自留山也属于集体所有。", chapter:"第五章 国家基本制度"},
  {q:"我国宪法规定的政党制度是？", opts:["中国共产党领导的多党合作和政治协商制度","多党轮流执政制度","一党单独执政、无协商机制","多党联盟制"], ans:0, diff:2, exp:"宪法序言规定，中国共产党领导的多党合作和政治协商制度将长期存在和发展。它同人民代表大会制度、民族区域自治制度、基层群众自治制度一样，是我国的一项基本政治制度。", chapter:"第五章 国家基本制度"},
  {q:"以下哪项不是我国公民的基本权利？", opts:["罢工自由","言论自由","人身自由","宗教信仰自由"], ans:0, diff:2, exp:"我国宪法规定的公民基本权利包括：平等权、政治权利和自由、宗教信仰自由、人身自由、社会经济权利、文化教育权利、监督权等。1975年宪法和1978年宪法曾规定罢工自由，但1982年宪法取消了这一规定。", chapter:"第六章 公民的基本权利和义务"},
  {q:"关于公民的选举权和被选举权，以下哪项正确？", opts:["年满18周岁的中国公民，未被剥夺政治权利的，享有选举权和被选举权","所有中国公民都享有","只有城市居民享有","必须年满20周岁"], ans:0, diff:1, exp:"《宪法》第34条规定，年满18周岁的中国公民，不分民族、种族、性别、职业等，都有选举权和被选举权，但依法被剥夺政治权利的人除外。", chapter:"第六章 公民的基本权利和义务"},
  {q:"公民的人身自由不受侵犯。任何公民非经什么程序，不受逮捕？", opts:["经人民检察院批准或决定或人民法院决定，并由公安机关执行","任何行政机关均可决定","公安机关可自行决定","任何人可以自行逮捕"], ans:0, diff:2, exp:"《宪法》第37条规定，任何公民非经人民检察院批准或决定或者人民法院决定，并由公安机关执行，不受逮捕。禁止非法拘禁和以其他方法非法剥夺或限制公民人身自由。", chapter:"第六章 公民的基本权利和义务"},
  {q:"中华人民共和国公民的通信自由和通信秘密受法律保护。因什么需要，公安机关或检察机关可依法检查通信？", opts:["因国家安全或追查刑事犯罪的需要","因行政管理需要","因民事纠纷","任何情况均可"], ans:0, diff:2, exp:"《宪法》第40条规定，除因国家安全或追查刑事犯罪的需要，由公安机关或检察机关依法对通信进行检查外，任何组织或个人不得以任何理由侵犯公民的通信自由和通信秘密。", chapter:"第六章 公民的基本权利和义务"},
  {q:"我国宪法规定，既是公民权利又是公民义务的是什么？", opts:["劳动和受教育","纳税","服兵役","遵守法律"], ans:0, diff:1, exp:"《宪法》第42条规定劳动是公民的权利和义务；第46条规定受教育是公民的权利和义务。这两种行为同时具有权利和义务的双重属性。", chapter:"第六章 公民的基本权利和义务"},
  {q:"我国宪法对私有财产的保护，以下哪项正确？", opts:["公民合法的私有财产不受侵犯，国家依法保护私有财产权和继承权","私有财产不受任何限制","国家可以任意征收私有财产","私有财产权不受法律保护"], ans:0, diff:2, exp:"《宪法》第13条规定，公民合法的私有财产不受侵犯。国家依法保护公民的私有财产权和继承权。国家为了公共利益的需要，可以依法对私有财产实行征收或征用并给予补偿。", chapter:"第六章 公民的基本权利和义务"},
  {q:"我国宪法规定，哪些人享有选举权和被选举权？", opts:["年满18周岁的中国公民，未被剥夺政治权利者","所有居住在中国境内的人","年满16周岁的中国公民","年满20周岁的中国公民"], ans:0, diff:1, exp:"《宪法》第34条规定，中华人民共和国年满十八周岁的公民，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况、居住期限，都有选举权和被选举权；但是依照法律被剥夺政治权利的人除外。", chapter:"第六章 公民的基本权利和义务"},
  {q:"我国宪法规定公民有依法纳税的义务，同时也有依法享有何种与税收相关的权利？", opts:["没有专门规定与税收相关的权利","退税权","免税权","任意纳税权"], ans:0, diff:1, exp:"《宪法》第56条规定公民有依照法律纳税的义务。这是公民的一项基本义务。权利主要通过税收法律法规体现，如依法享受税收优惠、申请退税等。宪法中纳税仅规定为义务。", chapter:"第六章 公民的基本权利和义务"},
  {q:"根据宪法，以下哪项属于公民的文化权利？", opts:["从事科学研究、文学艺术创作和其他文化活动的自由","经商的自由","拥有武器的自由","罢工的自由"], ans:0, diff:1, exp:"《宪法》第47条规定，公民有进行科学研究、文学艺术创作和其他文化活动的自由。国家对于从事教育、科学、技术、文学、艺术和其他文化事业的公民有益于人民的创造性工作给予鼓励和帮助。", chapter:"第六章 公民的基本权利和义务"},
  {q:"我国公民有维护什么的义务？", opts:["国家统一和全国各民族团结","个人利益","部门利益","地区利益"], ans:0, diff:1, exp:"《宪法》第52条规定，中华人民共和国公民有维护国家统一和全国各民族团结的义务。这是公民首要的宪法义务之一。", chapter:"第六章 公民的基本权利和义务"},
  {q:"全国人民代表大会每届任期几年？", opts:["5年","4年","3年","6年"], ans:0, diff:1, exp:"《宪法》第60条规定，全国人民代表大会每届任期5年。每年举行一次会议，由全国人大常委会召集。", chapter:"第七章 国家机构"},
  {q:"全国人民代表大会常务委员会的职权不包括？", opts:["决定战争和和平的问题","解释宪法和法律","监督国务院工作","决定特赦"], ans:0, diff:3, exp:"决定战争和和平的问题是全国人民代表大会的职权（《宪法》第62条），全国人大常委会在全国人大闭会期间如遇国家遭受武装侵犯时可决定战争状态的宣布。", chapter:"第七章 国家机构"},
  {q:"我国宪法规定，全国人大会议每年举行一次。如果全国人大常委会认为必要，或有多少以上的全国人大代表提议，可以临时召集？", opts:["五分之一以上","三分之一以上","二分之一以上","三分之二以上"], ans:0, diff:2, exp:"《宪法》第61条规定，如果全国人大常委会认为必要，或有五分之一以上的全国人大代表提议，可以临时召集全国人大会议。", chapter:"第七章 国家机构"},
  {q:"我国宪法规定的国务院的性质是？", opts:["最高国家权力机关的执行机关，最高国家行政机关","最高国家权力机关","最高国家审判机关","最高国家法律监督机关"], ans:0, diff:1, exp:"《宪法》第85条规定，国务院是最高国家权力机关的执行机关，是最高国家行政机关。国务院对全国人大及其常委会负责并报告工作。", chapter:"第七章 国家机构"},
  {q:"关于人民法院独立行使审判权，以下哪项正确？", opts:["人民法院依法独立行使审判权，不受行政机关、社会团体和个人的干涉","法院独立于人大","法官个人独立审判","法院完全不受任何监督"], ans:0, diff:3, exp:"《宪法》第131条规定，人民法院依法独立行使审判权，不受行政机关、社会团体和个人的干涉。但法院应对人大及其常委会负责并接受其监督，并非独立于人大。", chapter:"第七章 国家机构"},
  {q:"我国的国家元首是？", opts:["国家主席","全国人大常委会委员长","国务院总理","中共中央总书记"], ans:0, diff:2, exp:"《宪法》第81条规定，国家主席代表中华人民共和国进行国事活动。国家主席是国家元首。国家主席由全国人大选举产生，与全国人大常委会结合行使国家元首职权。", chapter:"第七章 国家机构"},
  {q:"我国国家监察委员会的性质和地位是？", opts:["最高监察机关，由全国人大产生，对全国人大及其常委会负责","行政机关","司法机关","检察机关"], ans:0, diff:3, exp:"《宪法》第123-127条规定（2018年修正新增），国家监察委员会是最高监察机关，由全国人大产生，对全国人大及其常委会负责，并领导地方各级监察委员会的工作。各级监察委员会是行使国家监察职能的专责机关。", chapter:"第七章 国家机构"},
  {q:"全国人大代表在会议期间，非经什么程序不受逮捕或刑事审判？", opts:["全国人大会议主席团许可（闭会期间经全国人大常委会许可）","任何机关都可决定","经公安机关批准","经最高人民法院批准"], ans:0, diff:2, exp:"《宪法》第74条规定，全国人大代表非经全国人大会议主席团许可（闭会期间非经全国人大常委会许可），不受逮捕或刑事审判。这是人大代表的人身特别保护权。", chapter:"第七章 国家机构"},
  {q:"特别行政区的高度自治权不包括？", opts:["外交权和国防权","行政管理权","立法权","独立的司法权和终审权"], ans:0, diff:2, exp:"特别行政区享有行政管理权、立法权、独立的司法权和终审权，但外交和国防事务由中央人民政府负责管理。特别行政区的高度自治以国家统一为前提。", chapter:"第八章 \"一国两制\"与特别行政区制度"},
  {q:"我国宪法规定，国家在必要时得设立特别行政区。在特别行政区内实行的制度按照具体情况由？", opts:["全国人民代表大会以法律规定","国务院以行政法规规定","全国人大常委会以决定规定","中央军委以命令规定"], ans:0, diff:1, exp:"《宪法》第31条规定，国家在必要时得设立特别行政区。在特别行政区内实行的制度按照具体情况由全国人民代表大会以法律规定。", chapter:"第八章 \"一国两制\"与特别行政区制度"},
  {q:"根据香港基本法，香港特别行政区不实行的制度是？", opts:["社会主义制度和政策","资本主义制度","原有的法律体系","独立的司法制度"], ans:0, diff:1, exp:"香港基本法规定，香港特别行政区不实行社会主义制度和政策，保持原有的资本主义制度和生活方式50年不变。这是\"一国两制\"方针的核心内容。", chapter:"第八章 \"一国两制\"与特别行政区制度"},
  {q:"关于特别行政区的司法制度，下列哪一选项正确？", opts:["特别行政区享有独立的司法权和终审权","特别行政区的终审权属于最高人民法院","特别行政区的审判须报最高人民法院核准","特别行政区不设立法院"], ans:0, diff:2, exp:"香港、澳门基本法均规定，特别行政区享有独立的司法权和终审权，终审权属于特别行政区设立的终审法院，中央司法机关不干预其审判，这体现了高度自治。", chapter:"第八章 \"一国两制\"与特别行政区制度"},
  {q:"根据香港基本法，香港特别行政区立法机关制定的法律须报全国人大常委会备案。下列关于备案的表述，哪一选项正确？", opts:["备案不影响该法律的生效，但全国人大常委会可将不符合基本法关于中央管理事务规定的法律发回，发回即失效","备案须经全国人大常委会批准后方能生效","备案的法律由全国人大常委会直接修改","备案不影响生效，全国人大常委会也无权作任何处理"], ans:0, diff:3, exp:"香港基本法第17条规定，特区立法机关制定的法律须报全国人大常委会备案，备案不影响该法律的生效；全国人大常委会征询基本法委员会意见后，如认为有关法律不符合基本法关于中央管理的事务及中央与特区关系的条款，可将该法律发回，发回即失效（无溯及力）。", chapter:"第八章 \"一国两制\"与特别行政区制度"},
  {q:"宪法的修改需要多少代表通过？", opts:["全国人大代表的三分之二以上多数","全国人大代表的过半数","全国人大代表的四分之三","全国人大代表的三分之一"], ans:0, diff:2, exp:"《宪法》第64条规定，宪法的修改由全国人大常委会或五分之一以上的全国人大代表提议，并由全国人大以全体代表的三分之二以上的多数通过。法律和其他议案由过半数通过。", chapter:"第九章 宪法实施和监督"},
  {q:"我国宪法修正案由谁公布？", opts:["全国人民代表大会","国家主席","全国人大常委会","国务院"], ans:0, diff:3, exp:"宪法修正案由全国人大通过后即生效，由全国人大以公告形式公布。法律由国家主席签署主席令公布，但宪法修正案不同。", chapter:"第九章 宪法实施和监督"},
  {q:"根据我国宪法，有权解释宪法、监督宪法实施的国家机关是？", opts:["全国人大及其常委会","最高人民法院","国务院","国家监察委员会"], ans:0, diff:2, exp:"《宪法》第67条规定，全国人大常委会有权解释宪法、监督宪法的实施；第62条规定全国人大监督宪法的实施。宪法解释权和监督宪法实施权属于全国人大及其常委会。", chapter:"第九章 宪法实施和监督"},
  {q:"国务院制定的行政法规如果同宪法、法律相抵触，依照宪法规定有权撤销的是？", opts:["全国人大常委会","最高人民法院","全国人民代表大会代表","国务院各部委"], ans:0, diff:3, exp:"《宪法》第67条规定，全国人大常委会有权撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令。这体现了全国人大常委会对国务院的监督和宪法监督职能。", chapter:"第九章 宪法实施和监督"},
  {q:"依照宪法规定，宪法的修改由谁提议？", opts:["全国人大常委会或者五分之一以上的全国人大代表","国家主席","国务院","中共中央委员会"], ans:0, diff:1, exp:"《宪法》第64条规定，宪法的修改由全国人大常委会或者五分之一以上的全国人大代表提议，并由全国人大以全体代表的三分之二以上的多数通过。", chapter:"第九章 宪法实施和监督"}
],

  "国际公法": [
{chapter:"第一章 国际法导论",q:"国际法最主要的渊源是？",opts:["国际习惯","国际条约","一般法律原则","司法判例"],ans:1,exp:"马工程教材明确指出，《国际法院规约》第38条列举的渊源中，国际条约是现代国际法最主要、最直接的渊源。"},
    {chapter:"第一章 国际法导论",q:"下列哪项不是国际法的基本原则？",opts:["国家主权平等原则","不干涉内政原则","国际法优先于国内法原则","和平解决国际争端原则"],ans:2,exp:"国际法与国内法的关系在理论上虽有争论，但”国际法优先于国内法”不是公认的国际法基本原则。国际法基本原则包括主权平等、不干涉内政、和平解决争端、禁止使用武力、民族自决、善意履行国际义务等。"},
    {chapter:"第一章 国际法导论",q:"国际法的主体主要是？",opts:["国家","国际组织","个人","跨国公司"],ans:0,exp:"国家是国际法的基本主体、主要主体。国际组织是派生主体，个人在特定领域（如人权、国际刑法）具有有限主体资格，但不是主要主体。"},
    {chapter:"第一章 国际法导论",q:"“强行法”（Jus Cogens）是指？",opts:["国际法院的判决","联合国安理会的决议","国际社会全体接受并公认为不许损抑的规范","各国国内宪法的规定"],ans:2,exp:"根据《维也纳条约法公约》第53条，强行法是指国家之国际社会全体接受并公认为不许损抑且仅有以后具有同等性质之一般国际法规律始得更改之规律。"},
    {chapter:"第一章 国际法导论",q:"国际法与国内法关系的”一元论”主张？",opts:["国际法与国内法是两个完全独立的法律体系","国际法从属于国内法","国内法从属于国际法","国际法与国内法属于同一个法律体系"],ans:3,exp:"一元论认为国际法和国内法同属一个法律体系，区别仅在于效力范围。二元论（平行说）才主张两者是独立体系。"},
    {chapter:"第一章 国际法导论",q:"下列哪项属于国际法的间接渊源？",opts:["国际条约","国际习惯","权威公法学家学说","一般法律原则"],ans:2,exp:"司法判例和权威公法学家的学说是确定法律原则的辅助资料（间接渊源），本身不是直接渊源。"},
    {chapter:"第一章 国际法导论",q:"国际法效力的根据是？",opts:["强权政治","国家之间的协议（共同意志）","自然法","联合国宪章"],ans:1,exp:"马工程教材强调，国际法是国家之间的法律，其效力根据在于国家之间的协议或共同意志，而非超国家的立法机关。"},
    {chapter:"第一章 国际法导论",q:"关于国际法在国内的适用，中国采取的方式是？",opts:["一律直接适用","一律转化适用","混合方式（直接适用与转化适用并存）","国际法不能在国内适用"],ans:2,exp:"中国宪法未作统一规定，实践中采取混合方式：如《民事诉讼法》规定条约优先（直接适用），但WTO规则等通常需要国内立法转化。"},
    {chapter:"第一章 国际法导论",q:"“软法”（Soft Law）通常指？",opts:["没有法律约束力的国际文件","效力低于条约的国际法","习惯国际法","一般法律原则"],ans:0,exp:"软法指原则上没有法律约束力但有实际效果的国际文件，如联合国大会决议、宣言等。"},
    {chapter:"第一章 国际法导论",q:"下列哪项不属于国际法基本原则的特征？",opts:["各国公认","具有普遍约束力","构成国际法体系的基础","仅适用于发达国家"],ans:3,exp:"国际法基本原则具有普遍适用性，对所有国家（无论大小、强弱、发达与否）均有约束力。"},
    {chapter:"第二章 国际法主体",q:"国家构成的四要素不包括？",opts:["定居的居民","确定的领土","强大的军队","政府"],ans:2,exp:"根据1933年《蒙得维的亚公约》，国家要素为：定居的居民、确定的领土、政府、与他国交往的能力。军队不是必要条件。"},
    {chapter:"第二章 国际法主体",q:"国家主权豁免的”限制豁免主义”主张？",opts:["国家的一切行为都享有豁免","国家的主权行为享有豁免，商业行为不享有豁免","国家在任何情况下都不享有豁免","只有联合国会员国享有豁免"],ans:1,exp:"限制豁免论将国家行为分为主权行为（统治权行为）和商业行为（管理权行为），仅前者享有豁免。这是当前国际趋势，中国《外国国家豁免法》也已采纳。"},
    {chapter:"第二章 国际法主体",q:"国际组织作为国际法主体，其权利能力来源于？",opts:["国家主权","成员国的授权（章程）","国际习惯","联合国大会决议"],ans:1,exp:"国际组织是派生主体，其权利能力和行为能力由成员国通过章程（组织约章）授予，具有职能性限制。"},
    {chapter:"第二章 国际法主体",q:"下列哪项不是国家继承的对象？",opts:["领土","档案","人身性条约（如军事同盟）","国家债务"],ans:2,exp:"国家继承主要涉及财产、档案、债务及与领土相关的条约。人身性条约（政治性条约）一般不予继承。"},
    {chapter:"第二章 国际法主体",q:"关于承认，下列哪项正确？",opts:["承认是构成国家存在的要件","承认是宣告性的，不是构成性的","承认必须经联合国批准","承认一旦作出不可撤销"],ans:1,exp:"现代国际法主流观点为宣告说：承认只是对既存事实的确认，不创造国家。但承认在法律上产生一定后果，通常不可随意撤销。"},
    {chapter:"第二章 国际法主体",q:"政府继承通常发生在？",opts:["国家合并时","国家分裂时","社会革命导致政权更迭时","领土割让时"],ans:2,exp:"政府继承是指因革命或政变导致政权非宪法程序更迭时，新政府继承旧政府的国际权利义务。宪法程序内的政府换届不属于国际法上的政府继承。"},
    {chapter:"第二章 国际法主体",q:"民族解放运动作为国际法主体，其地位是？",opts:["与国家完全等同","过渡性的、有限的主体","仅享有外交豁免","不是国际法主体"],ans:1,exp:"正在争取独立的民族解放运动，在民族自决原则下，具有过渡性的国际法主体资格，可缔结条约、参加国际会议。"},
    {chapter:"第二章 国际法主体",q:"下列哪项属于国家的主权行为（享有豁免）？",opts:["国有公司购买办公用品","国家发行主权债券","军队采购武器","国家旅游局在国外开设酒店"],ans:2,exp:"军队采购武器属于典型的主权行为（统治权行为）。购买办公用品、开设酒店、甚至部分商业债券发行，通常被视为商业行为（限制豁免下不享有豁免）。"},
    {chapter:"第二章 国际法主体",q:"关于国籍，下列哪项错误？",opts:["国籍是国家行使外交保护的依据","国籍的取得和丧失主要由国内法规定","双重国籍在国际法上被普遍禁止","国家有权决定是否给予外国人国籍"],ans:2,exp:"国际法不禁止双重国籍，但各国可通过国内法或双边条约加以限制或解决冲突。国籍原则属于国内管辖，但受国际法限制（如不得任意剥夺）。"},
    {chapter:"第二章 国际法主体",q:"国家责任的前提是？",opts:["造成实际损害","存在国际不法行为","经国际法院判决","受害人提出索赔"],ans:1,exp:"国家责任的构成要件是：行为可归因于国家 + 违背国际义务（即国际不法行为）。损害不是必要要件（如侵犯外交馆舍未造成物质损害也需负责）。"},
    {chapter:"第三章 国际法上的领土",q:"领海的外部界限是？",opts:["低潮线","领海基线向外12海里","大陆架边缘","专属经济区起点"],ans:1,exp:"根据《联合国海洋法公约》，领海宽度从基线量起不超过12海里。"},
    {chapter:"第三章 国际法上的领土",q:"下列哪项不属于内水？",opts:["港口","河流","领海","海湾（封口线内）"],ans:2,exp:"内水包括港口、河流、湖泊、内海湾、内海峡等。领海是内水以外的海域，两者法律地位不同（内水无无害通过权，领海有）。"},
    {chapter:"第三章 国际法上的领土",q:"关于领土取得方式，“先占”的对象必须是？",opts:["无主地","他国领土","公海","南极"],ans:0,exp:"先占（Occupation）的对象必须是无主地（Terra Nullius），即不属于任何国家或已被原主放弃的土地。"},
    {chapter:"第三章 国际法上的领土",q:"专属经济区（EEZ）的法律地位是？",opts:["公海","领海","自成一类的特定法律区域","沿海国领土"],ans:2,exp:"EEZ既不是领海也不是公海，是自成一类（Sui Generis）的区域。沿海国享有资源主权权利，他国享有航行飞越自由。"},
    {chapter:"第三章 国际法上的领土",q:"下列哪项不是无害通过的”无害”标准？",opts:["不损害沿海国和平、良好秩序或安全","进行捕鱼活动","进行研究测量活动","仅通过而不进入内水"],ans:3,exp:"D是”通过”的定义，不是”无害”的标准。A、B、C均为《公约》第19条列举的非无害行为。"},
    {chapter:"第三章 国际法上的领土",q:"关于大陆架，下列说法正确的是？",opts:["沿海国必须宣告才享有权利","沿海国对大陆架的权利是固有的、专属的","大陆架包括上覆水域","其他国家可在大陆架自由铺设管道无需同意"],ans:1,exp:"大陆架权利是固有的，无需宣告或占领。权利及于海床和底土，不及于上覆水域。铺设管道路线需沿海国同意。"},
    {chapter:"第三章 国际法上的领土",q:"国际海底区域（“区域”）的资源属于？",opts:["先占国","沿海国","人类共同继承财产","联合国所有"],ans:2,exp:"《联合国海洋法公约》规定，“区域”及其资源是人类共同继承财产，由国际海底管理局代表全人类管理。"},
    {chapter:"第三章 国际法上的领土",q:"领土主权的限制不包括？",opts:["共管","租借","无害通过","国内行政区划"],ans:3,exp:"国内行政区划是国家行使主权的表现，不是对主权的国际法限制。共管、租借、国际地役、无害通过等才是限制。"},
    {chapter:"第三章 国际法上的领土",q:"关于边界，下列哪项正确？",opts:["边界条约因政权更迭而失效","边界条约属于”处分性条约”，必须继承","边界可以由单方面划定","界标移动不影响边界线位置"],ans:1,exp:"边界条约具有稳定性，不因国家继承或政权更迭而失效。界标移动需通过协议恢复或重新划定，不能单方面改变边界线。"},
    {chapter:"第三章 国际法上的领土",q:"南极的法律地位是？",opts:["各国可主张主权","仅用于和平目的，冻结主权要求","属于联合国托管","属于公海"],ans:1,exp:"《南极条约》规定南极仅用于和平目的，冻结各国对南极的领土主权要求，既不承认也不否认现有主张。"},
    {chapter:"第四章 海洋法",q:"毗连区的宽度从基线量起不超过？",opts:["12海里","24海里","200海里","350海里"],ans:1,exp:"毗连区从基线量起不超过24海里（即领海之外再延伸12海里）。"},
    {chapter:"第四章 海洋法",q:"下列哪项不是沿海国在专属经济区的权利？",opts:["勘探开发自然资源","建造人工岛屿","禁止他国航行","海洋科学研究管辖"],ans:2,exp:"EEZ内他国享有航行和飞越自由，沿海国不得禁止。A、B、D均为沿海国的主权权利或管辖权。"},
    {chapter:"第四章 海洋法",q:"公海上的管辖权原则是？",opts:["属地管辖","船旗国专属管辖","普遍管辖","保护性管辖"],ans:1,exp:"公海实行船旗国专属管辖原则。例外情况：海盗、奴隶贩运、非法广播、无国籍船等可行使登临权或普遍管辖。"},
    {chapter:"第四章 海洋法",q:"关于群岛国，下列说法正确的是？",opts:["群岛基线内水域为领海","群岛国可划定群岛基线，基线内水域为群岛水域","群岛水域适用内水制度","外国船舶在群岛水域无无害通过权"],ans:1,exp:"群岛基线内水域为群岛水域，既非内水也非领海。外国船舶在群岛水域享有无害通过权，群岛国可指定海道通行权。"},
    {chapter:"第四章 海洋法",q:"国际海峡的通行制度是？",opts:["无害通过","过境通行","自由航行","需沿海国许可"],ans:1,exp:"用于国际航行的海峡适用过境通行制度（Transit Passage），比无害通过更宽松（允许潜艇潜航、飞机飞越）。"},
    {chapter:"第四章 海洋法",q:"下列哪项不是《联合国海洋法公约》规定的争端解决机制？",opts:["国际海洋法法庭","国际法院","仲裁庭","世界贸易组织争端解决机构"],ans:3,exp:"WTO机制解决贸易争端。《公约》第十五部分规定的机制包括：国际海洋法法庭、国际法院、仲裁庭、特别仲裁庭。"},
    {chapter:"第四章 海洋法",q:"关于海洋环境污染，下列说法正确的是？",opts:["仅沿海国有管辖权","船旗国、港口国、沿海国均有管辖权","公海污染无法管辖","仅国际海事组织有管辖权"],ans:1,exp:"海洋污染管辖是多重管辖：船旗国（主要）、沿海国（在其管辖海域）、港口国（对自愿在其港口的船舶）均有权采取措施。"},
    {chapter:"第四章 海洋法",q:"大陆架外部界限的确定标准包括？",opts:["200海里","2500米等深线外100海里","沉积岩厚度公式","以上皆是"],ans:3,exp:"大陆架外部界限可基于：200海里、2500米等深线外100海里、或沉积岩厚度公式（1%规则），取较远者，但最大不超过350海里。"},
    {chapter:"第四章 海洋法",q:"关于”区域”内活动，下列说法错误的是？",opts:["由国际海底管理局管理","实行”平行开发制”","企业部由管理局直接经营","各国可自由抢占矿区"],ans:3,exp:"“区域”资源为人类共同继承财产，禁止国家或个人据为己有。开发需经管理局批准，实行平行开发制（国家/企业部与承包者并行）。"},
    {chapter:"第四章 海洋法",q:"低潮高地（Low-tide Elevation）在领海宽度内可作为？",opts:["领海基点","专属经济区基点","大陆架基点","无任何效力"],ans:0,exp:"位于领海宽度内的低潮高地，可作为测算领海宽度的基点。若完全在领海外，则无自己的领海，也不能作为基点。"},
    {chapter:"第五章 外交与领事关系法",q:"外交代表的派遣需经接受国？",opts:["事先同意（Agrément）","事后追认","联合国批准","无需同意"],ans:0,exp:"派遣国在正式派遣使馆馆长前，必须查明接受国是否已同意（Agrément）该人选。"},
    {chapter:"第五章 外交与领事关系法",q:"使馆馆舍不可侵犯，意味着？",opts:["接受国官员非经馆长同意不得进入","使馆是派遣国领土","使馆内犯罪派遣国管辖","接受国可断水断电"],ans:0,exp:"馆舍不可侵犯的核心是非经馆长同意不得进入。使馆不是派遣国领土（B错）。馆内犯罪通常仍由接受国管辖，但执行受限。"},
    {chapter:"第五章 外交与领事关系法",q:"外交代表的刑事管辖豁免是？",opts:["有限的","绝对的","仅职务行为","需派遣国放弃"],ans:1,exp:"外交代表享有绝对的刑事管辖豁免，无论职务行为还是私人行为。民事豁免有例外（如私有不动产诉讼、继承诉讼）。"},
    {chapter:"第五章 外交与领事关系法",q:"领事官员的管辖豁免范围是？",opts:["绝对豁免","仅职务行为","无豁免","刑事绝对，民事有限"],ans:1,exp:"领事官员仅就执行职务的行为享有管辖豁免。非职务行为（如私人交通肇事）不享有豁免，但人身不可侵犯权仍有一定保护（非重罪不得逮捕）。"},
    {chapter:"第五章 外交与领事关系法",q:"“不受欢迎的人”（Persona Non Grata）适用于？",opts:["仅外交代表","仅领事官员","外交代表和领事官员","所有外国人"],ans:2,exp:"接受国可随时、无需说明理由，宣布外交代表或领事官员为”不受欢迎的人”，要求派遣国召回或终止其职务。"},
    {chapter:"第五章 外交与领事关系法",q:"外交邮袋？",opts:["可被开拆检查","不可开拆，但可X光扫描","不可开拆，不可扣留","需外交官在场方可开拆"],ans:2,exp:"外交邮袋不得开拆或扣留，应免受一切检查。这是绝对的特权。"},
    {chapter:"第五章 外交与领事关系法",q:"领馆馆舍与使馆馆舍的主要区别是？",opts:["领馆无不可侵犯权","领馆不可侵犯权有例外（火灾等紧急情况推定同意）","领馆可被随意进入","领馆不免税"],ans:1,exp:"领馆馆舍不可侵犯，但在火灾或其他灾害需迅速采取保护行动时，可推定馆长同意进入。使馆无此例外。"},
    {chapter:"第五章 外交与领事关系法",q:"外交代表的民事管辖豁免例外不包括？",opts:["私有不动产之物权诉讼","以私人身份参与的继承诉讼","职务范围内的商业活动","公务范围外的专业或商业活动"],ans:2,exp:"职务范围内的商业活动属于职务行为，享有豁免。例外是”公务范围外”的专业或商业活动。"},
    {chapter:"第五章 外交与领事关系法",q:"关于外交特权与豁免的理论依据，主流观点是？",opts:["代表性说","治外法权说","职务需要说","职务需要说与代表性说结合"],ans:3,exp:"《维也纳外交关系公约》序言确认，特权与豁免的依据是职务需要和代表性，而非治外法权。"},
    {chapter:"第五章 外交与领事关系法",q:"领事官员的人身不可侵犯权在何种情况下可受限？",opts:["任何轻微违法","犯有严重罪行，经主管司法机关裁判","接受国认为必要时","派遣国同意时"],ans:1,exp:"领事官员人身不可侵犯，但犯有严重罪行（Grave Crime）并经主管司法机关裁判，可予以逮捕或羁押。"},
    {chapter:"第六章 条约法",q:"条约对第三国创设义务，必须经第三国？",opts:["口头同意","书面明示同意","默示同意","联合国批准"],ans:1,exp:"《维也纳条约法公约》第35条：条约规定第三国义务，必须经第三国书面明示接受。"},
    {chapter:"第六章 条约法",q:"条约保留的目的是？",opts:["废除条约","排除或更改条约中某些规定对保留国的适用","推迟条约生效","增加缔约国"],ans:1,exp:"保留（Reservation）是一国在签署、批准、接受、赞同或加入条约时，旨在排除或更改条约中某些规定对该国适用时的法律效果的单方声明。"},
    {chapter:"第六章 条约法",q:"下列哪项不是条约无效的理由？",opts:["违反国内法关于缔约权限的规定","错误","欺诈","贿赂"],ans:0,exp:"《维也纳条约法公约》第46条规定，违反国内法关于缔约权限的规定仅在违反显见且涉及具有根本重要性之规则时，方可作为条约无效的理由。一般性的违反国内法规定不足以导致条约无效。"},
    {chapter:"第六章 条约法",q:"条约的”情势变迁”原则（Rebus sic stantibus）的适用条件不包括？",opts:["构成当事国同意受条约拘束的必要基础","变动是根本性的","变动是当事国所预见的","情势变动非因当事国本身违背国际义务所致"],ans:2,exp:"情势变迁原则要求变动是当事国所未预见的。如果当事国在缔约时已预见该变动，则不得援引情势变迁。此外，变动必须是根本性的、构成同意的基础，且非因援引国自身违约所致。"},
    {chapter:"第六章 条约法",q:"关于条约的缔结程序，下列哪项正确？",opts:["条约必须由元首签署才有效","全权代表签署的条约无需国家批准","条约的签署、批准、接受、加入是缔约的不同阶段","条约一经签署即对所有缔约国生效"],ans:2,exp:"条约缔结包括谈判、签署、批准、接受、加入等阶段。签署不一定导致条约生效，批准通常是条约生效的前提条件。全权代表签署的条约通常需经国家批准。"},
    {chapter:"第六章 条约法",q:"条约解释的首要规则是？",opts:["按条约目的和宗旨解释","按文字通常含义结合上下文解释","按缔约国事后实践解释","按有利于缔约国利益解释"],ans:1,exp:"《维也纳条约法公约》第31条规定，条约应依其用语按其上下文并参照条约之目的及宗旨所具有之通常含义，善意解释。文字解释是首要规则。"},
    {chapter:"第六章 条约法",q:"关于条约的终止和暂停施行，下列说法正确的是？",opts:["缔约国单方宣布退出条约即导致条约终止","重大违约是终止或暂停施行的理由之一","条约无效后不得重新缔结相同内容的条约","不可抗力可导致条约永久终止"],ans:1,exp:"《维也纳条约法公约》第60条规定，重大违约（Material Breach）是其他缔约国终止或暂停施行条约的理由。单方宣布退出仅在条约本身允许或经其他缔约国同意时才能导致终止。"},
    {chapter:"第六章 条约法",q:"关于条约的签署，下列哪项正确？",opts:["签署仅具有认证约文的作用","签署必然导致条约对签署国生效","签署国在批准前有义务不使条约目的和宗旨遭受破坏","签署国必须立即批准条约"],ans:2,exp:"《维也纳条约法公约》第18条规定，签署国在批准、接受或加入前，有义务不做任何足以妨碍条约目的和宗旨的行为。签署不一定导致条约生效，但产生善意义务。"},
    {chapter:"第六章 条约法",q:"多边条约的保留，其他缔约国可以？",opts:["必须接受保留","可以在一定期限内反对保留","不得反对保留","必须经联合国批准才能反对"],ans:1,exp:"其他缔约国可以在一定期限内对保留表示接受或反对。反对保留并不必然导致条约在反对国与保留国之间不生效，只是保留所涉及的规定在保留范围内不适用于反对国。"},
    {chapter:"第六章 条约法",q:"关于条约的生效，下列哪项正确？",opts:["条约必须经全体缔约国批准才能生效","条约的生效条件由条约本身规定","条约签署后即自动生效","条约必须经联合国秘书处登记才能生效"],ans:1,exp:"条约的生效条件由条约本身规定，可以是签署后生效、批准书交换后生效、或达到一定数量的批准后生效等。《联合国宪章》第102条规定条约应登记，但未登记不影响条约的法律效力，只是在联合国机关中不得援引。"},
    {chapter:"第七章 国家责任",q:"国家责任的构成要件不包括？",opts:["行为可归因于国家","行为违背国际义务","造成实际损害","行为具有违法性"],ans:2,exp:"根据《国家责任条款草案》，国家责任的构成要件是：行为可归因于国家 + 违背国际义务。实际损害不是必要要件，如侵犯外交馆舍未造成物质损害也需负责。"},
    {chapter:"第七章 国家责任",q:"下列哪项行为不可归因于国家？",opts:["国家机关的行为","经授权行使政府权力要素的个人或实体的行为","私人团体的自发行为","受国家指挥或指挥下的武装团体所为的行为"],ans:2,exp:"私人团体的自发行为一般不可归因于国家，除非该行为实际上受国家指挥或控制。国家机关的行为、经授权行使政府权力者的行为、以及受国家指挥的武装团体行为均可归因于国家。"},
    {chapter:"第七章 国家责任",q:"下列哪项可作为免除国家行为违法性的理由？",opts:["同意","自卫","不可抗力","以上皆是"],ans:3,exp:"《国家责任条款草案》规定了六种免除行为违法性的情形：同意、自卫、反措施、不可抗力、危难、危急情况。"},
    {chapter:"第七章 国家责任",q:"关于”反措施”（Countermeasures），下列说法正确的是？",opts:["反措施可以是武力行动","反措施必须由受害国采取","反措施可以是违反国际义务的行为，但须符合比例原则","反措施可以针对第三国"],ans:2,exp:"反措施是受害国为促使责任国履行国际义务而采取的原本违反国际义务的行为，但须符合比例原则，且不得使用武力或违反基本人权。反措施只能针对责任国，不能针对第三国。"},
    {chapter:"第七章 国家责任",q:"国际罪行与”严重违背对国际社会整体的义务”的区别在于？",opts:["前者要求故意或重大过失","前者仅涉及双边关系","前者不需要实际损害","两者没有区别"],ans:0,exp:"严重违背对国际社会整体承担的义务（原称”国际罪行”）要求故意或重大过失，且涉及保护国际社会基本价值，如禁止侵略、灭绝种族、奴隶制、种族隔离等。"},
    {chapter:"第七章 国家责任",q:"关于国家赔偿，下列说法正确的是？",opts:["赔偿仅包括物质损失","赔偿形式仅有一次性金钱赔偿","赔偿应包括物质损失和精神损失","国家责任不需要赔偿"],ans:2,exp:"国家赔偿应包括物质损失和精神损失。赔偿形式可以是 restitution（恢复原状）、compensation（赔偿损失）、satisfaction（抵偿）等，不限于一次性金钱赔偿。"},
    {chapter:"第七章 国家责任",q:"下列哪项属于”恢复原状”（Restitution）？",opts:["支付赔偿金","归还非法占领的领土","公开道歉","保证不再重犯"],ans:1,exp:"恢复原状是国家责任的首要赔偿形式，指恢复到不法行为发生前的状态。归还非法占领的领土、返还非法征收的财产等属于恢复原状。支付赔偿金属于补偿，公开道歉属于抵偿。"},
    {chapter:"第七章 国家责任",q:"关于”危急情况”（Necessity），下列说法正确的是？",opts:["任何国家都可以援引危急情况","危急情况要求保护的基本利益面临严重迫切的危险","危急情况可以违背任何国际义务","危急情况不适用于经济困难"],ans:1,exp:"危急情况要求保护的基本利益面临严重而迫切的危险，且该行为是保护该利益唯一的方法。危急情况不能违背对国际社会整体的基本义务，也不能由该国的行为促成危急情况。"},
    {chapter:"第七章 国家责任",q:"国家责任是否因时间经过而消灭？",opts:["是，超过10年即消灭","是，超过20年即消灭","《国家责任条款草案》未规定时效","由国际法院统一规定时效"],ans:2,exp:"《国家责任条款草案》未规定国家责任的时效问题。时效问题通常由相关条约或国内法处理，国际法层面尚无统一的时效规则。"},
    {chapter:"第七章 国家责任",q:"下列哪项行为可构成”灭绝种族”？",opts:["战争中的平民伤亡","意图全部或部分消灭某一民族、族裔、种族或宗教团体的行为","政治迫害","经济制裁导致的平民困难"],ans:1,exp:"根据《防止及惩治灭绝种族罪公约》，灭绝种族是指意图全部或部分消灭某一民族、族裔、种族或宗教团体的行为，包括杀害该团体成员、致使该团体成员在身体上或精神上遭受严重伤害等。关键在于”特定意图”（dolus specialis）。"},
    {chapter:"第八章 国际争端的和平解决",q:"下列哪项不是《联合国宪章》第33条列举的和平解决国际争端的方式？",opts:["谈判","调停","制裁","国际法院诉讼"],ans:2,exp:"《联合国宪章》第33条列举了谈判、调查、调停、和解、仲裁、司法解决、利用区域机关或安排等和平解决方式。制裁属于第七章的集体安全行动，不是和平解决争端的方式。"},
    {chapter:"第八章 国际争端的和平解决",q:"关于国际法院的管辖权，下列说法正确的是？",opts:["国际法院对所有国际争端具有强制管辖权","国际法院的管辖权以当事国同意为基础","个人可以向国际法院提起诉讼","国际法院可以审理国家与跨国公司之间的争端"],ans:1,exp:"国际法院的管辖权以当事国同意为基础，包括自愿管辖、协定管辖和任择强制管辖。国际法院仅审理国家之间的争端，个人和跨国公司不能成为国际法院的诉讼当事人。"},
    {chapter:"第八章 国际争端的和平解决",q:"关于国际仲裁，下列说法正确的是？",opts:["仲裁裁决可以上诉","仲裁庭由当事国单方面指定仲裁员","仲裁裁决是终局的，对当事国有拘束力","仲裁不适用国际法"],ans:2,exp:"国际仲裁实行一裁终局原则。仲裁裁决是终局的，对当事国有拘束力，不得上诉。仲裁庭的组成通常由双方协商指定仲裁员。仲裁应适用国际法。"},
    {chapter:"第八章 国际争端的和平解决",q:"关于”调停”（Good Offices/Mediation），下列哪项正确？",opts:["调停国提出的方案具有法律拘束力","调停国直接参与争端当事国的谈判","调停是一种自愿性争端解决方式","调停失败后当事国不得再寻求其他解决方式"],ans:2,exp:"调停是一种自愿性的政治解决方式，调停国可以提出方案供当事国参考，但方案不具有法律拘束力。调停失败后当事国仍可寻求其他解决方式。"},
    {chapter:"第八章 国际争端的和平解决",q:"关于和解（Conciliation），下列说法正确的是？",opts:["和解委员会的调查和调解结果具有法律拘束力","和解是司法解决的一种形式","和解委员会提出报告和建议，但不具有法律拘束力","和解仅适用于法律争端"],ans:2,exp:"和解委员会负责调查争端事实并提出解决建议，但其报告和建議不具有法律拘束力。和解适用于各类争端，不限于法律争端。"},
    {chapter:"第八章 国际争端的和平解决",q:"国际法院的”任择强制管辖权”（Optional Clause）是指？",opts:["所有联合国会员国自动接受国际法院强制管辖","国家可以声明接受国际法院对特定争端的强制管辖","国际法院可以强制任何国家接受管辖","安理会可以强制国家接受国际法院管辖"],ans:1,exp:"《国际法院规约》第36条第2款规定，国家可以声明接受国际法院的强制管辖权。这是一种任择性的声明，不是所有会员国都接受。"},
    {chapter:"第八章 国际争端的和平解决",q:"关于”临时措施”（Provisional Measures），下列说法正确的是？",opts:["国际法院的临时措施建议不具有法律拘束力","国际法院可以指示临时措施以保全当事国的权利","临时措施仅适用于领土争端","临时措施需要当事国同意才能发布"],ans:1,exp:"国际法院可以根据《国际法院规约》第41条指示临时措施，以保全当事国在诉讼期间的权利。国际法院的临时措施具有法律拘束力（国际法院在LaGrand案和Avena案中确认了这一点）。"},
    {chapter:"第八章 国际争端的和平解决",q:"区域机关解决国际争端的方式包括？",opts:["仅适用于区域和平与安全的维持","可以包括区域安排下的谈判、调解、仲裁等","区域机关的决议对联合国会员国具有强制拘束力","区域机关不能审理法律争端"],ans:1,exp:"《联合国宪章》第八章鼓励和平解决争端利用区域机关或区域安排。区域机关可以采用谈判、调解、仲裁等多种方式解决争端，包括法律争端和政治争端。"},
    {chapter:"第八章 国际争端的和平解决",q:"关于国际争端解决中的”法律争端”与”政治争端”，下列哪项正确？",opts:["法律争端只能通过仲裁解决","政治争端不能通过任何方式解决","法律争端适合通过司法方式解决","政治争端不适用国际法"],ans:2,exp:"法律争端（如条约解释、国际法问题）适合通过司法方式（国际法院、仲裁）解决。政治争端（如利益争端）更适合通过政治方式（谈判、调解）解决，但并非不适用国际法。"},
    {chapter:"第八章 国际争端的和平解决",q:"关于”调查”（Inquiry）在和平解决争端中的作用，下列哪项正确？",opts:["调查委员会可以作出具有拘束力的裁决","调查旨在查明争端事实，为当事国解决争端提供基础","调查仅适用于海洋争端","调查是强制性的争端解决方式"],ans:1,exp:"调查旨在查明争端事实，为当事国解决争端提供客观基础。调查委员会的报告不具有法律拘束力，但有助于当事国基于事实进行谈判或和解。"},
    {chapter:"第九章 战争与武装冲突法",q:"国际人道法（战争法）的核心原则不包括？",opts:["区分原则","比例原则","军事必要原则","绝对豁免原则"],ans:3,exp:"国际人道法的核心原则包括区分原则（区分战斗员与平民）、比例原则（禁止过度杀伤）、军事必要原则（允许必要的武力）和人道原则（禁止不必要的痛苦）。“绝对豁免”不是战争法原则。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于战斗员的定义，下列哪项正确？",opts:["仅包括正规军队成员","包括正规武装部队成员及符合一定条件的民兵和志愿部队成员","仅包括持有武器的士兵","包括所有参与战争的人"],ans:1,exp:"根据《日内瓦公约》及其附加议定书，战斗员包括正规武装部队成员，以及符合一定条件的民兵和志愿部队成员（如有组织指挥体系、公开携带武器、遵守战争法规等）。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于平民的保护，下列哪项正确？",opts:["平民在任何情况下都不应成为攻击目标","平民可以作为军事目标","平民自动失去保护如果居住在被占领土","平民可以成为报复的对象"],ans:0,exp:"国际人道法严格保护平民，禁止将平民作为攻击目标。平民只有在直接参与敌对行动期间才暂时失去保护。报复针对平民是被绝对禁止的。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于”军事必要”原则，下列说法正确的是？",opts:["军事必要可以凌驾于所有人道法之上","军事必要仅允许采取战争法所不禁止的、为实现合法军事目的所必需的措施","军事必要意味着可以不受任何限制地使用武力","军事必要仅适用于海战"],ans:1,exp:"军事必要原则允许采取为实现合法军事目的所必需且战争法不禁止的措施，但不能凌驾于人道法之上。军事必要与人道原则需要平衡。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于战俘待遇，下列哪项正确？",opts:["战俘可以被判处死刑而无需特别程序","战俘应始终受到人道待遇","战俘可以被用作人盾","战俘没有权利与外界通信"],ans:1,exp:"根据《日内瓦第三公约》，战俘应始终受到人道待遇，禁止酷刑、侮辱和公开好奇的围观。战俘有权与外界通信（受军事安全限制），不得被用作人盾。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于占领法，下列哪项正确？",opts:["占领国可以获得被占领土的主权","占领国应维持被占领土的法律和秩序","占领国可以随意改变被占领土的法律","占领状态因和平条约的签订而自动终止"],ans:1,exp:"根据《海牙章程》和《日内瓦第四公约》，占领国应维持被占领土的法律和秩序，但不得改变当地法律（除非绝对必要）。占领不转移主权，占领状态在实际控制结束或和平条约签订时终止。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于禁止使用的武器，下列哪项正确？",opts:["核武器在国际法上完全被禁止","毒器和有毒武器被绝对禁止","生物武器在特定条件下可以使用","所有大规模杀伤性武器都未被禁止"],ans:1,exp:"毒器和有毒武器、生物武器、化学武器被国际法绝对禁止。核武器的使用在国际法院咨询意见中被认为原则上受国际人道法约束，但尚未被全面禁止。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于”区分原则”，下列哪项正确？",opts:["战斗员可以随意选择攻击目标","冲突各方必须始终区分军事目标与民用物体","平民可以随意进入军事区域","区分原则仅适用于国际性武装冲突"],ans:1,exp:"区分原则要求冲突各方始终区分军事目标与民用物体、战斗员与平民。这是国际人道法的基本原则，适用于所有武装冲突。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于日内瓦四公约的”共同第三条”，下列哪项正确？",opts:["仅适用于国际性武装冲突","适用于非国际性武装冲突，规定最低人道标准","仅适用于海战","仅适用于空战"],ans:1,exp:"日内瓦四公约共同第三条适用于非国际性武装冲突（内战），规定了最基本的人道标准，如禁止谋杀、酷刑、劫持人质等。"},
    {chapter:"第九章 战争与武装冲突法",q:"关于战争罪，下列哪项正确？",opts:["战争罪仅适用于国际性武装冲突","战争罪可以由个人承担刑事责任","战争罪不需要与武装冲突有关联","战争罪只能由军事指挥官承担"],ans:1,exp:"战争罪可以由个人承担刑事责任，无论其是军事指挥官还是普通士兵。战争罪既适用于国际性武装冲突，也适用于非国际性武装冲突（《罗马规约》第8条）。"},
    {chapter:"第十章 国际刑法",q:"国际刑法的主要渊源不包括？",opts:["《罗马规约》","纽伦堡审判宪章","《联合国海洋法公约》","国际刑事法院规约"],ans:2,exp:"《联合国海洋法公约》主要调整海洋法问题，不是国际刑法的主要渊源。国际刑法的主要渊源包括《罗马规约》、纽伦堡审判宪章、前南斯拉夫问题国际刑事法庭规约等。"},
    {chapter:"第十章 国际刑法",q:"关于国际刑事法院（ICC），下列说法正确的是？",opts:["ICC具有普遍管辖权","ICC仅审理国家之间的争端","ICC对《罗马规约》缔约国移交的案件或检察官自行发起的调查具有管辖权","ICC可以审理个人与国家之间的争端"],ans:2,exp:"ICC的管辖权不是普遍性的，主要对《罗马规约》缔约国移交的案件或检察官自行发起的调查具有管辖权。ICC审理个人的国际刑事责任，不审理国家之间的争端。"},
    {chapter:"第十章 国际刑法",q:"下列哪项不属于《罗马规约》规定的ICC管辖权内的核心犯罪？",opts:["灭绝种族罪","危害人类罪","侵略罪","恐怖主义罪"],ans:3,exp:"《罗马规约》第5条规定的ICC管辖权内的核心犯罪包括：灭绝种族罪、危害人类罪、战争罪和侵略罪。恐怖主义罪尚未被纳入ICC的管辖权范围。"},
    {chapter:"第十章 国际刑法",q:"关于”危害人类罪”，下列哪项正确？",opts:["仅适用于战争期间","要求针对平民人口的广泛或有系统的攻击","仅指种族灭绝行为","不需要与国家政策有关联"],ans:1,exp:"危害人类罪要求针对任何平民人口进行的广泛或有系统的攻击，且明知此次攻击。根据《罗马规约》，危害人类罪不限于战争期间，和平时期也可以构成。"},
    {chapter:"第十章 国际刑法",q:"关于个人在国际刑法上的刑事责任，下列哪项正确？",opts:["个人只对其直接实施的行为负责","个人可以因上级命令而免除刑事责任","国家元首和政府首脑在国际刑法上不享有豁免","个人不承担国际刑事责任"],ans:2,exp:"根据《罗马规约》第27条，国家元首和政府首脑在国际刑法上不享有豁免。个人可以因上级命令而减轻刑罚，但不免除刑事责任。个人在国际刑法上承担刑事责任。"},
    {chapter:"第十章 国际刑法",q:"关于”侵略罪”，下列哪项正确？",opts:["侵略罪仅指武装攻击","侵略罪的定义由联合国大会确定","侵略罪是指策划、准备、发动或实施侵略行为的行为","侵略罪不适用于个人"],ans:2,exp:"《罗马规约》第8条之二规定，侵略罪是指策划、准备、发动或实施侵略行为的行为，且该行为须由处于能够策划、指挥或控制军事行动地位的个人实施。"},
    {chapter:"第十章 国际刑法",q:"关于前南斯拉夫问题国际刑事法庭（ICTY），下列说法正确的是？",opts:["ICTY是常设国际法院","ICTY仅审理战争罪","ICTY由联合国安理会设立，具有优先于国内法院的权力","ICTY的判决不能上诉"],ans:2,exp:"ICTY由联合国安理会根据第七章设立，是特设国际刑事法庭，具有优先于国内法院的权力（优先管辖权）。ICTY审理战争罪、危害人类罪、灭绝种族罪和违反战争法规与惯例罪。"},
    {chapter:"第十章 国际刑法",q:"关于”普遍管辖权”在国际刑法中的适用，下列哪项正确？",opts:["仅适用于海盗罪","各国可以对某些国际犯罪（如海盗、战争罪）行使管辖权，不论犯罪地或犯罪人国籍","普遍管辖权仅适用于国际法院","普遍管辖权已被国际法废除"],ans:1,exp:"普遍管辖权允许各国对某些被国际社会普遍认为严重的国际犯罪（如海盗罪、战争罪、危害人类罪、灭绝种族罪）行使管辖权，不论犯罪地或犯罪人国籍。海盗罪是最古老和公认的普遍管辖权适用对象。"},
    {chapter:"第十章 国际刑法",q:"关于国际刑事司法中的”不溯及既往”原则，下列哪项正确？",opts:["国际刑法不承认不溯及既往原则","国际刑法承认不溯及既往原则，但某些国际犯罪不受此限制","不溯及既往原则适用于所有国际犯罪","不溯及既往原则仅适用于国内法"],ans:1,exp:"纽伦堡审判确立了”不溯及既往”原则在国际刑法中的例外：某些国际犯罪（如反人类罪、战争罪）因其严重性，即使行为时未被国内法规定为犯罪，也应承担国际刑事责任。这体现了”法无明文规定不为罪”原则的例外。"},
    {chapter:"第十章 国际刑法",q:"关于国际刑事法院与联合国安理会的关系，下列哪项正确？",opts:["ICC完全独立于联合国","安理会可以向ICC移交情势","安理会可以否决ICC的判决","ICC的检察官由安理会任命"],ans:1,exp:"根据《罗马规约》第13条，安理会可以根据《联合国宪章》第七章向ICC检察官移交情势。安理会还可以根据第16条请求ICC在12个月内不发起调查或起诉，但这不是否决判决。ICC在组织上独立于联合国，但与联合国有特殊合作安排。"},
  ],

  "刑事诉讼法": [
{chapter:"第五章  回避",q:"下列关于回避制度的说法，正确的是？",opts:["回避制度仅适用于审判人员","回避制度适用于审判人员、检察人员和侦查人员","当事人没有申请回避的权利","回避申请只能由当事人提出"],ans:1,exp:"根据《刑事诉讼法》第29条至第31条，回避制度适用于审判人员、检察人员、侦查人员，以及书记员、翻译人员和鉴定人。"},
    {chapter:"第五章  回避",q:"下列哪些情形应当适用回避？",opts:["是本案的当事人或者是当事人的近亲属的","本人或者他的近亲属和本案有利害关系的","担任过本案的证人、鉴定人、辩护人、诉讼代理人的","与本案当事人有其他关系，可能影响公正处理案件的"],ans:[0,1,2,3],multi:true,exp:"根据《刑事诉讼法》第29条，以上情形均应当回避。"},
    {chapter:"第五章  回避",q:"当事人申请回避的，在回避决定作出前，被申请回避的人员应当？",opts:["继续参与案件办理","暂停参与案件办理，但侦查人员除外","自动回避","由法院决定是否暂停"],ans:1,exp:"对侦查人员的回避作出决定前，侦查人员不能停止对案件的侦查。"},
    {chapter:"第五章  回避",q:"下列关于回避决定的权限，正确的有？",opts:["审判人员的回避由院长决定","检察人员的回避由检察长决定","侦查人员的回避由公安机关负责人决定","院长的回避由审判委员会决定"],ans:[0,1,2,3],multi:true,exp:"根据《刑事诉讼法》第31条，以上决定权限均正确。"},
    {chapter:"第五章  回避",q:"对驳回申请回避的决定，可以申请复议几次？",opts:["一次","两次","三次","无数次"],ans:0,exp:"对驳回申请回避的决定，可以申请复议一次。"},
    {chapter:"第五章  回避",q:"下列哪些人员适用回避制度？",opts:["审判员","人民陪审员","书记员","翻译人员"],ans:[0,1,2,3],multi:true,exp:"根据《刑事诉讼法》第31条，以上人员均适用回避制度。"},
    {chapter:"第五章  回避",q:"审判人员违反规定会见当事人及其委托的人的，当事人有权？",opts:["要求改判","申请其回避","提起上诉","申请再审"],ans:1,exp:"根据《刑事诉讼法》第30条，当事人有权申请其回避。"},
    {chapter:"第五章  回避",q:"下列关于回避的程序，正确的有？",opts:["回避申请可以在法庭审理过程中提出","回避申请应当说明理由","对回避决定不服的，可以申请复议一次","回避决定作出前，所有诉讼参与人都必须暂停工作"],ans:[0,1,2],multi:true,exp:"D错误，侦查人员的回避决定作出前，侦查活动不停止。"},
    {chapter:"第五章  回避",q:"检察长和公安机关负责人的回避，由谁决定？",opts:["同级人民法院审判委员会","同级人民检察院检察委员会","上级人民检察院","上级公安机关"],ans:1,exp:"检察长和公安机关负责人的回避，由同级人民检察院检察委员会决定。"},
    {chapter:"第五章  回避",q:"下列关于回避的说法，错误的有？",opts:["辩护人可以申请审判人员回避","证人可以申请回避","被害人可以申请鉴定人回避","附带民事诉讼原告人可以申请书记员回避"],ans:[0,1],multi:true,exp:"申请回避的主体是当事人及其法定代理人。辩护人不能独立申请回避。证人不是回避的适用对象。"},
    {chapter:"第六章  辩护与代理",q:"犯罪嫌疑人自何时起有权委托辩护人？",opts:["自被侦查机关第一次讯问或者采取强制措施之日起","自案件移送审查起诉之日起","自案件被起诉到法院之日起","自判决生效之日起"],ans:0,exp:"根据《刑事诉讼法》第34条第1款，自被第一次讯问或者采取强制措施之日起有权委托辩护人。"},
    {chapter:"第六章  辩护与代理",q:"下列哪些人可以被委托为辩护人？",opts:["律师","人民团体或者所在单位推荐的人","犯罪嫌疑人、被告人的监护人、亲友","正在被执行刑罚的人"],ans:[0,1,2],multi:true,exp:"正在被执行刑罚的人不得担任辩护人。D错误。"},
    {chapter:"第六章  辩护与代理",q:"在侦查期间，犯罪嫌疑人只能委托谁作为辩护人？",opts:["律师","亲友","监护人","所在单位推荐的人"],ans:0,exp:"在侦查期间，只能委托律师作为辩护人。"},
    {chapter:"第六章  辩护与代理",q:"下列关于值班律师制度的说法，正确的有？",opts:["值班律师可以为犯罪嫌疑人、被告人提供法律帮助","值班律师可以代为申请变更强制措施","值班律师可以提出量刑建议","值班律师可以代为认罪认罚"],ans:[0,1],multi:true,exp:"值班律师不是辩护人，不能代为认罪认罚，也不能提出量刑建议。CD错误。"},
    {chapter:"第六章  辩护与代理",q:"辩护律师在侦查期间可以从事的活动是？",opts:["查阅、摘抄、复制本案的案卷材料","会见在押的犯罪嫌疑人，了解案件有关情况","自行调查取证","参加法庭辩论"],ans:1,exp:"查阅案卷材料是在案件移送审查起诉之日起。C、D属于后续阶段的活动。"},
    {chapter:"第六章  辩护与代理",q:"下列哪些案件中，没有委托辩护人的，公检法应当通知法律援助机构指派律师？",opts:["盲、聋、哑人","尚未完全丧失辨认或者控制自己行为能力的精神病人","可能被判处无期徒刑、死刑的人","经济困难的犯罪嫌疑人"],ans:[0,1,2],multi:true,exp:"D属于'可以'通知指派的情形，不是'应当'。"},
    {chapter:"第六章  辩护与代理",q:"辩护律师会见在押的犯罪嫌疑人、被告人时，可以了解的主要内容是？",opts:["案件的证据情况","案件有关情况","同案犯的供述","被害人的陈述"],ans:1,exp:"辩护律师可以会见在押的犯罪嫌疑人、被告人，了解案件有关情况。"},
    {chapter:"第六章  辩护与代理",q:"下列关于辩护律师执业权利的说法，正确的有？",opts:["辩护律师会见在押的犯罪嫌疑人、被告人，不被监听","辩护律师自案件移送审查起诉之日起，可以查阅、摘抄、复制本案案卷材料","辩护律师可以申请人民检察院、人民法院收集、调取证据","辩护律师在审判阶段可以自行向证人收集材料"],ans:[0,1,2],multi:true,exp:"D错误，辩护律师向证人收集材料需经证人同意或申请检察院、法院收集调取。"},
    {chapter:"第六章  辩护与代理",q:"刑事代理的委托主体不包括？",opts:["公诉案件的被害人及其法定代理人或者近亲属","自诉案件的自诉人及其法定代理人","附带民事诉讼的当事人及其法定代理人","犯罪嫌疑人、被告人"],ans:3,exp:"犯罪嫌疑人、被告人委托的是'辩护人'而非'诉讼代理人'。"},
    {chapter:"第六章  辩护与代理",q:"下列关于辩护人权利义务的說法，正确的有？",opts:["辩护律师自案件移送审查起诉之日起，可以向犯罪嫌疑人、被告人核实有关证据","辩护律师在执业活动中知悉的委托人有关情况和信息，有权予以保密","辩护律师发现委托人正在实施新的犯罪，应当立即向司法机关报告","辩护律师不得帮助犯罪嫌疑人、被告人隐匿、毁灭、伪造证据"],ans:[0,1,3],multi:true,exp:"C错误，保密义务例外仅限危害国家安全、公共安全以及严重危害他人人身安全的犯罪。"},
    {chapter:"第七章  证据与证明",q:"根据《刑事诉讼法》，下列哪项不属于法定证据种类？",opts:["物证","视听资料","专家意见","电子数据"],ans:2,exp:"法定证据种类包括物证、书证、证人证言、被害人陈述、犯罪嫌疑人被告人供述和辩解、鉴定意见、勘验检查辨认侦查实验笔录、视听资料电子数据。'专家意见'不是法定证据种类。"},
    {chapter:"第七章  证据与证明",q:"下列哪些属于非法言词证据，应当予以排除？",opts:["采用刑讯逼供方法收集的犯罪嫌疑人供述","采用暴力方法收集的证人证言","采用威胁方法收集的被害人陈述","采用引诱方法收集的犯罪嫌疑人供述"],ans:[0,1,2,3],multi:true,exp:"根据《刑事诉讼法》第56条，采用刑讯逼供等非法方法收集的供述和采用暴力、威胁等非法方法收集的证言、陈述，应当予以排除。"},
    {chapter:"第七章  证据与证明",q:"关于非法实物证据的排除，下列说法正确的是？",opts:["所有非法收集的物证、书证都应当排除","收集物证、书证不符合法定程序，可能严重影响司法公正的，应当予以排除","收集物证、书证不符合法定程序，可能严重影响司法公正的，应当予以补正或者作出合理解释；不能补正或者作出合理解释的，对该证据应当予以排除","非法收集的物证、书证一律不得作为定案根据"],ans:2,exp:"实物证据采取'裁量排除'规则，先补正或解释，不能补正或解释的才排除。"},
    {chapter:"第七章  证据与证明",q:"下列关于证明责任的说法，正确的有？",opts:["公诉案件中被告人有罪的举证责任由人民检察院承担","自诉案件中自诉人应当证明被告人有罪","被告人一般不承担证明自己无罪的责任","巨额财产来源不明案件中，被告人应当说明财产来源"],ans:[0,1,2,3],multi:true,exp:"A、B、C正确。D正确，巨额财产来源不明罪是举证责任倒置的特殊情形。"},
    {chapter:"第七章  证据与证明",q:"刑事诉讼中认定被告人有罪的证明标准是？",opts:["有犯罪嫌疑","高度盖然性","证据确实、充分，排除合理怀疑","优势证据"],ans:2,exp:"根据《刑事诉讼法》第55条，认定被告人有罪必须证据确实、充分并排除合理怀疑。"},
    {chapter:"第七章  证据与证明",q:"下列哪些情形下，应当排除相关证据？",opts:["侦查人员刑讯逼供获取的被告人有罪供述","侦查人员威胁证人获取的证人证言","侦查人员依照法定程序收集但未签名的讯问笔录","侦查人员非法搜查获取的毒品"],ans:[0,1],multi:true,exp:"A、B属于非法言词证据，应当绝对排除。C属于程序瑕疵可补正。D属于非法实物证据，适用裁量排除。"},
    {chapter:"第七章  证据与证明",q:"下列关于鉴定人的说法，正确的是？",opts:["鉴定人可以是自然人也可以是单位","鉴定人适用回避制度","鉴定意见不需要鉴定人出庭作证","鉴定人没有权利了解与鉴定有关的案件材料"],ans:1,exp:"鉴定人适用回避制度。鉴定人必须是自然人，经法院通知应当出庭作证。"},
    {chapter:"第七章  证据与证明",q:"下列关于证人证言的说法，正确的有？",opts:["不能辨别是非、不能正确表达的人，不能作证人","证人证言必须在法庭上经过双方质证并且查实以后，才能作为定案的根据","了解案件情况的人有作证的义务","证人的近亲属可以不出庭作证"],ans:[0,1,2],multi:true,exp:"D错误，近亲属关系不是不出庭的法定理由。"},
    {chapter:"第七章  证据与证明",q:"关于电子数据，下列说法正确的是？",opts:["电子数据不是法定证据种类","电子数据收集程序不符合法定程序一律排除","电子数据包括电子邮件、即时通讯信息、博客、微博客等","电子数据不需要原件，复印件即可"],ans:2,exp:"电子数据是法定证据种类，包括电子邮件、即时通讯、博客微博等。"},
    {chapter:"第七章  证据与证明",q:"下列关于'印证规则'的说法，正确的有？",opts:["只有被告人供述，没有其他证据的，不能认定被告人有罪","没有被告人供述，证据确实、充分的，可以认定被告人有罪","口供必须得到其他证据印证才能作为定案根据","孤立的证人证言不能单独作为定案根据"],ans:[0,1,2],multi:true,exp:"根据《刑事诉讼法》第55条，ABC正确。D错误，孤立的证人证言在特定条件下可以单独作为定案根据。"},
    {chapter:"第八章  强制措施",q:"下列哪种强制措施不需要经过人民检察院或者人民法院决定？",opts:["取保候审","监视居住","刑事拘留","逮捕"],ans:2,exp:"刑事拘留由公安机关决定并执行，不需要检察院或法院决定。"},
    {chapter:"第八章  强制措施",q:"下列关于取保候审的说法，正确的有？",opts:["取保候审最长不得超过12个月","取保候审可以由公安机关执行","被取保候审人未经执行机关批准不得离开所居住的市、县","取保候审只能提供保证金保证"],ans:[0,1,2],multi:true,exp:"D错误，取保候审可以要求提出保证人或者交纳保证金，二者择一。"},
    {chapter:"第八章  强制措施",q:"监视居住的执行地点是？",opts:["指定的居所","犯罪嫌疑人、被告人的住处","看守所","拘留所"],ans:1,exp:"监视居住应当在犯罪嫌疑人、被告人的住处执行；无固定住处的，可以在指定的居所执行。"},
    {chapter:"第八章  强制措施",q:"下列关于逮捕的条件，正确的有？",opts:["有证据证明有犯罪事实","可能判处徒刑以上刑罚","采取取保候审尚不足以防止发生社会危险性","可能判处拘役以上刑罚"],ans:[0,1,2],multi:true,exp:"D错误，应为'徒刑以上'而非'拘役以上'。"},
    {chapter:"第八章  强制措施",q:"人民检察院对公安机关提请批准逮捕的案件进行审查后，应当在规定期限内作出决定。该期限是？",opts:["3日","7日","10日","14日"],ans:1,exp:"人民检察院应当自接到提请批准逮捕书后的七日以内作出决定。"},
    {chapter:"第八章  强制措施",q:"下列关于刑事拘留期限的说法，正确的有？",opts:["公安机关对被拘留的人，认为需要逮捕的，应当在拘留后的3日以内提请审查批准","在特殊情况下，提请审查批准的时间可以延长1日至4日","对于流窜作案、多次作案、结伙作案的重大嫌疑分子，提请审查批准的时间可以延长至30日","刑事拘留的最长期限为37日"],ans:[0,1,2,3],multi:true,exp:"一般3日+特殊4日+流窜多次结伙30日，加上检察院7日审查批捕时间，最长37日。"},
    {chapter:"第八章  强制措施",q:"被羁押的犯罪嫌疑人及其法定代理人、近亲属申请变更强制措施的，应当在多少时间内作出决定？",opts:["24小时","48小时","3日","7日"],ans:2,exp:"收到变更强制措施申请后，应当在3日以内作出决定。"},
    {chapter:"第八章  强制措施",q:"下列哪些情形下，可以对犯罪嫌疑人、被告人采取取保候审？",opts:["可能判处管制、拘役或者独立适用附加刑的","可能判处有期徒刑以上刑罚，采取取保候审不致发生社会危险性的","患有严重疾病、生活不能自理的","怀孕或者正在哺乳自己婴儿的妇女"],ans:[0,1,2,3],multi:true,exp:"根据《刑事诉讼法》第67条，以上情形均可以取保候审。"},
    {chapter:"第八章  强制措施",q:"关于强制措施的变更，下列说法正确的是？",opts:["只有人民法院有权变更强制措施","只有人民检察院有权变更强制措施","人民法院、人民检察院和公安机关都有权依法变更强制措施","强制措施一旦决定，不得变更"],ans:2,exp:"人民法院、人民检察院和公安机关都有权依法变更强制措施。"},
    {chapter:"第八章  强制措施",q:"下列关于监视居住的执行，正确的有？",opts:["监视居住由公安机关执行","被监视居住人未经执行机关批准不得会见他人","被监视居住人违反规定，情节严重的，可以予以逮捕","监视居住最长不得超过6个月"],ans:[0,2],multi:true,exp:"B错误，不得会见'特定的人'而非'他人'。D错误，监视居住最长不得超过6个月（正确）。等等，D是正确的！监视居住最长不得超过6个月。所以ACD正确。"},
    {chapter:"第十四章  第一审程序",q:"人民法院审理公诉案件，应当在受理后多长时间内宣判？",opts:["1个月以内","1个半月以内","2个月以内","3个月以内"],ans:2,exp:"根据《刑事诉讼法》第208条，应当在受理后二个月以内宣判，至迟不得超过三个月。"},
    {chapter:"第十四章  第一审程序",q:"下列关于一审公诉案件庭审程序的顺序，正确的是？",opts:["法庭调查→法庭辩论→被告人最后陈述→评议和宣判","法庭辩论→法庭调查→被告人最后陈述→评议和宣判","法庭调查→被告人最后陈述→法庭辩论→评议和宣判","被告人最后陈述→法庭调查→法庭辩论→评议和宣判"],ans:[0],multi:true,exp:"庭审程序顺序为：法庭调查→法庭辩论→被告人最后陈述→合议庭评议→宣判。"},
    {chapter:"第十四章  第一审程序",q:"关于简易程序，下列说法正确的是？",opts:["简易程序只适用于基层人民法院","简易程序可以由审判员一人独任审判，也可以由合议庭审判","适用简易程序的案件，被告人可以不认罪","简易程序不受审理期限的限制"],ans:0,exp:"简易程序由基层人民法院管辖。可能判处三年以下的可以独任审判，超过三年的应当组成合议庭。适用简易程序的前提是被告人认罪。"},
    {chapter:"第十四章  第一审程序",q:"下列关于速裁程序的说法，正确的有？",opts:["速裁程序只适用于基层人民法院","速裁程序应当在受理后十日以内审结","速裁程序可以当庭宣判","速裁程序不需要听取被告人的最后陈述"],ans:[0,1,2],multi:true,exp:"速裁程序应当当庭宣判，且被告人最后陈述权不可剥夺。D错误。"},
    {chapter:"第十四章  第一审程序",q:"在法庭审判过程中，合议庭发现新的可能影响定罪量刑的事实，应当如何处理？",opts:["继续审理并直接判决","建议人民检察院补充起诉或补充侦查","中止审理","延期审理"],ans:1,exp:"合议庭发现新的可能影响定罪量刑的事实，应当建议人民检察院补充起诉或补充侦查。"},
    {chapter:"第十四章  第一审程序",q:"下列关于自诉案件一审程序的说法，正确的有？",opts:["自诉案件可以适用简易程序","自诉案件在判决宣告前，自诉人可以同被告人自行和解","自诉案件可以调解","自诉人经两次依法传唤，无正当理由拒不到庭的，按撤诉处理"],ans:[0,1,3],multi:true,exp:"C不完全正确，公诉转自诉的案件不适用调解。"},
    {chapter:"第十四章  第一审程序",q:"关于认罪认罚从宽制度在一审程序中的适用，下列说法正确的是？",opts:["认罪认罚案件不能适用简易程序","认罪认罚案件检察院应当提出量刑建议","认罪认罚案件法院不能调整量刑建议","认罪认罚案件不需要开庭审理"],ans:1,exp:"根据《刑事诉讼法》第201条，对于认罪认罚案件，人民检察院应当提出量刑建议。"},
    {chapter:"第十四章  第一审程序",q:"下列关于'延期审理'和'中止审理'的区别，正确的有？",opts:["延期审理的原因消除后，恢复审理，延期的时间计入审理期限","中止审理的原因消除后，恢复审理，中止审理的期间不计入审理期限","延期审理适用于暂时无法继续审理的情形","中止审理适用于较长时间无法继续审理的情形"],ans:[1,2,3],multi:true,exp:"A错误，延期审理的时间计入审理期限。B正确，中止审理期间不计入审理期限。"},
    {chapter:"第十四章  第一审程序",q:"人民法院在一审中认定指控的犯罪事实清楚，证据确实、充分，但指控的罪名与法院认定的罪名不一致的，应当？",opts:["裁定驳回起诉","建议人民检察院变更起诉","直接按照法院认定的罪名判决","退回人民检察院补充侦查"],ans:2,exp:"法院认为指控罪名与认定罪名不一致的，应当按照法院认定的罪名作出有罪判决。"},
    {chapter:"第十四章  第一审程序",q:"下列关于一审程序中被告人最后陈述权的说法，正确的有？",opts:["被告人最后陈述是庭审的必经程序","被告人可以委托辩护人在最后陈述时代为陈述","被告人最后陈述时发表煽动性言论的，审判长应当警告制止","被告人最后陈述权不可剥夺"],ans:[0,2,3],multi:true,exp:"B错误，最后陈述必须由被告人本人进行，不能由辩护人代为陈述。"},
    {chapter:"第十五章  第二审程序",q:"第二审人民法院审理上诉案件，原则上应当？",opts:["书面审理","开庭审理","由审判员三人至五人组成合议庭进行审理","由审判员和人民陪审员组成合议庭进行审理"],ans:2,exp:"二审上诉案件应当组成合议庭审理。事实清楚的可以不开庭审理。"},
    {chapter:"第十五章  第二审程序",q:"下列关于'上诉不加刑'原则的说法，正确的有？",opts:["只有被告人一方上诉的案件，第二审法院不得加重被告人的刑罚","人民检察院提出抗诉的案件，不受上诉不加刑原则的限制","自诉人提出上诉的案件，不受上诉不加刑原则的限制","被告人上诉后，第二审法院发回重审的案件，原审法院也不得加重刑罚"],ans:[0,1,2],multi:true,exp:"D错误，发回重审后如果有新的事实证据，原审法院可以加重刑罚。"},
    {chapter:"第十五章  第二审程序",q:"第二审人民法院发现第一审人民法院的审理违反公开审判规定的，应当？",opts:["裁定驳回上诉","查清事实后改判","裁定撤销原判，发回原审人民法院重新审判","指令下级法院再审"],ans:2,exp:"违反公开审判规定的，应当裁定撤销原判，发回重审。"},
    {chapter:"第十五章  第二审程序",q:"下列关于第二审程序的审理方式，正确的有？",opts:["对上诉案件，应当组成合议庭","经过阅卷、讯问被告人、听取其他当事人意见后，事实清楚的，可以不开庭审理","检察院抗诉的案件，应当开庭审理","被告人被判处死刑的上诉案件，应当开庭审理"],ans:[0,1,2,3],multi:true,exp:"根据《刑事诉讼法》第234条，以上说法均正确。"},
    {chapter:"第十五章  第二审程序",q:"第二审人民法院审理上诉案件，原判决认定事实没有错误，但适用法律有错误，或者量刑不当的，应当？",opts:["裁定撤销原判，发回重审","裁定驳回上诉，维持原判","撤销原判，依法改判","指令下级法院再审"],ans:2,exp:"原判决认定事实没有错误，但适用法律有错误或量刑不当的，应当撤销原判，依法改判。"},
    {chapter:"第十五章  第二审程序",q:"下列关于第二审程序的期限，正确的有？",opts:["第二审人民法院受理上诉、抗诉案件，应当在二个月以内审结","可能判处死刑的案件可以延长二个月","经最高人民法院批准，可以延长二个月","第二审程序的期限从第二审法院受理案件之日起计算"],ans:[0,1,2,3],multi:true,exp:"根据《刑事诉讼法》第243条，以上说法均正确。"},
    {chapter:"第十五章  第二审程序",q:"人民检察院认为人民法院第一审判决确有错误，提出抗诉的，应当向哪个法院提出？",opts:["原审人民法院","上一级人民法院","同级人民法院","最高人民法院"],ans:1,exp:"地方各级人民检察院认为本级人民法院第一审判决确有错误的，应当向上一级人民法院提出抗诉。"},
    {chapter:"第十五章  第二审程序",q:"下列关于第二审法院全面审查原则的说法，正确的有？",opts:["第二审法院应当对第一审判决认定的事实和适用法律进行全面审查","不受上诉或者抗诉范围的限制","共同犯罪案件，只有部分被告人上诉的，应当对全案进行审查","共同犯罪案件，只有部分被告人上诉的，只审查上诉被告人的部分"],ans:[0,1,2],multi:true,exp:"根据《刑事诉讼法》第233条，二审应当全面审查，不受上诉或抗诉范围限制。D错误。"},
    {chapter:"第十五章  第二审程序",q:"第二审人民法院审理上诉案件，认为原判决事实不清、证据不足的，可以如何处理？",opts:["只能查清事实后改判","只能裁定撤销原判，发回重审","可以查清事实后改判，也可以裁定撤销原判，发回重审","应当裁定驳回上诉"],ans:2,exp:"原判决事实不清楚或者证据不足的，可以在查清事实后改判，也可以发回重审。"},
    {chapter:"第十五章  第二审程序",q:"下列关于第二审判决效力的说法，正确的有？",opts:["第二审的判决、裁定，是终审的判决、裁定","第二审判决一经作出即发生法律效力","第二审判决生效后，被告人不得再上诉","第二审判决生效后，被告人可以申请再审"],ans:[0,1,2,3],multi:true,exp:"二审判决是终审判决，一经作出即生效，不得上诉。但符合法定条件的可以申请再审（审判监督程序）。"},
  ]
};
